import { Tabs } from 'expo-router';
import React from 'react';
import { View, StyleSheet, Platform } from 'react-native';
import { BlurView } from 'expo-blur';
import Animated, {
  useAnimatedStyle, withSpring, useSharedValue, withTiming, withRepeat,
} from 'react-native-reanimated';
import { LinearGradient } from 'expo-linear-gradient';
import {
  Newspaper, Film, Clapperboard, User,
} from 'lucide-react-native';
import { ReelEyeIcon } from '@/src/components/ReelEyeIcon';
import { HapticTab } from '@/src/components/HapticTab';
import { colors, fonts, effects } from '@/src/theme/theme';
import { TopNavBar } from '@/src/components/layout/TopNavBar';
import { useNotificationStore } from '@/src/stores/social';

// ════════════════════════════════════════════════════════════════
//  TAB ICON — Icons only. No labels. Pure cinema.
//
//  - Clean Lucide icons sized for clarity
//  - Spring-animated scale + opacity
//  - Gradient dot indicator below active icon
//  - Center tab (Lobby) elevated with warm flicker glow
// ════════════════════════════════════════════════════════════════
function TabIcon({
  IconComponent,
  focused,
  isCenter = false,
  hasNotification = false,
}: {
  IconComponent: typeof Newspaper;
  focused: boolean;
  isCenter?: boolean;
  hasNotification?: boolean;
}) {
  const scale = useSharedValue(1);
  const iconOpacity = useSharedValue(0.35);
  const badgeAlpha = useSharedValue(0.4);

  React.useEffect(() => {
    badgeAlpha.value = withRepeat(
      withTiming(1, { duration: 1800 }),
      -1,
      true
    );
  }, []);

  const badgeAlphaStyle = useAnimatedStyle(() => ({
    opacity: badgeAlpha.value,
  }));

  React.useEffect(() => {
    scale.value = withSpring(focused ? 1.15 : 1, {
      damping: 15,
      stiffness: 220,
      mass: 0.5,
    });
    iconOpacity.value = withTiming(focused ? 1 : 0.35, { duration: 200 });
  }, [focused]);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
    opacity: iconOpacity.value,
  }));

  const iconColor = focused
    ? (isCenter ? colors.flicker : colors.sepia)
    : colors.bone;
  const iconSize = isCenter ? 26 : 22;
  const strokeW = focused ? 2 : 1.5;

  return (
    <View style={s.tabIconRoot}>
      <Animated.View style={[s.tabIconInner, animatedStyle]}>
        <IconComponent
          size={iconSize}
          color={iconColor}
          strokeWidth={strokeW}
        />
      </Animated.View>

      {/* Nitrate Noir Breathing Ember Notification Badge */}
      {hasNotification && !focused && (
        <Animated.View style={[s.badgeDot, badgeAlphaStyle]} pointerEvents="none">
          <View style={s.badgeDotInner} />
        </Animated.View>
      )}

      {/* Active indicator — tiny gradient dot */}
      <View style={s.indicatorSlot}>
        {focused && (
          <View style={[
            s.indicatorDot,
            { backgroundColor: isCenter ? colors.flicker : colors.sepia },
            isCenter && s.centerGlow,
          ]} />
        )}
      </View>
    </View>
  );
}

function LobbyTabIcon({ focused }: { focused: boolean }) {
  const scale = useSharedValue(1);
  const iconOpacity = useSharedValue(0.35);

  React.useEffect(() => {
    scale.value = withSpring(focused ? 1.15 : 1, {
      damping: 15,
      stiffness: 220,
      mass: 0.5,
    });
    iconOpacity.value = withTiming(focused ? 1 : 0.35, { duration: 200 });
  }, [focused]);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
    opacity: iconOpacity.value,
  }));

  const iconColor = focused ? colors.flicker : colors.bone;
  return (
    <View style={s.tabIconRoot}>
      <Animated.View style={[s.tabIconInner, animatedStyle]}>
        <ReelEyeIcon
          size={26}
          color={iconColor}
          strokeWidth={focused ? 2 : 1.5}
        />
      </Animated.View>
      <View style={s.indicatorSlot}>
        {focused && (
          <View style={[
            s.indicatorDot,
            { backgroundColor: colors.flicker },
            s.centerGlow,
          ]} />
        )}
      </View>
    </View>
  );
}

// ════════════════════════════════════════════════════════════════
//  TAB BAR BACKGROUND — Frosted ink glass
// ════════════════════════════════════════════════════════════════
function TabBarBackground() {
  return (
    <View style={StyleSheet.absoluteFill}>
      <View style={[StyleSheet.absoluteFill, s.tabBarBg]} />
      <BlurView
        intensity={Platform.OS === 'ios' ? 45 : 90}
        tint="dark"
        style={StyleSheet.absoluteFill}
      />
      {/* Sepia gradient border at top */}
      <LinearGradient
        colors={['transparent', 'rgba(196,150,26,0.1)', 'transparent']}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 0 }}
        style={s.topBorder}
      />
    </View>
  );
}

// ════════════════════════════════════════════════════════════════
//  TAB LAYOUT
//  Dispatch • The Reel • LOBBY • Darkroom • Profile
// ════════════════════════════════════════════════════════════════
export default function TabLayout() {
  const unreadCount = useNotificationStore((s) => s._unreadCount);

  return (
    <Tabs
      screenOptions={{
        header: () => <TopNavBar />,
        headerTransparent: true,
        headerShown: true,
        tabBarButton: HapticTab,
        tabBarStyle: s.tabBar,
        tabBarBackground: () => <TabBarBackground />,
        tabBarShowLabel: false,
        tabBarActiveTintColor: colors.sepia,
        tabBarInactiveTintColor: colors.fog,
        animation: 'fade',
        lazy: true,
      }}
    >
      <Tabs.Screen
        name="dispatch"
        options={{
          title: 'Dispatch',
          tabBarIcon: ({ focused }) => (
            <TabIcon IconComponent={Newspaper} focused={focused} hasNotification={unreadCount > 0} />
          ),
        }}
      />

      <Tabs.Screen
        name="reels"
        options={{
          title: 'The Reel',
          tabBarIcon: ({ focused }) => (
            <TabIcon IconComponent={Film} focused={focused} />
          ),
        }}
      />

      <Tabs.Screen
        name="index"
        options={{
          title: 'Lobby',
          tabBarIcon: ({ focused }) => (
            <LobbyTabIcon focused={focused} />
          ),
        }}
      />

      <Tabs.Screen
        name="darkroom"
        options={{
          title: 'Darkroom',
          tabBarIcon: ({ focused }) => (
            <TabIcon IconComponent={Clapperboard} focused={focused} />
          ),
        }}
      />

      <Tabs.Screen
        name="profile"
        options={{
          title: 'Profile',
          tabBarIcon: ({ focused }) => (
            <TabIcon IconComponent={User} focused={focused} />
          ),
        }}
      />

      <Tabs.Screen name="lounge" options={{ href: null }} />
      <Tabs.Screen name="ledger" options={{ href: null }} />
    </Tabs>
  );
}

// ════════════════════════════════════════════════════════════════
//  STYLES
// ════════════════════════════════════════════════════════════════
const BOTTOM_INSET = Platform.OS === 'ios' ? 28 : 10;

const s = StyleSheet.create({
  tabBar: {
    position: 'absolute',
    bottom: 0,
    left: 0,
    right: 0,
    height: 56 + BOTTOM_INSET,
    paddingBottom: BOTTOM_INSET,
    borderTopWidth: 0,
    elevation: 0,
    backgroundColor: 'transparent',
    shadowColor: '#000',
    shadowOffset: { width: 0, height: -6 },
    shadowOpacity: 0.5,
    shadowRadius: 16,
  },

  topBorder: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    height: StyleSheet.hairlineWidth * 2,
  },

  tabIconRoot: {
    alignItems: 'center',
    justifyContent: 'center',
    width: 56,
    height: 48,
    paddingTop: 4,
  },

  tabIconInner: {
    width: 32,
    height: 32,
    alignItems: 'center',
    justifyContent: 'center',
  },

  indicatorSlot: {
    height: 6,
    alignItems: 'center',
    justifyContent: 'center',
  },

  indicatorDot: {
    width: 4,
    height: 4,
    borderRadius: 2,
  },

  badgeDot: {
    position: 'absolute',
    top: 6,
    right: 12,
    width: 8,
    height: 8,
    borderRadius: 4,
    backgroundColor: colors.ink,
    alignItems: 'center',
    justifyContent: 'center',
    shadowColor: colors.bloodReel,
    shadowOffset: { width: 0, height: 0 },
    shadowOpacity: 0.6,
    shadowRadius: 4,
    elevation: 3,
  },

  badgeDotInner: {
    width: 6,
    height: 6,
    borderRadius: 3,
    backgroundColor: colors.bloodReel,
  },

  tabBarBg: {
    backgroundColor: 'rgba(11,10,8,0.88)',
  },

  centerGlow: {
    shadowColor: colors.flicker,
    shadowOffset: { width: 0, height: 0 },
    shadowOpacity: 0.8,
    shadowRadius: 6,
    elevation: 4,
  },
});

import React, { useEffect, useState, useRef, useCallback, useMemo } from 'react';
import { View, Text, StyleSheet } from 'react-native';
import { FlashList } from '@shopify/flash-list';
import Animated, { FadeInDown } from 'react-native-reanimated';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { useNetInfo } from '@react-native-community/netinfo';

import { colors, fonts, spacing } from '@/src/theme/theme';
import { tmdb } from '@/src/lib/tmdb';
import { useDiscoverStore, type DiscoverFilm } from '@/src/stores/discover';
import { setScrollY } from '@/src/utils/scrollBridge';

import Buster from '@/src/components/Buster';
import { EmptyOffline } from '@/src/components/EmptyStates';
import PressableScale from '@/src/components/PressableScale';
import FrozenTab from '@/src/components/layout/FrozenTab';

import { DarkroomHeader } from '@/src/components/darkroom/DarkroomHeader';
import { FilmGridCard, AnimatedPosterSkeleton } from '@/src/components/darkroom/DarkroomCards';

// === MAIN SCREEN ===
export default function DarkRoomScreen() {
  const insets = useSafeAreaInsets();
  const [loading, setLoading] = useState(false);
  const [filtersVisible, setFiltersVisible] = useState(false);
  const loadingRef = useRef(false);
  const network = useNetInfo();

  const {
    page, mood, query, accumulatedFilms, filters,
    setPage, setAccumulatedFilms
  } = useDiscoverStore();

  // Reset scroll bridge so NavBar returns to transparent on this tab
  useEffect(() => { setScrollY(0); }, []);

  const isSearching = !!query;

  // Memoize contentContainerStyle — insets are stable per session
  const listContentStyle = useMemo(
    () => ({ ...s.listContent, paddingTop: insets.top + 90 }),
    [insets.top]
  );

  // Stable onScroll reference to avoid FlashList re-subscribing per render
  const handleScroll = useCallback(
    (e: { nativeEvent: { contentOffset: { y: number } } }) => setScrollY(e.nativeEvent.contentOffset.y),
    []
  );

  // -- Main Fetching Logic --
  useEffect(() => {
    let active = true;
    const fetchContent = async () => {
      if (loadingRef.current) return;
      loadingRef.current = true;
      setLoading(true);
      try {
        let results = [];
        if (isSearching) {
          const res = await tmdb.search(query, page);
          results = res?.results ?? [];
        } else {
          const params: Record<string, string | number> = {
            sort_by: mood ? mood.sort : filters.sortBy,
            page,
            'vote_count.gte': mood?.voteGte ?? 20,
          };
          if (filters.genreId) params.with_genres = filters.genreId;
          else if (mood) params.with_genres = mood.genre;

          if (filters.yearFrom || filters.yearTo) {
            if (filters.yearFrom) params['primary_release_date.gte'] = `${filters.yearFrom}-01-01`;
            if (filters.yearTo) params['primary_release_date.lte'] = `${filters.yearTo}-12-31`;
          } else if (filters.decade) {
            params['primary_release_date.gte'] = filters.decade.from;
            params['primary_release_date.lte'] = filters.decade.to;
          }
          if (filters.language) params.with_original_language = filters.language;
          if (filters.minRating > 0) params['vote_average.gte'] = filters.minRating;

          const strParams: Record<string, string> = {};
          for (const [k, v] of Object.entries(params)) strParams[k] = String(v);
          const discoverRes = await tmdb.discover(strParams);
          results = discoverRes?.results ?? [];
        }

        if (active) {
          const withPosters = results.filter((f: DiscoverFilm) => f.poster_path || f.profile_path);
          if (page === 1) {
            setAccumulatedFilms(withPosters);
          } else {
            setAccumulatedFilms((prev: DiscoverFilm[]) => {
              const keys = new Set(prev.map(p => p.id));
              const merged = [...prev, ...withPosters.filter((f: DiscoverFilm) => !keys.has(f.id))];
              return merged.slice(0, 500);
            });
          }
        }
      } catch (error) {
        console.error(error);
      } finally {
        if (active) {
          setLoading(false);
          loadingRef.current = false;
        }
      }
    };
    fetchContent();
    return () => { active = false; };
  }, [query, page, filters, mood]);

  const renderFooter = useCallback(() => {
    if (loading && page > 1) {
      return (
        <View style={s.footerLoading}>
           <Animated.Text entering={FadeInDown} style={s.paginationRetrieving}>
             [ ACCESSING ARCHIVES... ]
           </Animated.Text>
        </View>
      );
    }
    return <View style={s.footerSpacer} />;
  }, [loading, page]);

  const { clearFilters: clearAllFilters, clearSearch: clearAllSearch } = useDiscoverStore();

  const renderEmpty = useMemo(() => {
    if (loading) {
      return (
        <View style={{ flexDirection: 'row', flexWrap: 'wrap', width: '100%' }}>
          {Array.from({ length: 21 }).map((_, i) => (
            <View key={i} style={{ width: '33.33%', padding: 4 }}>
              <AnimatedPosterSkeleton />
            </View>
          ))}
        </View>
      );
    }

    if (network.isConnected === false) {
      return (
        <Animated.View entering={FadeInDown.duration(600)} style={[s.emptyWrap, { flex: 1, paddingTop: 100 }]}>
           <EmptyOffline />
        </Animated.View>
      );
    }

    return (
      <Animated.View entering={FadeInDown.duration(600)} style={s.emptyWrap}>
        <PressableScale onPress={() => {}} haptic="light">
          <Buster size={56} mood="crying" />
        </PressableScale>
        <Text style={s.emptyTitle}>
          {isSearching ? 'The vault is sealed.' : 'No films surfaced.'}
        </Text>
        <Text style={s.emptySub}>
          {isSearching
            ? 'No films match that search. Try a different title.'
            : 'Adjust your filters to uncover something from the archive.'}
        </Text>
        <PressableScale
          style={s.emptyBtn}
          onPress={() => {
            if (isSearching) { clearAllSearch(); } else { clearAllFilters(); }
            setPage(1);
          }}
          haptic="medium"
        >
          <Text style={s.emptyBtnText}>
            {isSearching ? 'CLEAR SEARCH' : 'RESET FILTERS'}
          </Text>
        </PressableScale>
      </Animated.View>
    );
  }, [loading, network.isConnected, isSearching, clearAllFilters, clearAllSearch, setPage]);

  const renderFilmItem = useCallback(({ item }: { item: DiscoverFilm }) => (
    <View style={{ flex: 1, padding: 4 }}>
      <FilmGridCard item={item} />
    </View>
  ), []);

  const viewabilityConfig = useRef({
    minimumViewTime: 400,
    itemVisiblePercentThreshold: 80,
  }).current;

  const inflightFetches = useRef(new Set<number>());

  const onViewableItemsChanged = useRef(({ viewableItems }: { viewableItems: import('react-native').ViewToken[] }) => {
    if (inflightFetches.current.size > 200) {
      inflightFetches.current.clear();
    }
    viewableItems.forEach((vi) => {
      if (vi.item && vi.item.id && !inflightFetches.current.has(vi.item.id)) {
        inflightFetches.current.add(vi.item.id);
        tmdb.detail(vi.item.id)
          .catch(() => {})
          .finally(() => {
            setTimeout(() => { inflightFetches.current.delete(vi.item.id!); }, 10000);
          });
      }
    });
  }).current;

  return (
    <FrozenTab>
      <View style={s.container}>
        <FlashList
          data={accumulatedFilms}
          keyExtractor={(item) => String(item.id)}
          numColumns={3}
          contentContainerStyle={listContentStyle}
          ListHeaderComponent={<DarkroomHeader filtersVisible={filtersVisible} setFiltersVisible={setFiltersVisible} />}
          ListFooterComponent={renderFooter}
          ListEmptyComponent={renderEmpty}
          renderItem={renderFilmItem}
          onEndReached={() => {
            if (!loadingRef.current && accumulatedFilms.length > 0 && accumulatedFilms.length < 500) {
              setPage(useDiscoverStore.getState().page + 1);
            }
          }}
          onEndReachedThreshold={0.5}
          onScroll={handleScroll}
          scrollEventThrottle={32}
          keyboardShouldPersistTaps="handled"
          keyboardDismissMode="on-drag"
          viewabilityConfig={viewabilityConfig}
          onViewableItemsChanged={onViewableItemsChanged}
        />
      </View>
    </FrozenTab>
  );
}

