import { useEffect, useState, useCallback } from 'react';
import { PersistQueryClientProvider } from '@tanstack/react-query-persist-client';
import { queryClient, mmkvPersister } from '@/src/lib/queryClient';
import { SafeAreaProvider } from 'react-native-safe-area-context';
import { GestureHandlerRootView } from 'react-native-gesture-handler';
import { Stack } from 'expo-router';
import { StatusBar } from 'expo-status-bar';
import { View, StyleSheet } from 'react-native';
import { useFonts, Rye_400Regular } from '@expo-google-fonts/rye';
import { SpecialElite_400Regular } from '@expo-google-fonts/special-elite';
import { CourierPrime_400Regular, CourierPrime_700Bold, CourierPrime_400Regular_Italic } from '@expo-google-fonts/courier-prime';
import { Inter_400Regular, Inter_500Medium, Inter_700Bold } from '@expo-google-fonts/inter';
import * as SplashScreen from 'expo-splash-screen';
import * as Linking from 'expo-linking';
import { useRouter } from 'expo-router';
import { supabase } from '@/src/lib/supabase';
import { useAuthStore } from '@/src/stores/auth';
import { colors } from '@/src/theme/theme';
import Preloader from '@/src/components/Preloader';
import FilmGrainOverlay from '@/src/components/FilmGrainOverlay';
import { ToastOverlay } from '@/src/components/ToastOverlay';
import ErrorBoundary from '@/src/components/ErrorBoundary';
import OfflineBanner from '@/src/components/OfflineBanner';
import { initSentry, setSentryUser } from '@/src/lib/sentry';
import { initRevenueCat, identifyUser as identifyRevenueCatUser } from '@/src/lib/revenueCat';
import { registerForPushNotifications, setupNotificationResponseHandler } from '@/src/lib/pushNotifications';
import 'react-native-reanimated';
import Animated, { useSharedValue, useAnimatedStyle, withSequence, withTiming, withDelay } from 'react-native-reanimated';
import NetInfo from '@react-native-community/netinfo';
import { flushOfflineQueue } from '@/src/utils/offlineQueue';
import { LinearGradient } from 'expo-linear-gradient';

// Font scaling lock removed temporarily to prevent React Native Hermes segfault.
// Prevent splash from hiding until fonts + auth are ready
SplashScreen.preventAutoHideAsync();

export const unstable_settings = {
  anchor: '(tabs)',
};

export default function RootLayout() {
  const { restoreSession } = useAuthStore();
  const [appReady, setAppReady] = useState(false);
  const [showPreloader, setShowPreloader] = useState(true);

  const [fontsLoaded] = useFonts({
    Rye_400Regular,
    SpecialElite_400Regular,
    CourierPrime_400Regular,
    CourierPrime_700Bold,
    CourierPrime_400Regular_Italic,
    Inter_400Regular,
    Inter_500Medium,
    Inter_700Bold,
  });

  // Initialize Sentry before any rendering
  useEffect(() => { initSentry(); }, []);

  useEffect(() => {
    async function prepare() {
      try {
        await restoreSession();
        const currentUser = useAuthStore.getState().user;
        if (currentUser) {
            // ── Sentry User Context ──
            setSentryUser({ id: currentUser.id, username: currentUser.username ?? '', role: (currentUser.role as string) ?? 'cinephile' });

            // ── RevenueCat — IAP Entitlements ──
            await initRevenueCat(currentUser.id);
            identifyRevenueCatUser(currentUser.id);

            // ── Push Notifications — The Overnight Programme ──
            registerForPushNotifications(currentUser.id);

            // ── Real-time Notification Service — The "Live Wire" ──
            import('@/src/stores/social').then(({ useNotificationStore }) => {
                useNotificationStore.getState().setupRealtime();
            });
        }
      } catch {} finally {
        setAppReady(true);
      }
    }
    prepare();

    // The "Dead Drop" Engine
    // The moment the device touches a network, silently flush the encrypted drawer.
    const unsubscribeNet = NetInfo.addEventListener(state => {
      if (state.isConnected && state.isInternetReachable) {
        flushOfflineQueue();
      }
    });

    return () => {
      unsubscribeNet();
    };
  }, []);

  // ── Deep link handler for auth callbacks ──
  // Intercepts reelhouse://auth/callback and reelhouse://reset-password deep links
  useEffect(() => {
    function handleDeepLink(event: { url: string }) {
      handleAuthDeepLink(event.url);
    }

    // Handle the URL that launched the app (cold start)
    Linking.getInitialURL().then(url => {
      if (url) handleAuthDeepLink(url);
    });

    // Handle URLs while the app is already open (warm start)
    const subscription = Linking.addEventListener('url', handleDeepLink);
    return () => subscription.remove();
  }, [appReady]);

  async function handleAuthDeepLink(url: string) {
    if (!url) return;

    try {
      const parsed = Linking.parse(url);
      const path = parsed.path || '';
      const queryParams = parsed.queryParams || {};

      // Handle: reelhouse://auth/callback?token_hash=xxx&type=signup|recovery
      if (path.includes('auth/callback') || path.includes('auth-callback')) {
        const tokenHash = queryParams.token_hash as string;
        const type = queryParams.type as string;

        if (tokenHash && type) {
          // Route EVERYTHING to auth-callback so it can handle success, error, and recovery flows flawlessly
          setTimeout(() => {
            const router = require('expo-router').router;
            router.push({
              pathname: '/auth-callback',
              params: { token_hash: tokenHash, type },
            });
          }, 300);
        }
        return;
      }

      // Handle: reelhouse://reset-password (direct deep link)
      if (path.includes('reset-password')) {
        setTimeout(() => {
          const router = require('expo-router').router;
          router.push('/reset-password');
        }, 300);
        return;
      }
    } catch {
      // Deep link parsing failed — silently ignore
    }
  }

  const onLayoutReady = useCallback(async () => {
    if (appReady && fontsLoaded) {
      await SplashScreen.hideAsync();
    }
  }, [appReady, fontsLoaded]);

  if (!appReady || !fontsLoaded) return null;

  return (
    <SafeAreaProvider>
      <GestureHandlerRootView style={styles.root} onLayout={onLayoutReady}>
        <ErrorBoundary>
        <PersistQueryClientProvider
          client={queryClient}
          persistOptions={{ persister: mmkvPersister, maxAge: 24 * 60 * 60 * 1000 }}
        >
        <Stack
        screenOptions={{
          headerShown: false,
          contentStyle: { backgroundColor: colors.ink },
          animation: 'none', // Shutter-Cut Navigation: Instant mechanical cut
        }}
      >
        <Stack.Screen name="(tabs)" />
        <Stack.Screen name="film/[id]" options={{ animation: 'none' }} />
        <Stack.Screen name="person/[id]" options={{ animation: 'none' }} />
        <Stack.Screen name="lounge/[id]" options={{ animation: 'none' }} />
        <Stack.Screen name="user/[username]" options={{ animation: 'none' }} />
        <Stack.Screen name="settings" options={{ animation: 'none' }} />
        <Stack.Screen name="log/[id]" options={{ animation: 'none' }} />
        <Stack.Screen name="search-modal" options={{ presentation: 'modal', animation: 'fade', gestureEnabled: true, gestureDirection: 'vertical' }} />
        <Stack.Screen name="log-modal" options={{ presentation: 'modal', animation: 'slide_from_bottom', gestureEnabled: true, gestureDirection: 'vertical' }} />
        <Stack.Screen name="notifications-modal" options={{ presentation: 'modal', animation: 'slide_from_bottom', gestureEnabled: true, gestureDirection: 'vertical' }} />
        <Stack.Screen name="list-modal" options={{ presentation: 'modal', animation: 'slide_from_bottom', gestureEnabled: true, gestureDirection: 'vertical' }} />
        <Stack.Screen name="vault-modal" options={{ presentation: 'modal', animation: 'slide_from_bottom', gestureEnabled: true, gestureDirection: 'vertical' }} />
        <Stack.Screen name="login" options={{ presentation: 'modal', animation: 'slide_from_bottom', gestureEnabled: true, gestureDirection: 'vertical' }} />
        <Stack.Screen name="social-modal" options={{ presentation: 'modal', animation: 'slide_from_bottom', gestureEnabled: true, gestureDirection: 'vertical' }} />
        <Stack.Screen name="reset-password" options={{ animation: 'none' }} />
        <Stack.Screen name="auth-callback" options={{ animation: 'none' }} />
        <Stack.Screen name="membership" options={{ presentation: 'modal', animation: 'slide_from_bottom', gestureEnabled: true, gestureDirection: 'vertical' }} />
        <Stack.Screen name="oracle" options={{ presentation: 'modal', animation: 'slide_from_bottom', gestureEnabled: true, gestureDirection: 'vertical' }} />
        <Stack.Screen name="tribunal" options={{ animation: 'none' }} />
        <Stack.Screen name="year-in-cinema" options={{ animation: 'none' }} />
        <Stack.Screen name="stacks/[id]" options={{ animation: 'none' }} />
        <Stack.Screen name="film-reviews/[id]" options={{ animation: 'none' }} />
        <Stack.Screen name="dossier/[id]" options={{ animation: 'none' }} />
        <Stack.Screen name="edit-profile" options={{ animation: 'none' }} />
        <Stack.Screen name="dispatch/compose" options={{ presentation: 'modal', animation: 'slide_from_bottom', gestureEnabled: true, gestureDirection: 'vertical' }} />
      </Stack>
      </PersistQueryClientProvider>

      {showPreloader && <Preloader onComplete={() => setShowPreloader(false)} />}
      <FilmGrainOverlay />
      <ToastOverlay />
      <OfflineBanner />

      </ErrorBoundary>
      <StatusBar style="light" />
      </GestureHandlerRootView>
    </SafeAreaProvider>
  );
}

const styles = StyleSheet.create({
  root: {
    flex: 1,
    backgroundColor: colors.ink,
  },
});

import { useEffect, useState } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, ActivityIndicator } from 'react-native';
import Animated, { FadeIn, FadeInDown, ReduceMotion } from 'react-native-reanimated';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { supabase } from '@/src/lib/supabase';
import { useAuthStore } from '@/src/stores/auth';
import { colors, fonts, effects } from '@/src/theme/theme';
import type { EmailOtpType } from '@supabase/supabase-js';

const AnimatedView = Animated.createAnimatedComponent(View);

// ── AUTH CALLBACK SCREEN ──
// Handles deep links from Supabase email verification & password recovery.
// URL: reelhouse://auth/callback?token_hash=xxx&type=signup|recovery
export default function AuthCallbackScreen() {
  const router = useRouter();
  const params = useLocalSearchParams<{ token_hash?: string; type?: string }>();
  const [status, setStatus] = useState<'verifying' | 'success' | 'error'>('verifying');
  const [errorMsg, setErrorMsg] = useState('');

  useEffect(() => {
    handleCallback();
  }, []);

  async function handleCallback() {
    try {
      const tokenHash = params.token_hash;
      const type = params.type; // 'signup' | 'recovery' | 'email_change'

      if (!tokenHash || !type) {
        // Fallback: try to get an existing session
        const { data: sessionData } = await supabase.auth.getSession();
        if (sessionData?.session) {
          setStatus('success');
          setTimeout(() => router.replace('/(tabs)'), 2000);
        } else {
          throw new Error('No valid token found in this link. It may have expired.');
        }
        return;
      }

      // Exchange the OTP token for a real session
      const { data, error } = await supabase.auth.verifyOtp({
        token_hash: tokenHash,
        type: type as EmailOtpType,
      });
      if (error) throw error;

      if (type === 'recovery') {
        // Password recovery — redirect to reset-password screen
        // The session is now active, so supabase.auth.updateUser will work
        setStatus('success');
        setTimeout(() => router.replace('/reset-password'), 1500);
        return;
      }

      if (data?.session) {
        // Email verification — fetch profile and set auth state
        let profile = null;
        for (let attempt = 0; attempt < 10; attempt++) {
          const { data: p } = await supabase
            .from('profiles')
            .select('id, username, role, bio, avatar_url, display_name, is_social_private, preferences, persona, created_at')
            .eq('id', data.session.user.id)
            .maybeSingle();
          if (p) { profile = p; break; }
          await new Promise(r => setTimeout(r, 500));
        }

        if (!profile) throw new Error('Profile synchronization timed out. Please return to login.');

        const completeUser = { ...data.session.user, ...profile, following: [] } as import('@/src/types').User;
        useAuthStore.setState({
          user: completeUser,
          isAuthenticated: true,
        });
        // Persist to MMKV so cold-start restores instantly
        try {
          const { storage } = require('@/src/stores/auth');
          storage.set('ironvault_user_cache', JSON.stringify(completeUser));
        } catch { /* non-critical */ }

        setStatus('success');
        setTimeout(() => router.replace('/(tabs)'), 2000);
      } else {
        throw new Error('Verification succeeded but no session was created.');
      }
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : 'Verification failed. The link may have expired.';
      setErrorMsg(msg);
      setStatus('error');
    }
  }

  return (
    <View style={s.container}>
      <View style={s.content}>
        {/* ── Verifying ── */}
        {status === 'verifying' && (
          <AnimatedView entering={FadeIn.duration(500).reduceMotion(ReduceMotion.Never)} style={s.stateWrap}>
            <ActivityIndicator size="large" color={colors.sepia} style={{ marginBottom: 24 }} />
            <Text style={s.eyebrow}>VERIFYING CLEARANCE</Text>
            <Text style={s.title}>Decrypting your{'\n'}dossier...</Text>
          </AnimatedView>
        )}

        {/* ── Success ── */}
        {status === 'success' && (
          <AnimatedView entering={FadeInDown.duration(600).reduceMotion(ReduceMotion.Never)} style={s.stateWrap}>
            <View style={s.successIconWrap}>
              <Text style={s.successIcon}>✓</Text>
            </View>
            <Text style={[s.eyebrow, { color: colors.sepia }]}>CLEARANCE GRANTED</Text>
            <Text style={s.title}>
              {params.type === 'recovery' ? 'Session Restored.' : 'Welcome to\nThe Society.'}
            </Text>
            <Text style={s.body}>
              {params.type === 'recovery'
                ? 'Redirecting you to set your new password...'
                : 'Your identity has been verified. Initiating access...'}
            </Text>
          </AnimatedView>
        )}

        {/* ── Error ── */}
        {status === 'error' && (
          <AnimatedView entering={FadeInDown.duration(600).reduceMotion(ReduceMotion.Never)} style={s.stateWrap}>
            <View style={s.errorIconWrap}>
              <Text style={s.errorIcon}>✕</Text>
            </View>
            <Text style={[s.eyebrow, { color: colors.bloodReel }]}>VERIFICATION FAILED</Text>
            <Text style={s.title}>Link Expired{'\n'}or Invalid</Text>
            <Text style={s.body}>{errorMsg}</Text>

            {/* Dynamic Rescue Options based on type */}
            <View style={{ marginTop: 28, width: '100%', gap: 12 }}>
              {params.type === 'recovery' ? (
                <TouchableOpacity
                  style={s.retryBtn}
                  onPress={() => router.replace({ pathname: '/login', params: { action: 'forgot_password' } })}
                  activeOpacity={0.7}
                >
                  <Text style={s.retryText}>REQUEST NEW RESET LINK</Text>
                </TouchableOpacity>
              ) : params.type === 'signup' ? (
                <TouchableOpacity
                  style={s.retryBtn}
                  onPress={() => router.replace({ pathname: '/login', params: { action: 'resend_signup' } })}
                  activeOpacity={0.7}
                >
                  <Text style={s.retryText}>REQUEST NEW VERIFICATION</Text>
                </TouchableOpacity>
              ) : null}

              <TouchableOpacity
                style={[s.retryBtn, { backgroundColor: 'transparent', borderWidth: 1, borderColor: colors.ash, marginTop: 0 }]}
                onPress={() => router.replace('/(tabs)')}
                activeOpacity={0.7}
              >
                <Text style={[s.retryText, { color: colors.fog }]}>RETURN TO THE LOBBY</Text>
              </TouchableOpacity>

              <TouchableOpacity
                style={[s.retryBtn, { backgroundColor: 'transparent', borderWidth: 1, borderColor: colors.fog + '33', marginTop: 0 }]}
                onPress={() => router.replace('/login')}
                activeOpacity={0.7}
              >
                <Text style={[s.retryText, { color: colors.fog + '99' }]}>RETURN TO LOGIN</Text>
              </TouchableOpacity>
            </View>
          </AnimatedView>
        )}
      </View>
    </View>
  );
}

const s = StyleSheet.create({
  container: { flex: 1, backgroundColor: colors.ink },
  content: {
    flex: 1, alignItems: 'center', justifyContent: 'center', padding: 32,
  },
  stateWrap: { alignItems: 'center', maxWidth: 340 },

  eyebrow: {
    fontFamily: fonts.ui, fontSize: 9, letterSpacing: 4,
    color: colors.sepia, marginBottom: 12,
  },
  title: {
    fontFamily: fonts.display, fontSize: 28, color: colors.parchment,
    textAlign: 'center', lineHeight: 34, marginBottom: 16,
    ...effects.textShadowDeep,
  },
  body: {
    fontFamily: fonts.body, fontSize: 13, color: colors.bone,
    textAlign: 'center', lineHeight: 22,
  },

  // Success
  successIconWrap: {
    width: 64, height: 64, borderRadius: 32,
    backgroundColor: 'rgba(196, 150, 26, 0.1)', borderWidth: 1.5, borderColor: colors.sepia,
    alignItems: 'center', justifyContent: 'center', marginBottom: 20,
    ...effects.glowSepia,
  },
  successIcon: { fontSize: 28, color: colors.sepia, fontFamily: fonts.uiBold },

  // Error
  errorIconWrap: {
    width: 64, height: 64, borderRadius: 32,
    backgroundColor: 'rgba(107, 26, 10, 0.15)', borderWidth: 1.5, borderColor: colors.bloodReel,
    alignItems: 'center', justifyContent: 'center', marginBottom: 20,
  },
  errorIcon: { fontSize: 28, color: colors.bloodReel, fontFamily: fonts.uiBold },

  retryBtn: {
    backgroundColor: colors.sepia, borderRadius: 3, paddingVertical: 14,
    paddingHorizontal: 32, marginTop: 28,
    ...effects.glowSepia,
  },
  retryText: {
    fontFamily: fonts.uiMedium, fontSize: 10, letterSpacing: 2.5,
    color: colors.ink, fontWeight: '700',
  },
});

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { View, Text, TextInput, StyleSheet, KeyboardAvoidingView, Platform, ScrollView, Dimensions, Keyboard } from 'react-native';
import { router, useLocalSearchParams, Stack } from 'expo-router';
import { BlurView } from 'expo-blur';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { Bold, Italic, Type, Quote, Minus, Link2 } from 'lucide-react-native';
import Markdown from 'react-native-markdown-display';
import * as Haptics from 'expo-haptics';

import { useAuthStore } from '@/src/stores/auth';
import { useDispatchStore } from '@/src/stores/content';
import { colors, fonts, spacing } from '@/src/theme/theme';
import reelToast from '@/src/utils/reelToast';
import PressableScale from '@/src/components/PressableScale';

const { width } = Dimensions.get('window');

export default function ComposeDossierScreen() {
    const { edit, initialTitle, initialContent } = useLocalSearchParams<{ edit?: string, initialTitle?: string, initialContent?: string }>();
    const { user } = useAuthStore();
    const insets = useSafeAreaInsets();
    const canWrite = user?.role === 'auteur';

    const [title, setTitle] = useState(initialTitle || '');
    const [content, setContent] = useState(initialContent || '');
    const [isPublishing, setIsPublishing] = useState(false);
    const [isPreview, setIsPreview] = useState(false);

    const inputRef = useRef<TextInput>(null);

    useEffect(() => {
        if (!canWrite) {
            reelToast('Auteur tier required');
            router.back();
        }
    }, [canWrite]);

    const stats = useMemo(() => {
        const words = content.trim() ? content.trim().split(/\s+/).length : 0;
        const readMin = Math.max(1, Math.ceil(words / 200));
        return { words, readMin };
    }, [content]);

    const insertFormatting = (before: string, after: string) => {
        setContent(prev => `${prev}${before}${after}`);
        // In a real advanced editor, we'd handle cursor position, but React Native TextInput selection handling is tricky.
        // We just append for now to ensure stability.
        inputRef.current?.focus();
    };

    const handlePublish = async () => {
        if (!title.trim() || !content.trim() || isPublishing) return;
        Keyboard.dismiss();
        setIsPublishing(true);

        try {
            // Strip markdown formatting for the clean plaintext excerpt
            const plainText = content.replace(/[#*_[\]()>-]/g, '').replace(/\n+/g, ' ').trim();
            const excerpt = plainText.substring(0, 150) + (plainText.length > 150 ? '...' : '');

            if (edit) {
                await useDispatchStore.getState().updateDossier(edit, {
                    title: title.trim(),
                    excerpt,
                    fullContent: content.trim(),
                });
                reelToast.success('Dossier updated');
            } else {
                await useDispatchStore.getState().addDossier({
                    title: title.trim(),
                    excerpt,
                    fullContent: content.trim(),
                });
                reelToast.success('Dossier published');
            }
            router.replace('/(tabs)/dispatch');
        } catch (err) {
            reelToast.error('Transmission failed');
        } finally {
            setIsPublishing(false);
        }
    };

    return (
        <View style={styles.container}>
            <Stack.Screen options={{ headerShown: false, presentation: 'modal' }} />

            <View style={[styles.header, { paddingTop: insets.top + 12 }]}>
                <PressableScale onPress={() => router.back()} hitSlop={{top:10,bottom:10,left:10,right:10}} haptic>
                    <Text style={styles.cancelBtn} numberOfLines={1}>CANCEL</Text>
                </PressableScale>
                <Text style={styles.headerTitle} numberOfLines={1}>THE WRITING ROOM</Text>
                <PressableScale 
                    onPress={() => {
                        setIsPreview(!isPreview);
                    }}
                    haptic="medium"
                >
                    <Text style={styles.previewBtn} numberOfLines={1}>{isPreview ? 'EDIT' : 'PREVIEW'}</Text>
                </PressableScale>
            </View>

            {isPreview ? (
                <ScrollView style={styles.workspace} contentContainerStyle={styles.previewContent} showsVerticalScrollIndicator={false}>
                    <Text style={styles.previewEyebrow}>LIVE PREVIEW</Text>
                    {title ? <Text style={styles.previewTitle}>{title}</Text> : null}
                    {content ? (
                        <Markdown style={markdownStyles}>
                            {content}
                        </Markdown>
                    ) : (
                        <View style={styles.emptyPreview}>
                            <Text style={styles.emptyPreviewText}>Your cinematic essay will appear here...</Text>
                        </View>
                    )}
                </ScrollView>
            ) : (
                <KeyboardAvoidingView style={styles.kavFlex} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
                    <ScrollView style={styles.workspace} keyboardShouldPersistTaps="handled">
                        <TextInput
                            style={styles.titleInput}
                            placeholder="Headline..."
                            placeholderTextColor={colors.fog}
                            value={title}
                            onChangeText={setTitle}
                            maxLength={100}
                            cursorColor={colors.sepia}
                            selectionColor="rgba(139,105,20,0.3)"
                            keyboardAppearance="dark"
                            accessibilityLabel="Dossier headline"
                        />
