interface SocialLink {
  id: string;
  title: string;
  url: string;
}

function generateId() {
  return Math.random().toString(36).slice(2, 9);
}

// Removed redundant AnimatedView definition

// ── Ornamental Divider ──◇── ──
function OrnamentalRule() {
  return (
    <View style={st.ornRule}>
      <View style={st.ornLine} />
