                       WITH {log.watched_with.toUpperCase()}
                    </Text>
                  )}
                  {log.watched_with && log.physical_media && <Text style={{ color: colors.ash, fontSize: 10 }}>·</Text>}
                  {log.physical_media && (
                    <Text style={{ fontFamily: fonts.ui, fontSize: 9, color: colors.bone, letterSpacing: 1.5 }}>
                       FORMAT: {log.physical_media.toUpperCase()}
                    </Text>
                  )}
               </View>
            )}
          </View>

          {/* Full Width Review / Pull Quote — Web: padding 1.5rem 1.5rem, textAlign center */}
          <View style={s.reviewSection}>
            {log.editorial_header && (
               <Text style={{ fontFamily: fonts.display, fontSize: 24, textAlign: 'center', color: colors.parchment, marginBottom: log.pull_quote || log.review ? 24 : 0 }}>
                  {log.editorial_header}
               </Text>
            )}
            {log.pull_quote && (
              <View style={s.featuredQuoteWrap}>
