          )}
        </View>

        {/* ═══ CLASSIFIED DOSSIER — BIOGRAPHY ═══ */}
        {person.biography ? (
          <AnimatedView style={s.bioSection}>
            <LinearGradient
              colors={['rgba(139,105,20,0.4)', 'transparent']}
              start={{ x: 0, y: 0 }} end={{ x: 1, y: 0 }}
              style={s.bioTopLine}
