import { useState, useEffect } from 'react';
import {
  View, Text, StyleSheet, ScrollView,
  Alert, ActivityIndicator, Linking, Platform,
} from 'react-native';
import Animated, { FadeInDown, useSharedValue, useAnimatedStyle, withRepeat, withTiming, Easing } from 'react-native-reanimated';
import { LinearGradient } from 'expo-linear-gradient';
import { useRouter } from 'expo-router';
import * as Haptics from 'expo-haptics';
import { ChevronLeft, LogOut, Trash2, Shield, FileText, Download, Sparkles } from 'lucide-react-native';

import { useAuthStore } from '@/src/stores/auth';
import reelToast from '@/src/utils/reelToast';
import { supabase } from '@/src/lib/supabase';
import { colors, fonts, effects } from '@/src/theme/theme';
import DataVault from '@/src/components/settings/DataVault';
import PressableScale from '@/src/components/PressableScale';

const AnimatedView = Animated.createAnimatedComponent(View);

import { PatronageSection, AccountSection, PrivacySection, NotificationsSection, SectionCard, SectionHead, ActionBtn } from '@/src/components/settings/SettingsSections';

export default function SettingsScreen() {
  const router = useRouter();
  const { user, updateUser, logout } = useAuthStore();

  // ── Privacy ──
  const [socialVisibility, setSocialVisibility] = useState<string>('public');
  const [privacyEndorsements, setPrivacyEndorsements] = useState<string>('everyone');
  const [privacyAnnotations, setPrivacyAnnotations] = useState<string>('everyone');

  // ── Notifications ──
  const [notifFollows, setNotifFollows] = useState(true);
  const [notifEndorsements, setNotifEndorsements] = useState(true);
  const [notifComments, setNotifComments] = useState(true);
  const [notifSystem, setNotifSystem] = useState(true);

  // ── Password ──
  const [showPasswordChange, setShowPasswordChange] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [changingPassword, setChangingPassword] = useState(false);

  // ── General ──
  const [saving, setSaving] = useState(false);

  const userRole = (user?.role as string) ?? 'cinephile';

  useEffect(() => {
    if (!user) return;
    const p = user.preferences ?? {};
    setSocialVisibility(typeof p.social_visibility === 'string' ? p.social_visibility : (user.is_social_private ? 'private' : 'public'));
    setPrivacyEndorsements(typeof p.privacy_endorsements === 'string' ? p.privacy_endorsements : 'everyone');
    setPrivacyAnnotations(typeof p.privacy_annotations === 'string' ? p.privacy_annotations : 'everyone');
    setNotifFollows(p.notif_follows !== undefined ? !!p.notif_follows : true);
    setNotifEndorsements(p.notif_endorsements !== undefined ? !!p.notif_endorsements : true);
    setNotifComments(p.notif_comments !== undefined ? !!p.notif_comments : true);
    setNotifSystem(p.notif_system !== undefined ? !!p.notif_system : true);
  }, [user?.id, user?.preferences]);

  const handleSave = async () => {
    if (!user) return;
    setSaving(true);
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    try {
      await updateUser({
        isSocialPrivate: socialVisibility === 'private',
      });
      const setP = useAuthStore.getState().setPreference;
      await setP('notif_follows', notifFollows);
      await setP('notif_endorsements', notifEndorsements);
      await setP('notif_comments', notifComments);
      await setP('notif_system', notifSystem);
      await setP('social_visibility', socialVisibility);
      await setP('privacy_endorsements', privacyEndorsements);
      await setP('privacy_annotations', privacyAnnotations);
      reelToast.success('Your dossier has been amended.');
    } catch (err: unknown) {
      reelToast.error(err instanceof Error ? err.message : 'Amendment failed — please try again.');
    } finally {
      setSaving(false);
    }
  };

  const handlePasswordChange = async () => {
    if (newPassword.length < 8) { reelToast('Cipher must be at least 8 characters.'); return; }
    if (newPassword !== confirmPassword) { reelToast('Ciphers do not match.'); return; }
    setChangingPassword(true);
    try {
      const { error } = await supabase.auth.updateUser({ password: newPassword });
      if (error) throw error;
      reelToast.success('Credentials re-encrypted.');
      setNewPassword('');
      setConfirmPassword('');
      setShowPasswordChange(false);
    } catch (e: unknown) {
      reelToast.error(e instanceof Error ? e.message : 'Re-encryption failed.');
    } finally {
      setChangingPassword(false);
    }
  };

  const handleSignOut = () => {
    Alert.alert('Depart the Society', 'Your membership will remain. You may return at any time.', [
      { text: 'CANCEL', style: 'cancel' },
      { text: 'SIGN OUT', style: 'destructive', onPress: async () => {
        Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Heavy);
        await logout();
        router.replace('/');
      }},
    ]);
  };

  const handleDeleteAccount = () => {
    Alert.alert(
      'Expunge All Records',
      'This will permanently destroy your dossier, all logs, stacks, and critiques. This action is irreversible.',
      [
        { text: 'CANCEL', style: 'cancel' },
        { text: 'DELETE', style: 'destructive', onPress: () => {
          Alert.alert('Contact Support', 'Account deletion requires admin intervention. Contact support@reelhouse.app');
        }},
      ]
    );
  };

  const glowOpacity = useSharedValue(0.04);
  useEffect(() => {
    glowOpacity.value = withRepeat(withTiming(0.08, { duration: 3000, easing: Easing.inOut(Easing.ease) }), -1, true);
  }, []);
  const glowStyle = useAnimatedStyle(() => ({ opacity: glowOpacity.value }));

  if (!user) return null;

  return (
    <View style={st.container}>
      <Animated.View style={[st.ambientGlow, glowStyle]}>
        <LinearGradient colors={['rgba(139,105,20,0.15)', 'transparent', 'transparent']} locations={[0, 0.4, 1]} style={StyleSheet.absoluteFillObject} />
      </Animated.View>
      <View style={st.navBar}>
        <PressableScale onPress={() => router.back()} style={st.navBackBtn} hitSlop={{top: 15, bottom: 15, left: 15, right: 15}} haptic="selection" pressedScale={0.92}>
          <ChevronLeft size={22} color={colors.bone} />
        </PressableScale>
        <PressableScale onPress={handleSave} disabled={saving} hitSlop={{top: 15, bottom: 15, left: 15, right: 15}} haptic="medium" pressedScale={0.95}>
          {saving ? <ActivityIndicator size="small" color={colors.sepia} /> : <Text style={st.navSaveText}>SAVE</Text>}
        </PressableScale>
      </View>

      <ScrollView contentContainerStyle={st.scrollContent} showsVerticalScrollIndicator={false}>
        <AnimatedView entering={FadeInDown.duration(600)} style={st.hero}>
          <View style={st.heroRuleTop} />
          <View style={st.heroEyebrowRow}>
            <Sparkles size={7} color={colors.sepia} strokeWidth={2} />
            <Text style={st.heroEyebrow}>THE DOSSIER BUREAU</Text>
            <Sparkles size={7} color={colors.sepia} strokeWidth={2} />
          </View>
          <Text style={st.heroTitle}>Settings</Text>
          <Text style={st.heroEst}>EST. 1924</Text>
          <Text style={st.heroDesc}>Configure your presence within The Society.</Text>
          <View style={st.heroRuleBottom} />
        </AnimatedView>

        <PatronageSection userRole={userRole} router={router} />
        <View style={st.ornRule}><View style={st.ornLine} /><View style={st.ornDiamond} /><View style={st.ornLine} /></View>

        <AccountSection
          user={user} showPasswordChange={showPasswordChange} setShowPasswordChange={setShowPasswordChange}
          newPassword={newPassword} setNewPassword={setNewPassword}
          confirmPassword={confirmPassword} setConfirmPassword={setConfirmPassword}
          changingPassword={changingPassword} handlePasswordChange={handlePasswordChange}
        />
        <View style={st.ornRule}><View style={st.ornLine} /><View style={st.ornDiamond} /><View style={st.ornLine} /></View>

        <PrivacySection
          socialVisibility={socialVisibility} setSocialVisibility={setSocialVisibility}
          privacyEndorsements={privacyEndorsements} setPrivacyEndorsements={setPrivacyEndorsements}
          privacyAnnotations={privacyAnnotations} setPrivacyAnnotations={setPrivacyAnnotations}
        />
        <View style={st.ornRule}><View style={st.ornLine} /><View style={st.ornDiamond} /><View style={st.ornLine} /></View>

        <NotificationsSection
          notifFollows={notifFollows} setNotifFollows={setNotifFollows}
          notifEndorsements={notifEndorsements} setNotifEndorsements={setNotifEndorsements}
          notifComments={notifComments} setNotifComments={setNotifComments}
          notifSystem={notifSystem} setNotifSystem={setNotifSystem}
        />

        <AnimatedView entering={FadeInDown.duration(500).delay(300)}>
          <SectionCard>
            <SectionHead icon={Download} label="IMPORT & EXPORT" />
            <DataVault />
          </SectionCard>
        </AnimatedView>
        <View style={st.ornRule}><View style={st.ornLine} /><View style={st.ornDiamond} /><View style={st.ornLine} /></View>

        <AnimatedView entering={FadeInDown.duration(500).delay(350)}>
          <SectionCard>
            <SectionHead icon={FileText} label="LEGAL" />
            <View style={st.legalActions}>
              <ActionBtn icon={Shield} label="PRIVACY POLICY" onPress={() => Linking.openURL('https://www.thereelhousesociety.com/privacy')} />
              <ActionBtn icon={FileText} label="TERMS OF SERVICE" onPress={() => Linking.openURL('https://www.thereelhousesociety.com/terms')} />
            </View>
          </SectionCard>
        </AnimatedView>

        <AnimatedView entering={FadeInDown.duration(500).delay(400)}>
          <SectionCard danger>
            <SectionHead icon={Shield} label="ACCOUNT ACTIONS" danger />
            <View style={st.legalActions}>
              <ActionBtn icon={LogOut} label="SIGN OUT" onPress={handleSignOut} />
              <View style={st.divider} />
              <ActionBtn icon={Trash2} label="DELETE ACCOUNT" onPress={handleDeleteAccount} danger />
            </View>
          </SectionCard>
        </AnimatedView>

        <AnimatedView entering={FadeInDown.duration(500).delay(450)} style={st.heritageFooter}>
          <View style={st.ornRule}><View style={st.ornLine} /><View style={st.ornDiamond} /><View style={st.ornLine} /></View>
          <PressableScale style={[st.globalSaveBtn, saving && st.disabledBtn]} onPress={handleSave} disabled={saving} haptic="medium" pressedScale={0.96}>
            <LinearGradient colors={['rgba(139,105,20,0.2)', 'rgba(139,105,20,0.1)']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={StyleSheet.absoluteFillObject} />
            <View style={st.saveBtnContent}>
              {!saving && <Sparkles size={10} color={colors.sepia} strokeWidth={2} />}
              <Text style={st.globalSaveBtnText}>{saving ? 'ARCHIVING SETTINGS\u2026' : 'SAVE SETTINGS'}</Text>
              {!saving && <Sparkles size={10} color={colors.sepia} strokeWidth={2} />}
            </View>
          </PressableScale>
          <View style={st.legalFooter}>
            <PressableScale onPress={() => Linking.openURL('https://www.thereelhousesociety.com/privacy')} haptic="selection" pressedScale={0.96}><Text style={st.legalFooterLink}>PRIVACY POLICY</Text></PressableScale>
            <View style={st.footerDot} />
            <PressableScale onPress={() => Linking.openURL('https://www.thereelhousesociety.com/terms')} haptic="selection" pressedScale={0.96}><Text style={st.legalFooterLink}>TERMS OF SERVICE</Text></PressableScale>
          </View>
          <Text style={st.memberSince}>MEMBER SINCE {user.created_at ? new Date(user.created_at).toLocaleDateString('en-US', { month: 'long', year: 'numeric' }).toUpperCase() : 'THE BEGINNING'}</Text>
          <View style={st.endMarkRow}>
            <View style={st.endMarkLine} /><Sparkles size={8} color={colors.sepia} strokeWidth={1.5} /><View style={st.endMarkLine} />
          </View>
          <Text style={st.heritageMark}>EST. 1924 · THE REELHOUSE SOCIETY</Text>
          <Text style={st.heritageCopyright}>© 1924–2026 The ReelHouse Society. All dossiers are classified.</Text>
        </AnimatedView>
      </ScrollView>
    </View>
  );
}

const st = StyleSheet.create({
  container: { flex: 1, backgroundColor: colors.ink },
  ambientGlow: { position: 'absolute', top: 0, left: 0, right: 0, height: 350, zIndex: 0 },
  navBar: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: 16, paddingTop: Platform.OS === 'ios' ? 60 : 40, paddingBottom: 16, borderBottomWidth: 1, borderBottomColor: 'rgba(139,105,20,0.1)', zIndex: 10, backgroundColor: 'rgba(5,3,1,0.85)' },
  navBackBtn: { padding: 4 },
  navSaveText: { fontFamily: fonts.uiMedium, fontSize: 10, letterSpacing: 2, color: colors.sepia },
  scrollContent: { paddingBottom: 100 },
  hero: { alignItems: 'center', paddingVertical: 40, paddingHorizontal: 24 },
  heroRuleTop: { width: 100, height: 2, borderTopWidth: 1, borderBottomWidth: 1, borderColor: colors.sepia, marginBottom: 16, opacity: 0.5 },
  heroRuleBottom: { width: 100, height: 2, borderTopWidth: 1, borderBottomWidth: 1, borderColor: colors.sepia, marginTop: 24, opacity: 0.5 },
  heroEyebrowRow: { flexDirection: 'row', alignItems: 'center', gap: 8, marginBottom: 12 },
  heroEyebrow: { fontFamily: fonts.ui, fontSize: 9, letterSpacing: 4, color: colors.sepia },
  heroTitle: { fontFamily: fonts.display, fontSize: 32, color: colors.parchment, marginBottom: 4, ...effects.textShadowDeep },
  heroEst: { fontFamily: fonts.uiBold, fontSize: 8, letterSpacing: 3, color: colors.sepia, marginBottom: 16, opacity: 0.8 },
  heroDesc: { fontFamily: fonts.bodyItalic, fontSize: 13, color: colors.bone, textAlign: 'center', maxWidth: 260 },
  ornRule: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', paddingVertical: 24, paddingHorizontal: 40, opacity: 0.5 },
  ornLine: { flex: 1, height: 1, backgroundColor: colors.sepia },
  ornDiamond: { width: 6, height: 6, backgroundColor: colors.sepia, transform: [{ rotate: '45deg' }], marginHorizontal: 12 },
  legalActions: { flexDirection: 'column' },
  divider: { height: 1, backgroundColor: 'rgba(139,105,20,0.1)' },
  heritageFooter: { marginTop: 40, paddingHorizontal: 24, alignItems: 'center', paddingBottom: 40 },
  globalSaveBtn: { backgroundColor: 'transparent', borderWidth: 1, borderColor: colors.sepia, width: '100%', paddingVertical: 18, alignItems: 'center', borderRadius: 2, marginBottom: 32, ...effects.glowSepia },
  disabledBtn: { opacity: 0.5 },
  saveBtnContent: { flexDirection: 'row', alignItems: 'center', gap: 10 },
  globalSaveBtnText: { fontFamily: fonts.uiMedium, fontSize: 11, letterSpacing: 3, color: colors.sepia, fontWeight: '700' },
  legalFooter: { flexDirection: 'row', alignItems: 'center', gap: 12, marginBottom: 24 },
  legalFooterLink: { fontFamily: fonts.ui, fontSize: 9, letterSpacing: 1.5, color: colors.fog, textDecorationLine: 'underline', textDecorationColor: colors.fog },
  footerDot: { width: 3, height: 3, borderRadius: 1.5, backgroundColor: colors.fog },
  memberSince: { fontFamily: fonts.uiBold, fontSize: 9, letterSpacing: 2, color: colors.parchment, marginBottom: 32 },
  endMarkRow: { flexDirection: 'row', alignItems: 'center', gap: 12, marginBottom: 16 },
  endMarkLine: { width: 30, height: 1, backgroundColor: colors.sepia, opacity: 0.3 },
  heritageMark: { fontFamily: fonts.ui, fontSize: 9, letterSpacing: 2, color: colors.sepia, marginBottom: 8 },
  heritageCopyright: { fontFamily: fonts.bodyItalic, fontSize: 10, color: colors.fog },
});

import React, { useState, useEffect } from 'react';
import { View, Text, StyleSheet, ActivityIndicator } from 'react-native';
import { FlashList } from '@shopify/flash-list';
import { Image } from 'expo-image';
import { useLocalSearchParams, router } from 'expo-router';
import { BlurView } from 'expo-blur';
import { X, User, Users } from 'lucide-react-native';
import Animated, { FadeInUp } from 'react-native-reanimated';
import { supabase } from '@/src/lib/supabase';
import { colors, fonts } from '@/src/theme/theme';
import PressableScale from '@/src/components/PressableScale';
import { EmptyState } from '@/src/components/EmptyStates';
import reelToast from '@/src/utils/reelToast';

interface SocialProfile {
    id: string;
    username: string;
    avatar_url?: string;
    role?: string;
}

export default function SocialModal() {
    const { userId, type } = useLocalSearchParams<{ userId: string, type: 'followers' | 'following' }>();
    const [loading, setLoading] = useState(true);
    const [profiles, setProfiles] = useState<SocialProfile[]>([]);

    useEffect(() => {
        if (!userId || (type !== 'followers' && type !== 'following')) {
            router.back();
            return;
        }

        const fetchSocial = async () => {
            setLoading(true);
            try {
                let ids: string[] = [];
                if (type === 'followers') {
                    const { data } = await supabase
                        .from('interactions')
                        .select('user_id')
                        .eq('target_user_id', userId)
                        .eq('type', 'follow')
                        .limit(100);
                    ids = (data || []).map(r => r.user_id);
                } else {
                    const { data } = await supabase
                        .from('interactions')
                        .select('target_user_id')
                        .eq('user_id', userId)
                        .eq('type', 'follow')
                        .limit(100);
                    ids = (data || []).map(r => r.target_user_id);
                }

                if (ids.length > 0) {
                    const { data: profs } = await supabase
                        .from('profiles')
                        .select('id, username, avatar_url, role')
                        .in('id', ids);
                    setProfiles(profs || []);
                }
            } catch (err) {
                reelToast.error('The telegraph to the archive is disrupted.');
            } finally {
                setLoading(false);
            }
        };

        fetchSocial();
    }, [userId, type]);

    const handleProfilePress = (username: string) => {
        router.back();
        setTimeout(() => {
            router.push(`/user/${username}` as any);
        }, 300);
    };

    return (
        <BlurView intensity={90} tint="dark" style={styles.container}>
            {/* Drag handle */}
            <View style={styles.dragHandleWrap}><View style={styles.dragHandle} /></View>

            <View style={styles.header}>
                <View style={{ width: 40 }} />
                <Text style={styles.title}>{type === 'followers' ? 'FOLLOWERS' : 'FOLLOWING'}</Text>
                <PressableScale onPress={() => router.back()} style={styles.closeBtn} hitSlop={{top: 15, bottom: 15, left: 15, right: 15}} haptic="selection" pressedScale={0.92}>
                    <X size={20} color={colors.parchment} />
                </PressableScale>
            </View>

            {loading ? (
                <View style={styles.center}>
                    <ActivityIndicator size="large" color={colors.sepia} />
                </View>
            ) : profiles.length === 0 ? (
                <View style={styles.center}>
                    <EmptyState
                        icon={<Users size={28} color={colors.sepia} strokeWidth={1} />}
                        title="The Circle Is Empty"
                        subtitle={type === 'followers' ? 'No one follows this member yet.' : 'This member hasn\'t followed anyone yet.'}
                    />
                </View>
            ) : (
                <FlashList 
                    data={profiles}
                    /* estimatedItemSize removed for v2 */
                    keyExtractor={item => item.id}
                    contentContainerStyle={{ padding: 16 }}
                    renderItem={({ item, index }) => (
                        <Animated.View entering={FadeInUp.duration(300).delay(index * 40)}>
                            <PressableScale onPress={() => handleProfilePress(item.username)}>
                                <View style={styles.userRow}>
                                    {item.avatar_url && item.avatar_url.startsWith('http') ? (
                                        <Image source={{ uri: item.avatar_url }} style={styles.avatar} contentFit="cover" />
                                    ) : (
                                        <View style={styles.avatarPlaceholder}><User size={20} color={colors.parchment} /></View>
                                    )}
                                    <View style={styles.userInfo}>
                                        <Text style={styles.username}>@{item.username.toUpperCase()}</Text>
                                        <Text style={styles.role}>{(item.role ?? 'member').toUpperCase()}</Text>
                                    </View>
                                </View>
                            </PressableScale>
                        </Animated.View>
                    )}
                />
            )}
        </BlurView>
    );
}

const styles = StyleSheet.create({
    container: { flex: 1 },
    dragHandleWrap: { alignItems: 'center', paddingTop: 10 },
    dragHandle: { width: 36, height: 4, borderRadius: 2, backgroundColor: 'rgba(255,255,255,0.2)' },
    header: {
        flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between',
        paddingHorizontal: 16, paddingTop: 12, paddingBottom: 20,
        borderBottomWidth: StyleSheet.hairlineWidth, borderBottomColor: 'rgba(139,105,20,0.2)',
    },
    title: { fontFamily: fonts.uiMedium, fontSize: 12, letterSpacing: 4, color: colors.sepia },
    closeBtn: { width: 40, height: 40, alignItems: 'flex-end', justifyContent: 'center' },
    center: { flex: 1, alignItems: 'center', justifyContent: 'center' },
    userRow: {
        flexDirection: 'row', alignItems: 'center', paddingVertical: 12,
        borderBottomWidth: StyleSheet.hairlineWidth, borderBottomColor: colors.ash,
    },
    avatar: { width: 44, height: 44, borderRadius: 22 },
    avatarPlaceholder: {
        width: 44, height: 44, borderRadius: 22,
        backgroundColor: 'rgba(139,105,20,0.15)', alignItems: 'center', justifyContent: 'center',
        borderWidth: 1, borderColor: 'rgba(139,105,20,0.3)',
    },
    userInfo: { marginLeft: 14, flex: 1 },
    username: { fontFamily: fonts.sub, fontSize: 15, color: colors.parchment, marginBottom: 2 },
    role: { fontFamily: fonts.ui, fontSize: 9, letterSpacing: 1.5, color: colors.fog },
});

import React, { useEffect, useState, useCallback } from 'react';
import { View, Text, StyleSheet, TouchableOpacity, Dimensions, ActivityIndicator, Platform, FlatList, Alert, TextInput, KeyboardAvoidingView } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import Animated, { FadeInDown, FadeInUp, interpolate, useAnimatedScrollHandler, useAnimatedStyle, useSharedValue } from 'react-native-reanimated';
import * as Haptics from 'expo-haptics';
import { Image } from 'expo-image';
import { BlurView } from 'expo-blur';
import { LinearGradient } from 'expo-linear-gradient';
import { FlashList } from '@shopify/flash-list';
import { ArrowLeft, Edit3, Trash2, CheckCircle2, Award, MessageCircle, Send } from 'lucide-react-native';
import { useQuery } from '@tanstack/react-query';

import { useAuthStore } from '@/src/stores/auth';
import { useFilmStore } from '@/src/stores/films';
import { supabase } from '@/src/lib/supabase';
import { tmdb } from '@/src/lib/tmdb';
import { colors, fonts } from '@/src/theme/theme';
import reelToast from '@/src/utils/reelToast';

const { width, height } = Dimensions.get('window');
const ITEM_WIDTH = (width - 32 - 16) / 3;
const ITEM_HEIGHT = ITEM_WIDTH * 1.5;
const HEADER_HEIGHT = height * 0.45;

const AnimatedFlashList = Animated.createAnimatedComponent(FlashList);
const AnimatedBlurView = Animated.createAnimatedComponent(BlurView);

const blurhash = 'L87n_O~q00_300E1t7Rj00%#RjV@';

interface FilmItem {
  id: number;
  title: string;
  poster_path: string | null;
}

interface ListDetail {
  id: string;
  title: string;
  description: string;
  userId: string;
  user: string;
  createdAt: string;
  films: FilmItem[];
  isPrivate: boolean;
  isRanked: boolean;
}

interface ListComment {
  id: string;
  user_id: string;
  username: string;
  content: string;
  created_at: string;
}

interface LoungeItem {
  id: string;
  name: string;
  cover_image: string | null;
  is_private: boolean;
}

// ── Memoized Comment Row ──
const StackCommentRow = React.memo(({ c }: { c: ListComment }) => (
  <View style={s.commentRow}>
    <Text style={s.commentUser} numberOfLines={1}>@{c.username}</Text>
    <Text style={s.commentBody}>{c.content}</Text>
  </View>
));

const StackDetailFilmCard = React.memo(({ 
  item, 
  index, 
  isLogged, 
  isRanked, 
  onPress 
}: { 
  item: FilmItem; 
  index: number; 
  isLogged: boolean; 
  isRanked: boolean; 
  onPress: (id: number) => void;
}) => {
  return (
    <Animated.View entering={FadeInUp.duration(400).delay(Math.min(index * 30, 400))} style={s.filmItem}>
      <TouchableOpacity 
        style={[s.filmCard, { width: ITEM_WIDTH, height: ITEM_HEIGHT }]} 
        onPress={() => onPress(item.id)}
        activeOpacity={0.8}
      >
        {item.poster_path ? (
          <Image 
            source={{ uri: tmdb.poster(item.poster_path, 'w342')! }} 
            style={StyleSheet.absoluteFillObject}
            contentFit="cover"
            cachePolicy="memory-disk"
            placeholder={{ blurhash }}
            transition={200}
          />
        ) : (
          <View style={s.posterPlaceholder}>
            <Text style={s.placeholderText} numberOfLines={3} adjustsFontSizeToFit>{item.title}</Text>
          </View>
        )}
        {isLogged && (
          <View style={s.loggedBadge}>
            <CheckCircle2 size={12} color={colors.parchment} />
          </View>
        )}
        {isRanked && (
          <View style={s.rankBadgeWrap}>
            <LinearGradient 
              colors={['transparent', 'rgba(10,7,3,0.8)', 'rgba(5,4,2,0.95)']} 
              style={StyleSheet.absoluteFillObject} 
            />
            <Text style={s.rankNumber}>{index + 1}</Text>
          </View>
        )}
      </TouchableOpacity>
      <Text style={s.filmTitle} numberOfLines={2} adjustsFontSizeToFit minimumFontScale={0.8}>{item.title}</Text>
    </Animated.View>
  );
});

export default function StackDetailScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const router = useRouter();
  const { user } = useAuthStore();
  const { logs, toggleListEndorse, hasListEndorsed, deleteList } = useFilmStore();

  // ── React Query: MMKV-cached stack detail (instant revisits) ──
  const { data: stackQueryData, isLoading: stackQueryLoading } = useQuery({
    queryKey: ['stack', id],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('lists')
        .select('id, title, description, created_at, user_id, is_private, is_ranked')
        .eq('id', id)
        .single();

      if (error || !data) throw error;

      const [profileRes, itemsRes, endorseRes] = await Promise.all([
        supabase.from('profiles').select('username').eq('id', data.user_id).single(),
        supabase.from('list_items').select('film_id, film_title, poster_path').eq('list_id', id).order('position', { ascending: true }).order('created_at', { ascending: true }),
        supabase.from('interactions').select('user_id', { count: 'exact', head: false }).eq('target_list_id', id).eq('type', 'endorse_list'),
      ]);

      const endorseCount = endorseRes.count || endorseRes.data?.length || 0;

      const listDetail: ListDetail = {
        id: data.id,
        title: data.title,
        description: data.description,
        userId: data.user_id,
        user: profileRes.data?.username || 'anonymous',
        createdAt: data.created_at,
        films: (itemsRes.data || []).map((item: { film_id: number; film_title: string; poster_path: string | null; }) => ({
          id: item.film_id,
          title: item.film_title,
          poster_path: item.poster_path,
        })),
        isPrivate: data.is_private,
        isRanked: data.is_ranked,
      };

      return { list: listDetail, endorseCount };
    },
    staleTime: 10 * 60 * 1000,  // 10 min
    enabled: !!id,
  });

  const list = stackQueryData?.list ?? null;
  const loading = stackQueryLoading;
  const [certifyCount, setCertifyCount] = useState(0);
  const [showComments, setShowComments] = useState(false);
  const [comments, setComments] = useState<ListComment[]>([]);
  const [commentText, setCommentText] = useState('');
  const [submittingComment, setSubmittingComment] = useState(false);
  const [showLoungeShare, setShowLoungeShare] = useState(false);
  const [loadingLounges, setLoadingLounges] = useState(false);
  const [lounges, setLounges] = useState<LoungeItem[]>([]);
  const [sharingTo, setSharingTo] = useState<string | null>(null);

  // Callback isolation: stabilize comment input handler
  const handleCommentTextChange = useCallback((text: string) => {
    setCommentText(text);
  }, []);

  // Scroll animations
  const scrollY = useSharedValue(0);
  const scrollHandler = useAnimatedScrollHandler({
    onScroll: (event) => {
      scrollY.value = event.contentOffset.y;
    },
  });

  const headerStyle = useAnimatedStyle(() => {
    return {
      height: HEADER_HEIGHT,
      transform: [
        { translateY: interpolate(scrollY.value, [-100, 0, HEADER_HEIGHT], [0, 0, HEADER_HEIGHT * 0.5]) },
        { scale: interpolate(scrollY.value, [-100, 0], [1.2, 1], 'clamp') }
      ]
    };
  });

  const navBlurStyle = useAnimatedStyle(() => {
    return {
      opacity: interpolate(scrollY.value, [HEADER_HEIGHT * 0.5, HEADER_HEIGHT - 60], [0, 1], 'clamp')
    };
  });

  // Sync endorsement count from query data
  useEffect(() => {
    if (stackQueryData?.endorseCount !== undefined) {
      setCertifyCount(stackQueryData.endorseCount);
    }
  }, [stackQueryData?.endorseCount]);

  const isOwner = user?.id === list?.userId;
  const isCertified = hasListEndorsed(id);
  const loggedIds = new Set(logs.map(l => l.filmId));

  // ── CERTIFY ──
  const handleCertify = useCallback(async () => {
    if (!user) return;
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    const wasCertified = isCertified;

    if (wasCertified) {
      setCertifyCount(c => Math.max(0, c - 1));
    } else {
      setCertifyCount(c => c + 1);
    }

    try {
      await toggleListEndorse(id);
      if (!wasCertified) reelToast.success('Certified!');
    } catch {
      // Atomic rollback on failure
      setCertifyCount(c => wasCertified ? c + 1 : Math.max(0, c - 1));
      reelToast.error('Certification failed. Reverted.');
    }
  }, [user, id, isCertified, toggleListEndorse]);

  // ── COMMENTS ──
  const loadComments = useCallback(async () => {
    const { data } = await supabase
      .from('list_comments')
      .select('id, user_id, content, created_at')
      .eq('list_id', id)
      .order('created_at', { ascending: true })
      .limit(30);
    if (!data || data.length === 0) { setComments([]); return; }
    const uids = [...new Set(data.map((c: { user_id: string }) => c.user_id))];
    const { data: profiles } = await supabase.from('profiles').select('id, username').in('id', uids);
    const umap = Object.fromEntries((profiles || []).map((p: { id: string; username: string }) => [p.id, p.username]));
    setComments(data.map((c: { id: string; user_id: string; content: string; created_at: string; }) => ({ ...c, username: umap[c.user_id] || 'anon' })));
  }, [id]);

  const handleToggleComments = useCallback(() => {
    Haptics.selectionAsync();
    const next = !showComments;
    setShowComments(next);
    if (next) loadComments();
  }, [showComments, loadComments]);

  const handleSubmitComment = useCallback(async () => {
    if (!commentText.trim() || submittingComment || !user) return;
    setSubmittingComment(true);
    const content = commentText.trim();
    const tempId = `temp_${Date.now()}`;

    // Optimistic Update
    const optimisticComment: ListComment = {
      id: tempId,
      user_id: user.id,
      username: user.username || 'anon',
      content,
      created_at: new Date().toISOString()
    };

    setComments(prev => [...prev, optimisticComment]);
    setCommentText('');
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);

    try {
      const { data, error } = await supabase.from('list_comments').insert([{
        user_id: user.id, list_id: id, content
      }]).select().single();

      if (error) throw error;

      // Swap temp with real
      setComments(prev => prev.map(c => c.id === tempId ? { ...c, id: data.id } : c));

      // Notify list owner
      const { data: listInfo } = await supabase.from('lists').select('user_id, title').eq('id', id).single();
      if (listInfo && String(listInfo.user_id) !== String(user.id)) {
        supabase.from('notifications').insert({
          user_id: listInfo.user_id,
          type: 'comment',
          from_username: user.username,
          message: `@${user.username} critiqued your stack "${listInfo.title || 'Untitled'}"`,
          read: false,
        });
      }
    } catch (err: unknown) {
      // Rollback
      setComments(prev => prev.filter(c => c.id !== tempId));
      setCommentText(content);
      reelToast.error('Your critique could not be filed.');
    } finally {
      setSubmittingComment(false);
    }
  }, [commentText, submittingComment, user, id]);

  // ── SHARE TO LOUNGE ──
  const handleOpenShareLounge = useCallback(async () => {
    Haptics.selectionAsync();
    setShowLoungeShare(true);
    setLoadingLounges(true);
    try {
      const { data } = await supabase
        .from('lounge_members')
        .select('lounge_id')
        .eq('user_id', user?.id);
      if (data && data.length > 0) {
        const loungeIds = data.map((r: { lounge_id: string }) => r.lounge_id);
        const { data: loungeData } = await supabase
          .from('lounges')
          .select('id, name, cover_image, is_private')
          .in('id', loungeIds);
        setLounges(loungeData || []);
      } else {
        setLounges([]);
      }
    } catch (err: unknown) {
      setLounges([]);
    } finally {
      setLoadingLounges(false);
    }
  }, [user?.id]);

  const handleShareToLounge = async (loungeId: string) => {
    if (sharingTo || !list) return;
    setSharingTo(loungeId);
    try {
      const caption = `${list.title} · ${list.films.length} films · by @${list.user}`;
      await supabase.from('lounge_messages').insert({
        lounge_id: loungeId,
        user_id: user?.id,
        username: user?.username || 'anon',
        content: caption,
        type: 'list_share',
        metadata: {
          listId: list.id,
          title: list.title,
          filmCount: list.films.length,
          curator: list.user,
          topPosters: list.films.slice(0, 4).map((f: FilmItem) => f.poster_path),
        },
      });
      Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
      reelToast.success('Dispatched to the parlour.');
      setTimeout(() => setShowLoungeShare(false), 800);
    } catch (err: unknown) {
      reelToast.error('Dispatch failed. The courier is delayed.');
    }
    setSharingTo(null);
  };

  const handleDelete = useCallback(() => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Heavy);
    Alert.alert(
      'Incinerate Stack',
      'This will permanently destroy this collection. This action is irreversible.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Incinerate',
          style: 'destructive',
          onPress: async () => {
            try {
              await deleteList(id);
              Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning);
              router.back();
            } catch (err: unknown) {
              reelToast.error('The collection resists destruction.');
            }
          },
        },
      ]
    );
  }, [id, deleteList, router]);

  if (loading || !list) {
    return (
      <View style={s.container}>
        <View style={[s.navBar, { zIndex: 10 }]}>
          <TouchableOpacity onPress={() => router.back()} style={s.backBtn}>
            <ArrowLeft size={20} color={colors.bone} />
          </TouchableOpacity>
        </View>
        <View style={s.loadingCenter}>
          <ActivityIndicator size="large" color={colors.sepia} />
        </View>
      </View>
    );
  }

  const handlePressFilm = useCallback((filmId: number) => {
    Haptics.selectionAsync();
    router.push(`/film/${filmId}` as any);
  }, [router]);

  const renderItem = useCallback(({ item, index }: { item: FilmItem; index: number }) => {
    return (
      <StackDetailFilmCard 
        item={item} 
        index={index} 
        isLogged={loggedIds.has(item.id)} 
        isRanked={!!list?.isRanked} 
        onPress={handlePressFilm} 
      />
    );
  }, [loggedIds, list?.isRanked, handlePressFilm]);

  const heroPoster = list.films.length > 0 && list.films[0].poster_path 
    ? tmdb.poster(list.films[0].poster_path, 'w780') 
    : null;

  return (
    <KeyboardAvoidingView 
      style={s.container}
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      keyboardVerticalOffset={Platform.OS === 'ios' ? 0 : 0}
    >
      {/* Absolute Dynamic Nav Bar */}
      <View style={s.navBar}>
        <AnimatedBlurView intensity={80} tint="dark" style={[StyleSheet.absoluteFill, navBlurStyle]} />
        <View style={s.navInner}>
          <TouchableOpacity onPress={() => router.back()} style={s.backBtn} activeOpacity={0.7} hitSlop={{top: 20, bottom: 20, left: 20, right: 20}}>
            <ArrowLeft size={20} color={colors.bone} />
          </TouchableOpacity>
          {isOwner && (
            <View style={s.headerActions}>
              <TouchableOpacity style={s.actionBtn} onPress={() => { Haptics.selectionAsync(); router.push({ pathname: '/list-modal', params: { editId: id } } as import('expo-router').Href); }} activeOpacity={0.7} hitSlop={{top: 15, bottom: 15, left: 15, right: 15}}>
                <Edit3 size={18} color={colors.fog} />
              </TouchableOpacity>
              <TouchableOpacity style={s.actionBtn} onPress={handleDelete} activeOpacity={0.7} hitSlop={{top: 15, bottom: 15, left: 15, right: 15}}>
                <Trash2 size={18} color="rgba(231,76,60,0.8)" />
              </TouchableOpacity>
            </View>
          )}
        </View>
      </View>

      <AnimatedFlashList
        data={list.films}
        keyExtractor={(item: any) => String(item.id)}
        numColumns={3}
        contentContainerStyle={s.scrollContent}
        onScroll={scrollHandler}
        scrollEventThrottle={16}
        showsVerticalScrollIndicator={false}
        estimatedItemSize={200}
        removeClippedSubviews={true}
        ListHeaderComponent={
          <>
            {/* Parallax Image Background */}
            <Animated.View style={[s.parallaxHeader, headerStyle]}>
              {heroPoster && (
                <Image source={heroPoster} style={StyleSheet.absoluteFillObject} contentFit="cover" blurRadius={20} cachePolicy="memory-disk" />
              )}
              <LinearGradient 
                colors={['rgba(10, 7, 3, 0.4)', 'rgba(10, 7, 3, 0.9)', colors.ink]}
                locations={[0, 0.6, 1]}
                style={StyleSheet.absoluteFillObject}
              />
            </Animated.View>

            {/* Content Overlaid on Header */}
            <View style={s.headerContentWrap}>

              <Animated.Text entering={FadeInDown.duration(600).delay(100)} style={s.title} numberOfLines={3} adjustsFontSizeToFit minimumFontScale={0.7}>
                {list.title.toUpperCase()}
              </Animated.Text>

              <Animated.View entering={FadeInDown.duration(600).delay(200)} style={s.metaRow}>
                <View style={s.curatorDot} />
                <Text style={[s.metaText, { flexShrink: 1, marginRight: 8 }]} numberOfLines={1}>@{list.user.toUpperCase()}</Text>
                <Text style={s.metaText}>·  {list.films.length} ENTRIES</Text>
                {list.isRanked && (
                  <>
                    <Text style={s.metaText}>  ·  </Text>
                    <Text style={[s.metaText, { color: colors.sepia }]}>✦ RANKED</Text>
                  </>
                )}
              </Animated.View>

              {list.description && (
                <Animated.Text entering={FadeInDown.duration(600).delay(300)} style={s.desc}>
                  {list.description}
                </Animated.Text>
              )}

              {/* ── ACTION BAR: Certify · Critic · Share to Lounge ── */}
              <Animated.View entering={FadeInDown.duration(600).delay(350)} style={s.actionBar}>
                <TouchableOpacity style={s.actionItem} onPress={handleCertify} activeOpacity={0.7}>
                  <Award size={16} color={isCertified ? colors.sepia : colors.fog} fill={isCertified ? colors.sepia : 'none'} />
                  <Text style={[s.actionLabel, isCertified && s.actionLabelActive]} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.8}>
                    {certifyCount > 0 ? `${certifyCount} ` : ''}{isCertified ? 'CERTIFIED' : 'CERTIFY'}
                  </Text>
                </TouchableOpacity>

                <View style={s.actionDivider} />

                <TouchableOpacity style={s.actionItem} onPress={handleToggleComments} activeOpacity={0.7}>
                  <MessageCircle size={14} color={showComments ? colors.sepia : colors.fog} />
                  <Text style={[s.actionLabel, showComments && s.actionLabelActive]} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.8}>CRITIC</Text>
                </TouchableOpacity>

                <View style={s.actionDivider} />

                <TouchableOpacity style={s.actionItem} onPress={handleOpenShareLounge} activeOpacity={0.7}>
                  <Send size={14} color={colors.fog} />
                  <Text style={s.actionLabel} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.8}>LOUNGE</Text>
                </TouchableOpacity>
              </Animated.View>

              {/* ── COMMENTS PANEL ── */}
              {showComments && (
                <Animated.View entering={FadeInDown.duration(300)} style={s.commentsPanel}>
                  {comments.length === 0 && (
                    <Text style={s.commentEmpty}>No remarks yet. Be the first to speak.</Text>
                  )}
                  {comments.map(c => (
                    <StackCommentRow key={c.id} c={c} />
                  ))}
                  {user && (
                    <View style={s.commentInputRow}>
                      <TextInput
                        style={s.commentInput}
                        placeholder="Leave a remark..."
                        placeholderTextColor={colors.ash}
                        value={commentText}
                        onChangeText={handleCommentTextChange}
                        returnKeyType="send"
                        onSubmitEditing={handleSubmitComment}
                        maxLength={500}
                        selectionColor={'rgba(218,165,32,0.3)'}
                        cursorColor={colors.sepia}
                        disableFullscreenUI={true}
                        keyboardAppearance="dark"
                        accessibilityLabel="Stack comment"
                      />
                      <TouchableOpacity onPress={handleSubmitComment} disabled={submittingComment || !commentText.trim()} style={[s.commentSendBtn, (!commentText.trim()) && s.sendBtnDisabled]}>
                        <Send size={14} color={colors.sepia} />
                      </TouchableOpacity>
                    </View>
                  )}
                </Animated.View>
              )}

              <View style={s.trackRow}>
                <Text style={s.trackLabel}>INDEXED REELS</Text>
                <View style={s.trackLine} />
              </View>
            </View>
          </>
        }
        renderItem={renderItem as any}
        ListEmptyComponent={
          <View style={s.emptyState}>
            <Text style={s.emptyTitle}>Archive Empty</Text>
            <Text style={s.emptySubtitle}>No films have been added to this collection.</Text>
          </View>
        }
      />

      {/* ── SHARE TO LOUNGE MODAL ── */}
      {showLoungeShare && (
        <View style={s.loungeOverlay}>
          <TouchableOpacity style={StyleSheet.absoluteFill} activeOpacity={1} onPress={() => setShowLoungeShare(false)} />
          <View style={s.loungeSheet}>
            <View style={s.loungeHeader}>
              <Send size={14} color={colors.sepia} />
              <Text style={s.loungeTitle}>SHARE TO LOUNGE</Text>
              <TouchableOpacity onPress={() => setShowLoungeShare(false)} hitSlop={{top: 20, bottom: 20, left: 20, right: 20}}>
                <Text style={s.loungeClose}>✕</Text>
              </TouchableOpacity>
            </View>
            {loadingLounges ? (
              <View style={s.loungeEmptyWrap}>
                <ActivityIndicator size="small" color={colors.sepia} />
              </View>
            ) : lounges.length === 0 ? (
              <View style={s.loungeEmptyWrap}>
                <Text style={s.loungeEmptyText}>No lounges found. Join or create one first.</Text>
              </View>
            ) : (
              lounges.map(lounge => (
                <TouchableOpacity
                  key={lounge.id}
                  style={s.loungeRow}
                  activeOpacity={0.7}
                  onPress={() => handleShareToLounge(lounge.id)}
                  disabled={!!sharingTo}
                >
                  <View style={s.loungeAvatar}>
                    {lounge.cover_image ? (
                      <Image source={tmdb.poster(lounge.cover_image, 'w92')} style={s.loungeAvatarImg} contentFit="cover" cachePolicy="memory-disk" />
                    ) : (
                      <MessageCircle size={12} color={colors.sepia} />
                    )}
                  </View>
                  <Text style={s.loungeName} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.8}>{lounge.name}</Text>
                  <View style={s.loungeSendIcon}>
                    {sharingTo === lounge.id ? (
                      <ActivityIndicator size="small" color={colors.sepia} />
                    ) : (
                      <Send size={12} color={colors.sepia} />
                    )}
                  </View>
                </TouchableOpacity>
              ))
            )}
          </View>
        </View>
      )}
    </KeyboardAvoidingView>
  );
}

