const SEPIA_HASH = 'LGF5]+Yk^6#M@-5c,1J5@[or[Q6.';

type ProfileTab = 'archive' | 'ledger' | 'watchlist' | 'lists' | 'physical' | 'passport' | 'projector' | 'calendar';


