/**
 * SkeletonPulse — Breathing opacity shimmer for loading states.
 * Uses gentle opacity pulse (0.06 → 0.15 → 0.06) instead of
 * GPU-heavy gradient sweeps. Matches the Preloader ring breathing.
 */
import React, { useEffect } from 'react';
import { ViewStyle, StyleProp } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withRepeat,
  withSequence,
  withTiming,
  Easing,
} from 'react-native-reanimated';
import { colors } from '@/src/theme/theme';

interface SkeletonPulseProps {
  style?: StyleProp<ViewStyle>;
  /** Base color. Default: colors.ash */
  color?: string;
  /** Width. Default: '100%' */
  width?: number | string;
  /** Height. Default: 12 */
  height?: number;
  /** Border radius. Default: 3 */
  borderRadius?: number;
}

export default function SkeletonPulse({
  style,
  color = 'rgba(42,33,24,0.85)',
  width = '100%',
  height = 12,
  borderRadius = 3,
}: SkeletonPulseProps) {
  const opacity = useSharedValue(0.06);

  useEffect(() => {
    opacity.value = withRepeat(
      withSequence(
        withTiming(0.18, { duration: 900, easing: Easing.inOut(Easing.ease) }),
        withTiming(0.06, { duration: 900, easing: Easing.inOut(Easing.ease) }),
      ),
      -1,
      false,
    );
  }, []);

  const animatedStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
  }));

  return (
    <Animated.View
      style={[
        {
          backgroundColor: color,
          width: width as import('react-native').DimensionValue,
          height,
          borderRadius,
        },
        animatedStyle,
        style,
      ]}
    />
  );
}

/**
 * SkeletonShimmer — Nitrate Noir themed loading placeholder.
 *
 * A Reanimated-driven linear gradient shimmer that sweeps across
 * placeholder boxes. Dark-to-sepia-to-dark sweep, not the generic
 * grey pulse that every other app uses.
 *
 * Usage:
 *   <SkeletonShimmer width={100} height={150} />
 *   <SkeletonShimmer width="100%" height={44} borderRadius={2} />
 *   <SkeletonShimmer count={4} width={80} height={120} /> // renders 4 side-by-side
 */
import React, { memo, useEffect } from 'react';
import { View, StyleSheet, ViewStyle } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withRepeat,
  withTiming,
  Easing,
  interpolate,
} from 'react-native-reanimated';
import { colors } from '@/src/theme/theme';

interface SkeletonShimmerProps {
  width: number | string;
  height: number | string;
  borderRadius?: number;
  count?: number;
  gap?: number;
  style?: ViewStyle;
}

const ShimmerBox = memo(function ShimmerBox({
  width,
  height,
  borderRadius = 2,
  style,
}: Omit<SkeletonShimmerProps, 'count' | 'gap'>) {
  const shimmer = useSharedValue(0);

  useEffect(() => {
    shimmer.value = withRepeat(
      withTiming(1, { duration: 1800, easing: Easing.inOut(Easing.ease) }),
      -1,
      true
    );
  }, []);

  const shimmerStyle = useAnimatedStyle(() => ({
    opacity: interpolate(shimmer.value, [0, 0.5, 1], [0.3, 0.6, 0.3]),
    backgroundColor: `rgba(139, 105, 20, ${interpolate(
      shimmer.value,
      [0, 0.5, 1],
      [0.04, 0.12, 0.04]
    )})`,
  }));

  return (
    <Animated.View
      style={[
        {
          width: width as any,
          height: height as any,
          borderRadius,
          borderWidth: 1,
          borderColor: 'rgba(139,105,20,0.08)',
          overflow: 'hidden',
        },
        shimmerStyle,
        style,
      ]}
    />
  );
});

export default memo(function SkeletonShimmer({
  width,
  height,
  borderRadius = 2,
  count = 1,
  gap = 8,
  style,
}: SkeletonShimmerProps) {
  if (count === 1) {
    return (
      <ShimmerBox
        width={width}
        height={height}
        borderRadius={borderRadius}
        style={style}
      />
    );
  }

  return (
    <View style={[styles.row, { gap }, style]}>
      {Array.from({ length: count }, (_, i) => (
        <ShimmerBox
          key={i}
          width={width}
          height={height}
          borderRadius={borderRadius}
        />
      ))}
    </View>
  );
});

