      <View style={st.wireItemInner}>
        <Text style={st.wireCategory} numberOfLines={1}>[{item.category ?? 'WIRE'}]</Text>
        <Text style={st.wireTitle} numberOfLines={2}>{item.title}</Text>
        <Text style={st.wireExcerpt} numberOfLines={2}>{item.excerpt}</Text>
        <Text style={st.wireMeta} numberOfLines={1}>
          {item.date} · {item.time} · BY {(item.author ?? 'THE ORACLE').toUpperCase()}
        </Text>
      </View>
    </PressableScale>
  );
});

import { memo, useEffect } from 'react';
import { View, Text, StyleSheet } from 'react-native';
import { useRouter } from 'expo-router';
import Animated, { useSharedValue, useAnimatedStyle, withRepeat, withTiming, Easing, cancelAnimation } from 'react-native-reanimated';
import { Image } from 'expo-image';
import { LinearGradient } from 'expo-linear-gradient';
import { Radio, Star } from 'lucide-react-native';

import { colors, SEPIA_HASH } from '@/src/theme/theme';
import PressableScale from '@/src/components/PressableScale';
import { DispatchFilm } from './types';
import { daysSinceEpoch, volumeNumber, transmissionNum } from './utils';
import { st } from './styles';

const TMDB_IMG_W780 = 'https://image.tmdb.org/t/p/w780';

export const NightlyTransmission = memo(function NightlyTransmission({ films }: { films: DispatchFilm[] }) {
  const router = useRouter();
  const day = daysSinceEpoch();
  const film = films.length > 0 ? films[day % films.length] : null;
  const txNum = transmissionNum();

  const scale = useSharedValue(1);
  const blink = useSharedValue(0.2);

  useEffect(() => {
    // 30-second continuous breathe
    scale.value = withRepeat(
      withTiming(1.08, { duration: 30000, easing: Easing.inOut(Easing.sin) }),
      -1,
      true
    );
    blink.value = withRepeat(
      withTiming(1, { duration: 800, easing: Easing.inOut(Easing.ease) }),
      -1,
      true
    );
    return () => {
      cancelAnimation(scale);
      cancelAnimation(blink);
    };
  }, []);

  const animatedImgStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
  }));
  const animatedBlinkStyle = useAnimatedStyle(() => ({ opacity: blink.value }));

  if (!film) return null;

  const backdropUri = film.backdrop_path ? `${TMDB_IMG_W780}${film.backdrop_path}` : null;

  return (
    <PressableScale
      style={st.transmissionWrap}
      onPress={() => router.push(`/film/${film.id}` as any)}
      pressedScale={0.97}
      haptic="medium"
      accessibilityRole="button"
      accessibilityLabel={`Nightly transmission: ${film.title}`}
    >
      <View style={st.transmissionImageContainer}>
        {backdropUri && (
          <Animated.View style={[StyleSheet.absoluteFillObject, animatedImgStyle]}>
            <Image 
              source={{ uri: backdropUri }} 
              style={StyleSheet.absoluteFillObject} 
              cachePolicy="memory-disk" 
              placeholder={{ blurhash: SEPIA_HASH }} 
              transition={800} 
            />
          </Animated.View>
        )}
        <LinearGradient 
          colors={['transparent', 'rgba(10,7,3,0.5)', 'rgba(10,7,3,0.95)', colors.ink]} 
          locations={[0, 0.4, 0.8, 1]}
          style={StyleSheet.absoluteFillObject} 
        />
        {/* Subtle noise grain could go here but Native performance dictates avoiding massive overlapping arrays. */}
      </View>

      <View style={st.transmissionContent}>
        <View style={st.transmissionSignalRow}>
          <Animated.View style={animatedBlinkStyle}>
            <Radio size={12} color={colors.bloodReel} strokeWidth={2.5} />
          </Animated.View>
          <Text style={st.transmissionSignal}>[ TRANSMISSION LIVE ]</Text>
        </View>

        <Text style={st.transmissionTitle} numberOfLines={2}>
          {(film.title ?? '').toUpperCase()}
        </Text>

        <View style={st.transmissionMetaRow}>
          <Text style={st.transmissionMeta} numberOfLines={1}>VOL. {volumeNumber()} · № {txNum}</Text>
          <Star size={7} color={colors.sepia} strokeWidth={2} fill={colors.sepia} />
          <Text style={st.transmissionMeta} numberOfLines={1}>{(film.release_date || '').slice(0, 4)}</Text>
        </View>

        <Text style={st.transmissionExcerpt} numberOfLines={4}>
          "{film.overview}"
        </Text>

        <View style={st.transmissionFooter}>
          <View style={st.transmissionBullet}>
            <Text style={st.transmissionFooterText} numberOfLines={1}>[ INITIATE VIEWING SEQUENCE ]</Text>
          </View>
        </View>
      </View>
    </PressableScale>
  );
});

import React, { useCallback, useState } from 'react';
import { View, Text, StyleSheet } from 'react-native';
import * as Haptics from 'expo-haptics';
import { useRouter } from 'expo-router';
import { Heart, MessageSquare, Edit3, Bookmark, MessageCircle } from 'lucide-react-native';
import { useFilmStore } from '@/src/stores/films';
import { useAuthStore } from '@/src/stores/auth';
import { colors, fonts } from '@/src/theme/theme';
import reelToast from '@/src/utils/reelToast';
import PressableScale from '@/src/components/PressableScale';
import ShareToLoungeModal from '@/src/components/ShareToLoungeModal';
import Animated, { useSharedValue, useAnimatedStyle, withSpring, withSequence } from 'react-native-reanimated';

interface ActionDeckProps {
  itemId: string;
  filmId: number;
  filmTitle: string;
  posterPath: string | null;
  year?: number;
  ownerUsername: string;
}

export const ActionDeck = React.memo(function ActionDeck({
  itemId,
  filmId,
  filmTitle,
  posterPath,
  year,
  ownerUsername,
}: ActionDeckProps) {
  const router = useRouter();

  // Zustand slices purely for THIS specific component. ActivityCard won't re-render.
  const { hasEndorsed, toggleEndorse, _watchlistIndex, addToWatchlist, removeFromWatchlist } = useFilmStore();
  const { user: currentUser } = useAuthStore();

  const [showShareModal, setShowShareModal] = useState(false);

  const endorsed = hasEndorsed(itemId);
  const filmSaved = !!_watchlistIndex[filmId];
  const isOwner = currentUser?.username === ownerUsername;
  const isLoungeEligible = currentUser && ['archivist', 'auteur'].includes(currentUser.role ?? '');

  const heartScale = useSharedValue(1);
  const bookmarkScale = useSharedValue(1);

  const animatedHeartStyle = useAnimatedStyle(() => ({
    transform: [{ scale: heartScale.value }]
  }));
  const animatedBookmarkStyle = useAnimatedStyle(() => ({
    transform: [{ scale: bookmarkScale.value }]
  }));

  const handleCertify = useCallback(() => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    toggleEndorse(itemId);
    heartScale.value = withSequence(
      withSpring(1.5, { damping: 12, stiffness: 400 }),
      withSpring(1, { damping: 14, stiffness: 300 })
    );
  }, [itemId, toggleEndorse, heartScale]);

  const handleCritique = useCallback(() => {
    Haptics.selectionAsync();
    router.push(`/log/${itemId}` as any);
  }, [itemId, router]);

  const handleSaveOrEdit = useCallback(() => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    if (isOwner) {
      router.push({
        pathname: '/log-modal',
        params: {
          filmId: String(filmId),
          editLogId: itemId,
          filmTitle: filmTitle,
          filmPoster: posterPath ?? '',
          filmYear: year ? String(year) : '',
        },
      } as any);
    } else {
      if (filmSaved) {
        removeFromWatchlist(filmId);
        reelToast.success('Removed from watchlist');
      } else {
        addToWatchlist({
          id: filmId,
          title: filmTitle,
          poster_path: posterPath,
          release_date: year ? `${year}-01-01` : undefined,
        });
        reelToast.success('Saved to watchlist ✦');
      }
      bookmarkScale.value = withSequence(
        withSpring(1.4, { damping: 12, stiffness: 400 }),
        withSpring(1, { damping: 14, stiffness: 300 })
      );
    }
  }, [isOwner, filmSaved, addToWatchlist, removeFromWatchlist, router, filmId, itemId, filmTitle, posterPath, year, bookmarkScale]);

  const handleLounge = useCallback(() => {
    if (!isLoungeEligible) {
      Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning);
      reelToast.error('Archivist or Auteur tier required to share to The Lounge.');
      return;
    }
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    setShowShareModal(true);
  }, [isLoungeEligible]);

  return (
    <>
      <View style={s.actionDeck}>
        <PressableScale style={s.actionBtn} onPress={handleCertify} haptic="medium" pressedScale={0.92}>
          <Animated.View style={animatedHeartStyle}>
            <Heart size={16} strokeWidth={2} color={endorsed ? colors.bloodReel : colors.fog} fill={endorsed ? colors.bloodReel : 'transparent'} />
          </Animated.View>
          <Text style={[s.actionLabel, endorsed && s.actionLabelCertified]}>{endorsed ? 'CERTIFIED' : 'CERT'}</Text>
        </PressableScale>

        <PressableScale style={s.actionBtn} onPress={handleCritique} haptic="light">
          <MessageSquare size={16} strokeWidth={2} color={colors.fog} />
          <Text style={s.actionLabel}>CRITIQUE</Text>
        </PressableScale>

        <PressableScale style={s.actionBtn} onPress={handleSaveOrEdit} haptic="medium" pressedScale={0.92}>
          <Animated.View style={animatedBookmarkStyle}>
            {isOwner ? (
              <Edit3 size={16} strokeWidth={2} color={colors.fog} />
            ) : (
              <Bookmark size={16} strokeWidth={2} color={filmSaved ? colors.bloodReel : colors.fog} fill={filmSaved ? colors.bloodReel : 'transparent'} />
            )}
          </Animated.View>
          <Text style={[s.actionLabel, !isOwner && filmSaved && s.actionLabelCertified]}>{isOwner ? 'EDIT' : filmSaved ? 'SAVED' : 'SAVE'}</Text>
        </PressableScale>

        <PressableScale style={s.actionBtn} onPress={handleLounge} haptic="medium">
          <MessageCircle size={16} strokeWidth={2} color={isLoungeEligible ? colors.fog : colors.ash} />
          <Text style={[s.actionLabel, !isLoungeEligible && s.actionIconLocked]}>LOUNGE</Text>
        </PressableScale>
      </View>

      <ShareToLoungeModal
        visible={showShareModal}
        onClose={() => setShowShareModal(false)}
        filmTitle={filmTitle}
        filmId={String(filmId)}
        posterPath={posterPath}
      />
    </>
  );
});

const s = StyleSheet.create({
  actionDeck: {
    flexDirection: 'row',
    borderWidth: StyleSheet.hairlineWidth,
    borderColor: 'rgba(139,105,20,0.1)',
    backgroundColor: '#050403', // Deep soot
    borderRadius: 2,
    overflow: 'hidden',
    zIndex: 1,
    padding: 1,
    gap: StyleSheet.hairlineWidth,
  },
  actionBtn: {
    flex: 1,
    paddingVertical: 18,
    alignItems: 'center',
    justifyContent: 'center',
    gap: 6,
    backgroundColor: colors.ink,
    borderRadius: 1,
  },
  actionLabel: {
    fontFamily: fonts.ui,
    fontSize: 8,
    letterSpacing: 2,
    color: colors.fog,
  },
  actionLabelCertified: {
    color: colors.bloodReel,
  },
  actionIconLocked: {
    opacity: 0.3,
  },
});

