              </View>
            </View>
          )}

          {rent.length > 0 && (
            <View style={s.section}>
              <Text style={s.sectionLabel} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.8}>RENT</Text>
              <View style={s.grid}>
                {rent.slice(0, 6).map((p: Provider) => (
                  <ProviderLogo key={p.provider_id} p={p} providerLink={link} />
                ))}
              </View>
