          )}

          {buy.length > 0 && (
            <View style={s.section}>
              <Text style={s.sectionLabel} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.8}>BUY</Text>
              <View style={s.grid}>
                {buy.slice(0, 4).map((p: Provider) => (
