import { View, Text, StyleSheet, Share, Alert } from 'react-native';
import Animated, { FadeIn, FadeInDown } from 'react-native-reanimated';
import Svg, { Circle } from 'react-native-svg';
import * as Haptics from 'expo-haptics';
import { colors, fonts } from '@/src/theme/theme';
import PressableScale from '../PressableScale';

interface CinephileStats {
    count: number;
    level: string;
    color: string;
    progress: number;
}

interface ProjectorUser {
    username?: string;
}

const AnimatedView = Animated.createAnimatedComponent(View);

function StatDial({ count, color }: { count: number; color: string }) {
    const size = 140;
    const strokeWidth = 3;
    const radius = (size - strokeWidth) / 2;
    const circumference = 2 * Math.PI * radius;
    // Animate based on count: full circle at 100
    const progress = Math.min(count / 100, 1);

    return (
        <View style={[ds.dialWrap, { width: size, height: size }]}>
            <Svg width={size} height={size} style={{ position: 'absolute' }}>
                {/* Background track */}
                <Circle
                    cx={size / 2} cy={size / 2} r={radius}
                    fill="none" stroke="rgba(139,105,20,0.15)" strokeWidth={strokeWidth}
                />
                {/* Progress arc */}
                <Circle
                    cx={size / 2} cy={size / 2} r={radius}
                    fill="none" stroke={color} strokeWidth={strokeWidth}
                    strokeDasharray={`${circumference * progress} ${circumference * (1 - progress)}`}
                    strokeDashoffset={circumference * 0.25}
                    strokeLinecap="round"
                />
            </Svg>
            <Text style={[ds.dialValue, { color }]}>{count}</Text>
            <Text style={ds.dialLabel}>LIFETIME LOGS</Text>
        </View>
    );
}

