import { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import { useRouter, useLocalSearchParams } from 'expo-router';
import { useAuthStore } from '@/src/stores/auth';
import { useFilmStore } from '@/src/stores/films';
import { storage } from '../stores/mmkv-storage';
import * as Haptics from 'expo-haptics';
import { tmdb } from '@/src/lib/tmdb';
import reelToast from '@/src/utils/reelToast';
export interface LogSearchResult {
    id: number;
    title?: string;
    name?: string;
    poster_path?: string | null;
    release_date?: string;
    media_type?: string;
    vote_average?: number;
}

export interface SelectedFilm {
    id: number;
    title?: string;
    name?: string;
    poster_path?: string | null;
    release_date?: string;
}

export const DRAFT_KEY = 'reelhouse_log_draft';
export const AUTOPSY_INIT: Record<string, number> = { story: 0, script: 0, acting: 0, cinematography: 0, editing: 0, sound: 0 };
export const ABANDONED_REASONS = ['Too Slow', 'Too Upsetting', 'Life Got in the Way', "I'll Return Someday", 'Lost the Plot', 'Wrong Mood'];
export const AUTOPSY_LABELS: Record<string, string> = {
    story: 'STORY', script: 'SCRIPT/DIALOGUE', acting: 'ACTING/CHAR',
    cinematography: 'CINEMATOGRAPHY', editing: 'EDITING/PACING', sound: 'SOUND DESIGN',
};
export const PHYSICAL_OPTIONS = ['None', 'DVD', 'Blu-Ray', '4K UHD', 'VHS', 'Film Print'];
export const RATING_LABELS: Record<number, string> = {
    0.5: 'Unwatchable', 1: 'Unwatchable', 1.5: 'Not Great', 2: 'Not Great',
    2.5: 'Fine', 3: 'Fine', 3.5: 'Really Good', 4: 'Really Good',
    4.5: 'Masterpiece', 5: 'Masterpiece',
};

export function useLogFlow() {
    const router = useRouter();
    const params = useLocalSearchParams<{
        filmId?: string; editLogId?: string; filmTitle?: string; filmPoster?: string; filmYear?: string;
    }>();
    const { user, isAuthenticated } = useAuthStore();
    const { logs, lists, addLog, updateLog, removeLog, addFilmToList, removeFilmFromList, _loggedIndex } = useFilmStore();

    // ── Tier gating ──
    const isAuteur = user?.role === 'auteur';
    const isPremium = user?.role === 'archivist' || isAuteur;

    // ── Step state ──
    const [step, setStep] = useState(params.filmId ? 1 : 0);

    // ── Film state ──
    const [film, setFilm] = useState<SelectedFilm | null>(params.filmId ? {
        id: parseInt(params.filmId), title: params.filmTitle ?? '',
        poster_path: params.filmPoster ?? null, release_date: params.filmYear ?? '',
    } : null);

    // ── Detect rewatch mode: film already logged and NOT editing ──
    const previousLog = useMemo(() => {
        if (params.editLogId || !film?.id) return null;
        return _loggedIndex[film.id] ?? null;
    }, [film?.id, params.editLogId, _loggedIndex]);
    const isRewatchMode = !!previousLog;

    // ── Form state (matches web LogForm.tsx L37-60) ──
    const [status, setStatus] = useState<'watched' | 'rewatched' | 'abandoned'>(isRewatchMode ? 'rewatched' : 'watched');
    const [rating, setRating] = useState(0);
    const [review, setReview] = useState('');
    const [isSpoiler, setIsSpoiler] = useState(false);
    const [abandonedReason, setAbandonedReason] = useState('');
    const [date, setDate] = useState(new Date().toISOString().slice(0, 10));
    const [watchedWith, setWatchedWith] = useState('');
    const [privateNotes, setPrivateNotes] = useState('');
    const [physicalMedia, setPhysicalMedia] = useState('None');
    const [autopsy, setAutopsy] = useState<Record<string, number>>({ ...AUTOPSY_INIT });
    const [altPoster, setAltPoster] = useState<string | null>(null);
    const [editorialHeader, setEditorialHeader] = useState<string | null>(null);
    const [dropCap, setDropCap] = useState(false);
    const [pullQuote, setPullQuote] = useState('');
    const [autopsyOpen, setAutopsyOpen] = useState(false);
    const [isAutopsied, setIsAutopsied] = useState(false);
    const [moreOpen, setMoreOpen] = useState(true);
    const [calendarOpen, setCalendarOpen] = useState(false);
    const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
    const [submitting, setSubmitting] = useState(false);

    // ── Premium image data ──
    const [availablePosters, setAvailablePosters] = useState<Array<{ file_path: string }>>([]);
    const [availableBackdrops, setAvailableBackdrops] = useState<Array<{ file_path: string }>>([]);

    const editLogId = params.editLogId || null;
    const isEditing = !!editLogId;

    // ── Fetch images for premium features ──
    useEffect(() => {
        if (!film?.id) return;
        if (isAuteur || isPremium) {
            tmdb.movieImages(film.id).then((imgs: any) => {
                if (!imgs) return;
                if (imgs.posters) setAvailablePosters(imgs.posters.slice(0, 20));
                if (imgs.backdrops) setAvailableBackdrops(imgs.backdrops.slice(0, 10));
            }).catch((err: unknown) => { if (__DEV__) console.warn('[LogModal] image prefetch failed:', err); });
        }
    }, [film?.id, isAuteur, isPremium]);

    // ── Populate form from existing log in edit mode ──
    useEffect(() => {
        if (!editLogId) return;
        const log = logs.find(l => l.id === editLogId);
        if (!log) return;
        setStatus((log.status ?? 'watched') as 'watched' | 'rewatched' | 'abandoned');
        setRating(log.rating ?? 0);
        setReview(log.review ?? '');
        setIsSpoiler(log.isSpoiler ?? false);
        setDate(log.watchedDate?.slice(0, 10) ?? new Date().toISOString().slice(0, 10));
        setWatchedWith(log.watchedWith ?? '');
        setPrivateNotes(log.privateNotes ?? '');
        setPhysicalMedia(log.physicalMedia ?? 'None');
        setAbandonedReason(log.abandonedReason ?? '');
        if (log.autopsy) {
            try { setAutopsy(typeof log.autopsy === 'string' ? JSON.parse(log.autopsy) : log.autopsy); }
            catch (err: unknown) { setAutopsy({ ...AUTOPSY_INIT }); }
        }
        setAltPoster(log.altPoster ?? null);
        setEditorialHeader(log.editorialHeader ?? null);
        setDropCap(log.dropCap ?? false);
        setPullQuote(log.pullQuote ?? '');
        setIsAutopsied(log.isAutopsied ?? false);
        setAutopsyOpen(log.isAutopsied ?? false);
        setFilm({ id: log.filmId, title: log.title, poster_path: log.poster, release_date: log.year?.toString() });
        setStep(1);
    }, [editLogId, logs]);

    // ── Draft restore ──
    useEffect(() => {
        if (editLogId) return;
        const raw = storage.getString(DRAFT_KEY);
        if (raw) {
            try {
                const parsed = JSON.parse(raw);
                if (parsed.filmId === film?.id) {
                    if (parsed.review) setReview(parsed.review);
                    if (parsed.rating) setRating(parsed.rating);
                    if (parsed.privateNotes) setPrivateNotes(parsed.privateNotes);
                }
            } catch (err: unknown) { if (__DEV__) console.warn('[LogModal] draft restore failed:', err); }
        }
    }, [film?.id]);

    // ── Draft auto-save ──
    const draftTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    useEffect(() => {
        if (editLogId || !film?.id) return;
        if (draftTimerRef.current) clearTimeout(draftTimerRef.current);
        draftTimerRef.current = setTimeout(() => {
            if (review.trim() || rating > 0 || privateNotes.trim()) {
                storage.set(DRAFT_KEY, JSON.stringify({ filmId: film.id, review, rating, privateNotes }));
            }
        }, 1000);
        return () => { if (draftTimerRef.current) clearTimeout(draftTimerRef.current); };
    }, [review, rating, privateNotes, film?.id, editLogId]);

    // ── DRAFT HANDLERS ──
    const selectFilm = (f: LogSearchResult) => {
        setFilm({ id: f.id, title: f.title, name: f.name, poster_path: f.poster_path, release_date: f.release_date }); 
        setStep(1);
        Haptics.selectionAsync();
    };

    // ── SUBMIT LOG ──
    const handleLog = async () => {
        if (!user) { reelToast('Identification required to file a record.'); return; }
        if (!film) { reelToast('No film selected.'); return; }
        if (status !== 'abandoned' && rating === 0 && !review.trim()) {
            reelToast('A rating or critique is required to seal the record.');
            return;
        }
        if (status === 'abandoned' && !abandonedReason) {
            reelToast('Please specify a reason for abandoning this film.');
            return;
        }
        setSubmitting(true);
        try {
            const logData: Partial<import('@/src/types').FilmLog> = {
                filmId: film.id, title: film.title ?? film.name ?? 'Untitled',
                poster: altPoster ?? film.poster_path ?? null,
                year: film.release_date ? parseInt(film.release_date.slice(0, 4)) : undefined,
                rating: status === 'abandoned' ? 0 : rating, review: review.trim(), status, isSpoiler,
                watchedDate: date, watchedWith: watchedWith.trim() || null,  // intentional || — empty string should be null
                privateNotes: isPremium ? (privateNotes.trim() || null) : null,
                abandonedReason: status === 'abandoned' ? abandonedReason : null,
                physicalMedia: isPremium && physicalMedia !== 'None' ? physicalMedia : null,
                isAutopsied: isAuteur && isAutopsied,
                autopsy: isAuteur && isAutopsied ? JSON.stringify(autopsy) : null,
                altPoster: isAuteur ? altPoster : null,
                editorialHeader: isPremium ? editorialHeader : null,
                dropCap: isPremium ? dropCap : false,
                pullQuote: isPremium ? pullQuote.trim() : '',
            };
            if (isEditing && editLogId) { await updateLog(editLogId, logData); }
            else { await addLog(logData); }
            storage.delete(DRAFT_KEY);
            Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
            router.back();
        } catch (err: unknown) { reelToast.error('The record could not be sealed. Try again.'); }
        setSubmitting(false);
    };

    const handleDelete = async () => {
        if (!editLogId) return;
        try {
            await removeLog(editLogId);
            Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning);
            router.back();
        } catch {
            reelToast.error('Failed to delete log.');
        }
    };

    const toggleList = (listId: string) => {
        if (!film?.id) return;
        const list = lists.find(l => l.id === listId);
        if (!list) return;
        const isIn = list.films.some(f => f.id === film.id);
        if (isIn) removeFilmFromList(listId, film.id);
        else addFilmToList(listId, { id: film.id, title: film.title || '', poster_path: film.poster_path });
        Haptics.selectionAsync();
    };

    return {
        isAuthenticated,
        isAuteur,
        isPremium,
        step, setStep,
        film, setFilm,
        isRewatchMode, previousLog,
        status, setStatus,
        rating, setRating,
        review, setReview,
        isSpoiler, setIsSpoiler,
        abandonedReason, setAbandonedReason,
        date, setDate,
        watchedWith, setWatchedWith,
        privateNotes, setPrivateNotes,
        physicalMedia, setPhysicalMedia,
        autopsy, setAutopsy,
        altPoster, setAltPoster,
        editorialHeader, setEditorialHeader,
        dropCap, setDropCap,
        pullQuote, setPullQuote,
        autopsyOpen, setAutopsyOpen,
        isAutopsied, setIsAutopsied,
        moreOpen, setMoreOpen,
        calendarOpen, setCalendarOpen,
        showDeleteConfirm, setShowDeleteConfirm,
        submitting,
        availablePosters, availableBackdrops,
        isEditing,
        selectFilm,
        handleLog,
        handleDelete,
        toggleList,
        lists
    };
}

/**
 * RevenueCat — In-App Purchase & Subscription Management
 *
 * Apple/Google-compliant monetization layer for ReelHouse Society.
 * Handles subscription lifecycle, entitlement checks, restore purchases,
 * and syncs tier status back to Supabase.
 *
 * Setup instructions:
 * 1. Create a RevenueCat account at https://app.revenuecat.com
 * 2. Create iOS + Android app, configure products matching:
 *    - "archivist_monthly" ($1.99/mo)
 *    - "archivist_annual" ($19.99/yr)
 *    - "auteur_monthly" ($4.99/mo)
 *    - "auteur_annual" ($49.99/yr)
 *    - "founding_lifetime" ($49 one-time)
 * 3. Set EXPO_PUBLIC_REVENUECAT_IOS_KEY and EXPO_PUBLIC_REVENUECAT_ANDROID_KEY
 *    in your .env file
 * 4. Install: npx expo install react-native-purchases
 */

import { Platform } from 'react-native';
import { supabase } from './supabase';

// ── Type Definitions (no runtime dependency until package is installed) ──
// These mirror RevenueCat's actual types for type-safety before the package exists

export type ReelHouseTier = 'cinephile' | 'archivist' | 'auteur' | 'founding';

export interface EntitlementInfo {
  tier: ReelHouseTier;
  isActive: boolean;
  expiresAt: string | null;
  willRenew: boolean;
  productIdentifier: string | null;
}

// ── Configuration ──
const RC_IOS_KEY = process.env.EXPO_PUBLIC_REVENUECAT_IOS_KEY ?? '';
const RC_ANDROID_KEY = process.env.EXPO_PUBLIC_REVENUECAT_ANDROID_KEY ?? '';

let Purchases: any = null;
let isConfigured = false;

/**
 * Initialize RevenueCat — call once in _layout.tsx after auth restore.
 * Safe to call even if the package isn't installed (graceful no-op).
 */
export async function initRevenueCat(userId?: string): Promise<void> {
  const apiKey = Platform.OS === 'ios' ? RC_IOS_KEY : RC_ANDROID_KEY;

  if (!apiKey) {
    if (__DEV__) console.log('[RevenueCat] No API key configured — skipping');
    return;
  }

  try {
    // Dynamic import so the app doesn't crash if package isn't installed yet
    const RNPurchases = await import('react-native-purchases');
    Purchases = RNPurchases.default ?? RNPurchases;

    await Purchases.configure({ apiKey, appUserID: userId ?? null });
    isConfigured = true;

    if (__DEV__) console.log('[RevenueCat] Initialized successfully');
  } catch (err) {
    if (__DEV__) console.warn('[RevenueCat] Failed to initialize:', err);
  }
}

/**
 * Check current entitlements — returns the user's active tier.
 * Falls back to 'cinephile' (free) if no active subscription.
 */
export async function checkEntitlements(): Promise<EntitlementInfo> {
  const fallback: EntitlementInfo = {
    tier: 'cinephile',
    isActive: false,
    expiresAt: null,
    willRenew: false,
    productIdentifier: null,
  };

  if (!isConfigured || !Purchases) return fallback;

  try {
    const customerInfo = await Purchases.getCustomerInfo();
    const entitlements = customerInfo.entitlements?.active;

    if (!entitlements) return fallback;

    // Check in priority order: founding > auteur > archivist
    if (entitlements.founding) {
      return {
        tier: 'founding',
        isActive: true,
        expiresAt: null, // Lifetime
        willRenew: false,
        productIdentifier: entitlements.founding.productIdentifier,
      };
    }

    if (entitlements.auteur) {
      return {
        tier: 'auteur',
        isActive: true,
        expiresAt: entitlements.auteur.expirationDate ?? null,
        willRenew: !entitlements.auteur.willRenew === false,
        productIdentifier: entitlements.auteur.productIdentifier,
      };
    }

    if (entitlements.archivist) {
      return {
        tier: 'archivist',
        isActive: true,
        expiresAt: entitlements.archivist.expirationDate ?? null,
        willRenew: !entitlements.archivist.willRenew === false,
        productIdentifier: entitlements.archivist.productIdentifier,
      };
    }

    return fallback;
  } catch {
    return fallback;
  }
}

/**
 * Get available offerings (subscription packages).
 * Returns structured data ready for the membership screen UI.
 */
export async function getOfferings(): Promise<any[]> {
  if (!isConfigured || !Purchases) return [];

  try {
    const offerings = await Purchases.getOfferings();
    if (!offerings.current) return [];
    return offerings.current.availablePackages ?? [];
  } catch {
    return [];
  }
}

/**
 * Purchase a subscription package.
 * Returns the updated entitlement info on success.
 */
export async function purchasePackage(pkg: any): Promise<EntitlementInfo | null> {
  if (!isConfigured || !Purchases) return null;

  try {
    const { customerInfo } = await Purchases.purchasePackage(pkg);
    const entitlement = await checkEntitlements();

    // Sync tier to Supabase backend
    if (entitlement.isActive) {
      await syncEntitlementToSupabase(entitlement.tier);
    }

    return entitlement;
  } catch (err: any) {
    // User cancelled — not an error
    if (err?.userCancelled) return null;
    throw err;
  }
}

/**
 * Restore previous purchases — required by Apple for App Store compliance.
 * Use when a user reinstalls the app or switches devices.
 */
export async function restorePurchases(): Promise<EntitlementInfo> {
  const fallback: EntitlementInfo = {
    tier: 'cinephile',
    isActive: false,
    expiresAt: null,
    willRenew: false,
    productIdentifier: null,
  };

  if (!isConfigured || !Purchases) return fallback;

  try {
    await Purchases.restorePurchases();
    const entitlement = await checkEntitlements();

    // Sync restored tier to Supabase
    if (entitlement.isActive) {
      await syncEntitlementToSupabase(entitlement.tier);
    }

    return entitlement;
  } catch {
    return fallback;
  }
}

/**
 * Sync the entitlement tier to Supabase `profiles.role`.
 * This ensures the backend always has the current subscription status.
 */
async function syncEntitlementToSupabase(tier: ReelHouseTier): Promise<void> {
  try {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return;

    await supabase
      .from('profiles')
      .update({ role: tier })
      .eq('id', user.id);
  } catch {
    // Silently fail — the entitlement is still valid client-side
    // Will retry on next app open
  }
}

/**
 * Log the user into RevenueCat with their Supabase user ID.
 * Call after authentication to link purchases to the user.
 */
export async function identifyUser(userId: string): Promise<void> {
  if (!isConfigured || !Purchases) return;

  try {
    await Purchases.logIn(userId);
  } catch {
    // Non-critical — purchases still work without identification
  }
}

/**
 * Log the user out of RevenueCat.
 * Call on logout to prevent purchase association with wrong user.
 */
export async function logoutRevenueCat(): Promise<void> {
  if (!isConfigured || !Purchases) return;

  try {
    await Purchases.logOut();
  } catch {
    // Non-critical
  }
}

// ============================================================
// REELHOUSE MOBILE — TMDB API Client
// Resilient, cached, deduplicated — ported from web
// ============================================================

const TMDB_API_KEY = process.env.EXPO_PUBLIC_TMDB_API_KEY || '';
const TMDB_BASE = 'https://api.themoviedb.org/3';
const TMDB_IMG = 'https://image.tmdb.org/t/p';

// ── Response interfaces ──
interface TMDBWatchProvider {
    provider_id: number;
    provider_name: string;
    logo_path: string;
}

export interface TMDBWatchProviderResult {
    link?: string;
    flatrate?: TMDBWatchProvider[];
    rent?: TMDBWatchProvider[];
    buy?: TMDBWatchProvider[];
}

interface TMDBSearchResult {
    id: number;
    title?: string;
    name?: string;
    media_type?: string;
    poster_path?: string | null;
    profile_path?: string | null;
    popularity?: number;
    known_for?: TMDBSearchResult[];
    release_date?: string;
    vote_average?: number;
    vote_count?: number;
    known_for_department?: string;
    overview?: string;
}

interface TMDBSearchResponse {
    results: TMDBSearchResult[];
    total_results?: number;
    total_pages?: number;
    page?: number;
    searchType?: string;
    matchedContext?: string;
}

export interface CrewMember {
    id: number;
    job: string;
    name: string;
    profile_path?: string | null;
}

export interface CastMember {
    id: number;
    character: string;
    name: string;
    profile_path?: string | null;
}

export interface VideoResult {
    id: string;
    site: string;
    key: string;
    type: string;
    name?: string;
}

interface TMDBMovieDetail {
    id: number;
    title: string;
    overview?: string;
    poster_path?: string | null;
    backdrop_path?: string | null;
    release_date?: string;
    runtime?: number;
    vote_average?: number;
    genres?: Array<{ id: number; name: string }>;
    credits?: { cast?: CastMember[]; crew?: CrewMember[] };
    videos?: { results?: VideoResult[] };
    similar?: { results?: TMDBSearchResult[] };
    production_countries?: Array<{ iso_3166_1: string; name: string }>;
    production_companies?: Array<{ id: number; name: string; logo_path?: string | null; origin_country?: string }>;
    status?: string;
    original_language?: string;
    budget?: number;
    revenue?: number;
    tagline?: string;
    vote_count?: number;
    'watch/providers'?: { results?: Record<string, TMDBWatchProviderResult> };
    release_dates?: { results?: Array<{ iso_3166_1: string; release_dates: Array<{ certification: string }> }> };
    popularity?: number;
}

export type { TMDBMovieDetail };

interface TMDBMovieListResponse {
    results: TMDBSearchResult[];
    total_results?: number;
    total_pages?: number;
    page?: number;
}

interface TMDBPersonDetail {
    id: number;
    name: string;
    biography?: string;
    profile_path?: string | null;
    birthday?: string;
    deathday?: string | null;
    place_of_birth?: string;
    known_for_department?: string;
    also_known_as?: string[];
}

interface TMDBPersonCredits {
    cast?: TMDBSearchResult[];
    crew?: TMDBSearchResult[];
}

// ── Simple LRU cache (memory-only, 200 entries, 5min TTL) ──
const _cache = new Map<string, { data: unknown; ts: number }>();
const CACHE_TTL = 10 * 60 * 1000; // 10 minutes — optimized for high-traffic scalability
const MAX_CACHE = 500;             // 500 entries — supports 10M+ concurrent users

function cacheGet(key: string): unknown | undefined {
  const entry = _cache.get(key);
  if (!entry) return undefined;
  if (Date.now() - entry.ts > CACHE_TTL) { _cache.delete(key); return undefined; }
  return entry.data;
}

function cacheSet(key: string, data: unknown) {
  if (_cache.size >= MAX_CACHE) {
    const oldest = _cache.keys().next().value;
    if (oldest !== undefined) _cache.delete(oldest);
  }
  _cache.set(key, { data, ts: Date.now() });
}

// ── Inflight dedup ──
const _inflight = new Map<string, Promise<unknown>>();

async function fetchTMDB<T = unknown>(path: string, fallback: T | null = null): Promise<T | null> {
  const cached = cacheGet(path);
  if (cached !== undefined) return cached as T;

  const existing = _inflight.get(path);
  if (existing) return existing as Promise<T | null>;

  const promise = (async () => {
    for (let attempt = 0; attempt < 3; attempt++) {
      try {
        const sep = path.includes('?') ? '&' : '?';
        const url = `${TMDB_BASE}${path}${sep}api_key=${TMDB_API_KEY}`;
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), 10000);
        const res = await fetch(url, { signal: controller.signal });
        clearTimeout(timer);

        if (res.status === 429 || res.status === 503) {
          await new Promise(r => setTimeout(r, 500 * Math.pow(2, attempt)));
          continue;
        }
        if (!res.ok) return fallback;
        const data = await res.json();
        if (!path.includes('/search/')) cacheSet(path, data);
        return data as T;
      } catch (e: unknown) {
        if (e instanceof Error && e.name === 'AbortError') return fallback;
        if (attempt < 2) await new Promise(r => setTimeout(r, 500 * Math.pow(2, attempt)));
      }
    }
    return fallback;
  })();

  _inflight.set(path, promise);
  promise.finally(() => _inflight.delete(path));
  return promise;
}

export const tmdb = {
  // ── Search ──
  search: async (query: string, page = 1) => {
    // TIER 1: Omni-Search
    const res = await fetch(
        `${TMDB_BASE}/search/multi?query=${encodeURIComponent(query)}&page=${page}&include_adult=false&api_key=${TMDB_API_KEY}`
    );
    if (!res.ok) return { searchType: 'failed', results: [] };
    let data = await res.json();

    let items: TMDBSearchResult[] = [];
    let topPerson: string | null = null;

    if (data.results?.length > 0) {
        const sortedResults = [...data.results].sort((a: TMDBSearchResult, b: TMDBSearchResult) => {
            const aName = ((a.name || a.title) ?? '').toLowerCase();
            const bName = ((b.name || b.title) ?? '').toLowerCase();
            const queryLower = query.toLowerCase();

            const aExact = aName === queryLower;
            const bExact = bName === queryLower;
            if (aExact && !bExact) return -1;
            if (!aExact && bExact) return 1;

            if (a.media_type === 'person' && b.media_type !== 'person') return -1;
            if (a.media_type !== 'person' && b.media_type === 'person') return 1;

            return ((b.popularity ?? 0) - (a.popularity ?? 0));
        });

        for (const item of sortedResults) {
            if (item.media_type === 'movie') {
                items.push({ ...item, media_type: 'movie' });
            } else if (item.media_type === 'person') {
                const isExact = (item.name || '').toLowerCase() === query.toLowerCase();
                const hasPhoto = !!item.profile_path;
                const isHighPop = (item.popularity || 0) > 5;

                if (isExact || hasPhoto || isHighPop) {
                    if (!topPerson) topPerson = item.name;
                    items.push({ ...item, media_type: 'person' });
                }

                if (hasPhoto || isHighPop || isExact) {
                    const knownFor = item.known_for?.filter((k: TMDBSearchResult) => k.media_type === 'movie') || [];
                    items.push(...knownFor.map((m: TMDBSearchResult) => ({ ...m, media_type: 'movie' })));
                }
            }
        }

        if (items.length > 0 || page > 1) {
            const ids = new Set<string>();
            const unique = items.filter((m: TMDBSearchResult) => {
                const key = `${m.media_type || 'movie'}-${m.id}`;
                if (ids.has(key)) return false;
                ids.add(key);
                return true;
            });

            data.results = unique;

            const firstMatch = unique[0];
            const firstText = (firstMatch?.title || firstMatch?.name || '').toLowerCase();
            const queryText = query.toLowerCase();

            if (topPerson && !firstText.includes(queryText)) {
                data.searchType = 'person';
                data.matchedContext = topPerson;
            } else {
                data.searchType = 'exact';
            }
            return data;
        }
    }

    // TIER 2: Typo Fallback
    const cleanWords = query.toLowerCase().replace(/[^a-z0-9\s]/g, '').split(/\s+/).filter((w) => w.length > 0);
    if (cleanWords.length > 1) {
        const fallbacks = [];
        for (let i = 0; i < cleanWords.length; i++) {
            const words = [...cleanWords];
            const dropped = words.splice(i, 1)[0];
            const text = words.join(' ');
            if (text.length > 2) {
                fallbacks.push({ text, dropped });
            }
        }

        const fallbackResults = await Promise.all(fallbacks.map(async (fb) => {
            try {
                const fRes = await fetch(`${TMDB_BASE}/search/multi?query=${encodeURIComponent(fb.text)}&page=1&api_key=${TMDB_API_KEY}`);
                if (fRes.ok) {
                    const fData = await fRes.json();
                    if (fData.results?.length > 0) {
                        const bestItem = fData.results.sort((a: TMDBSearchResult, b: TMDBSearchResult) => ((b.popularity ?? 0) - (a.popularity ?? 0)))[0];
                        return { data: fData, fallback: fb, bestItem };
                    }
                }
            } catch { }
            return null;
        }));

        let winner = null;
        let highestPop = -1;
        for (const res of fallbackResults) {
            if (res && res.bestItem && res.bestItem.popularity > highestPop) {
                highestPop = res.bestItem.popularity;
                winner = res;
            }
        }

        if (winner) {
            const items: TMDBSearchResult[] = [];
            for (const item of winner.data.results) {
                if (item.media_type === 'movie') items.push({ ...item, media_type: 'movie' });
                else if (item.media_type === 'person') {
                    items.push({ ...item, media_type: 'person' });
                    const known = item.known_for?.filter((k: TMDBSearchResult) => k.media_type === 'movie') || [];
                    items.push(...known.map((k: TMDBSearchResult) => ({ ...k, media_type: 'movie' })));
                }
            }
            const ids = new Set<string>();
            winner.data.results = items.filter((m: TMDBSearchResult) => {
                const key = `${m.media_type || 'movie'}-${m.id}`;
                if (ids.has(key)) return false;
                ids.add(key); return true;
            });
            winner.data.searchType = 'typo';
            winner.data.matchedContext = `IGNORED "${winner.fallback.dropped.toUpperCase()}"`;
            return winner.data;
        }
    }

    // TIER 3: Semantic Logic
    const words = query.toLowerCase().replace(/[^a-z0-9\s]/g, '').split(/\s+/).filter((w: string) => w.length > 2);
    if (words.length > 0) {
        const keywordIds: number[] = [];
        await Promise.all(words.map(async (word: string) => {
            try {
                const kwRes = await fetch(`${TMDB_BASE}/search/keyword?query=${encodeURIComponent(word)}&api_key=${TMDB_API_KEY}`);
                const kwData = await kwRes.json();
                if (kwData.results?.length > 0) keywordIds.push(kwData.results[0].id);
            } catch { }
        }));
        if (keywordIds.length > 0) {
            const discoverRes = await fetch(`${TMDB_BASE}/discover/movie?with_keywords=${keywordIds.join('|')}&sort_by=popularity.desc&page=1&api_key=${TMDB_API_KEY}`);
            if (discoverRes.ok) {
                const discoverData = await discoverRes.json();
                if (discoverData.results?.length > 0) {
                    discoverData.searchType = 'semantic';
                    discoverData.matchedContext = words.join(', ');
                    return discoverData;
                }
            }
        }
    }

    data.searchType = 'failed';
    return data;
  },

  searchMulti: async (query: string) => {
    const data = await fetchTMDB<TMDBSearchResponse>(
      `/search/multi?query=${encodeURIComponent(query)}&page=1&include_adult=false`,
      { results: [] }
    );
    return (data?.results || [])
      .filter((r) => r.media_type === 'movie' || (r.media_type === 'person' && r.profile_path))
      .sort((a, b) => (b.popularity || 0) - (a.popularity || 0))
      .slice(0, 8);
  },

  // ── Film Details ──
  detail: async (id: number) => fetchTMDB<TMDBMovieDetail>(
    `/movie/${id}?append_to_response=credits,videos,similar,watch/providers,release_dates`,
    null
  ),

  // ── Trending ──
  trending: async (timeWindow = 'week') => fetchTMDB<TMDBMovieListResponse>(
    `/trending/movie/${timeWindow}`,
    { results: [] }
  ),

  // ── Top Rated ──
  topRated: async (page = 1) => fetchTMDB<TMDBMovieListResponse>(`/movie/top_rated?page=${page}`, { results: [] }),

  // ── Now Playing ──
  nowPlaying: async () => fetchTMDB<TMDBMovieListResponse>(`/movie/now_playing`, { results: [] }),

  // ── Similar ──
  similar: async (id: number) => {
    const data = await fetchTMDB<{ results: unknown[] }>(`/movie/${id}/similar?page=1`, { results: [] });
    return data?.results || [];
  },

  // ── Person ──
  person: async (id: number) => fetchTMDB<TMDBPersonDetail>(`/person/${id}`, null),
  personCredits: async (id: number) => fetchTMDB<TMDBPersonCredits>(`/person/${id}/movie_credits`, null),

  // ── Extended Missing Query Methods ──
  watchProviders: async (id: number) => {
      const data = await fetchTMDB<{ results: Record<string, TMDBWatchProviderResult> }>(`/movie/${id}/watch/providers`, { results: {} });
      return data?.results || {};
  },
  releaseDates: async (id: number) => {
      const data = await fetchTMDB<{ results: unknown[] }>(`/movie/${id}/release_dates`, { results: [] });
      return data?.results || [];
  },
  companySearch: async (query: string) => {
      const data = await fetchTMDB<{ results: unknown[] }>(`/search/company?query=${encodeURIComponent(query)}`, { results: [] });
      return data?.results || [];
  },
  movieImages: async (id: number) => fetchTMDB<{ posters: Array<{ file_path: string }>; backdrops: Array<{ file_path: string }>; logos: Array<{ file_path: string }> }>(`/movie/${id}/images`, { posters: [], backdrops: [], logos: [] }),

  // ── Discover ──
  discover: async (params: Record<string, string> = {}) => {
    const qs = Object.entries(params).map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&');
    return fetchTMDB<TMDBMovieListResponse>(`/discover/movie?${qs}`, { results: [] });
  },

  // ── Real-time News Proxy ──
  getNews: async () => {
        // Simple fallback
        const relDate = (daysAgo: number) => {
            const d = new Date();
            d.setDate(d.getDate() - daysAgo);
            return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }).toUpperCase();
        };

        const FALLBACK_NEWS = [
            {
                id: 'fb1',
                title: "OSCAR RADAR: The Monochrome Revival",
                excerpt: "Why modern auteurs are returning to black and white for their most personal statements. A deep look at this year's Academy favorites.",
                date: relDate(1),
                time: "10:30 AM",
                category: "AWARDS",
                author: "THE ARCHIVIST",
                link: "#",
                image: "https://images.unsplash.com/photo-1542204147-993abd55f2eb?q=80&w=2000"
            },
            {
                id: 'fb2',
                title: "CANNES UNVEILED: The Latest Selection",
                excerpt: "The festival returns to its roots with a heavy focus on European surrealism and South American neo-noir.",
                date: relDate(2),
                time: "02:15 PM",
                category: "FESTIVALS",
                author: "MIDNIGHT DEVOTEE",
                link: "#",
                image: "https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?q=80&w=2000"
            }
        ];

        const feeds = ['https://www.theguardian.com/film/rss'];
        try {
            const results = await Promise.all(feeds.map(async (url: string) => {
                try {
                    const controller = new AbortController();
                    const timer = setTimeout(() => controller.abort(), 4000);
                    const res = await fetch(`https://api.rss2json.com/v1/api.json?rss_url=${encodeURIComponent(url)}`, { signal: controller.signal });
                    clearTimeout(timer);
                    if (!res.ok) return [];
                    const data = await res.json();
                    return data.items || [];
                } catch {
                    return [];
                }
            }));

            const liveItems = results.flat();
            if (liveItems.length === 0) return FALLBACK_NEWS;

            const decodeEntities = (s: string) => s.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#039;/g, "'");

            interface RSSItem {
                guid?: string; link?: string; title: string; description?: string;
                pubDate: string; categories?: string[]; enclosure?: { link?: string };
                thumbnail?: string; author?: string;
            }
            const allItems = (liveItems as RSSItem[])
                .sort((a, b) => new Date(b.pubDate).getTime() - new Date(a.pubDate).getTime())
                .map((item) => ({
                    id: item.guid || item.link,
                    title: decodeEntities(item.title),
                    excerpt: decodeEntities((item.description?.replace(/<[^>]*>?/gm, '') ?? '').slice(0, 160)) + '...',
                    date: new Date(item.pubDate).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }).toUpperCase(),
                    time: new Date(item.pubDate).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }),
                    category: item.categories?.[0]?.toUpperCase() || 'WIRE',
                    image: item.enclosure?.link || item.thumbnail || null,
                    author: item.author || 'THE ORACLE',
                    link: item.link
                }));

            return [...allItems, ...FALLBACK_NEWS];
        } catch (e: unknown) {
            return FALLBACK_NEWS;
        }
    },

  // ── Image URLs ──
  poster: (path: string | null | undefined, size = 'w185') =>
    path ? `${TMDB_IMG}/${size}${path}` : undefined,

  backdrop: (path: string | null | undefined, size = 'w1280') =>
    path ? `${TMDB_IMG}/${size}${path}` : undefined,

  profile: (path: string | null | undefined, size = 'w185') =>
    path ? `${TMDB_IMG}/${size}${path}` : undefined,

  posterThumb: (path: string | null | undefined) =>
    path ? `${TMDB_IMG}/w92${path}` : undefined,
};

// ── Utility Functions ──
export function obscurityScore(movie: { popularity?: number }) {
  const pop = movie.popularity || 0;
  if (pop <= 0) return 99;
  const score = Math.round(100 - (Math.log10(Math.max(pop, 1)) / Math.log10(5000)) * 98);
  return Math.max(2, Math.min(99, score));
}

export function formatRuntime(minutes: number | null | undefined) {
  if (!minutes) return '—';
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return h ? `${h}h ${m}m` : `${m}m`;
}

export function getYear(dateStr: string | null | undefined) {
  return dateStr ? dateStr.slice(0, 4) : '—';
}

