import { create } from 'zustand';
import { supabase } from '../lib/supabase';
import { User } from '../types';
import { Alert, Platform } from 'react-native';
import { MMKV } from 'react-native-mmkv';
export { storage } from './mmkv-storage';
import * as Linking from 'expo-linking';

export interface AuthState {
  user: User | null;
  isAuthenticated: boolean;
  loading: boolean;
  login: (email: string, password: string) => Promise<void>;
  signup: (email: string, password: string, username: string, persona?: string) => Promise<{ needsConfirmation: boolean }>;
  logout: () => Promise<void>;
  updateUser: (updates: Partial<User>) => Promise<void>;
  setPreference: (key: string, value: unknown) => Promise<void>;
  getPreference: (key: string, fallback?: unknown) => unknown;
  restoreSession: () => Promise<void>;
  followUser: (targetUsername: string) => Promise<void>;
  unfollowUser: (targetUsername: string) => Promise<void>;
}

interface DBProfileUpdate {
  bio?: string;
  username?: string;
  avatar_url?: string;
  display_name?: string;
  is_social_private?: boolean;
}

// ── Action throttle: prevents spam-clicking social buttons ──
const _actionThrottles = new Map<string, number>();
const _THROTTLE_MAX = 200;
const _THROTTLE_TTL = 30000;
function pruneThrottles() {
  if (_actionThrottles.size < _THROTTLE_MAX) return;
  const now = Date.now();
  for (const [key, ts] of _actionThrottles) {
    if (now - ts > _THROTTLE_TTL) _actionThrottles.delete(key);
  }
  if (_actionThrottles.size >= _THROTTLE_MAX) {
    const oldest = _actionThrottles.keys().next().value;
    if (oldest !== undefined) _actionThrottles.delete(oldest);
  }
}

// ── Username → ID cache (with 10min TTL to prevent stale mappings) ──
const _usernameIdCache = new Map<string, { id: string; ts: number }>();
const _USERNAME_CACHE_TTL = 10 * 60 * 1000;
async function resolveUsernameToId(username: string): Promise<string | null> {
  const cached = _usernameIdCache.get(username);
  if (cached && Date.now() - cached.ts < _USERNAME_CACHE_TTL) return cached.id;
  if (cached) _usernameIdCache.delete(username);  // Expired — remove stale entry
  const { data } = await supabase.from('profiles').select('id').eq('username', username).single();
  if (data?.id) {
    if (_usernameIdCache.size >= 200) {
      const oldest = _usernameIdCache.keys().next().value;
      if (oldest !== undefined) _usernameIdCache.delete(oldest);
    }
    _usernameIdCache.set(username, { id: data.id, ts: Date.now() });
    return data.id;
  }
  return null;
}

export const useAuthStore = create<AuthState>()((set, get) => ({
  user: null,
  isAuthenticated: false,
  loading: true,

  restoreSession: async () => {
    try {
      // ── IRON VAULT CACHE: Instant RAM memory restoration before network ping ──
      let cachedFollowing: string[] = [];
      const vaultData = storage.getString('ironvault_user_cache');
      if (vaultData) {
        try {
          const parsedUser = JSON.parse(vaultData);
          cachedFollowing = parsedUser.following ?? [];
          set({ user: parsedUser, isAuthenticated: true, loading: false });
        } catch {}
      }

      const { data: { session } } = await supabase.auth.getSession();
      if (session?.user) {
        const { data: profile } = await supabase
          .from('profiles').select('id, username, role, bio, avatar_url, display_name, is_social_private, preferences, persona, created_at').eq('id', session.user.id).single();
        if (profile) {
          // CRITICAL: Preserve the cached following list — don't overwrite with []
          const completeUser = { ...session.user, ...profile, following: cachedFollowing } as unknown as User;
          storage.set('ironvault_user_cache', JSON.stringify(completeUser));
          set({ user: completeUser, isAuthenticated: true, loading: false });
          // Hydrate following from DB in background (authoritative source)
          hydrateFollowing();
          return;
        }
      }
    } catch (err: unknown) {
      console.warn('[restoreSession] Failed:', err instanceof Error ? err.message : String(err));
    }
    set({ loading: false });
  },

  login: async (email, password) => {
    // Support username login — resolve to email via RPC
    let loginEmail = email.trim();
    if (!loginEmail.includes('@')) {
      const lookupUsername = loginEmail.toLowerCase().replace(/\s+/g, '_');
      const { data: resolvedEmail, error: rpcError } = await supabase
        .rpc('get_email_by_username', { lookup_username: lookupUsername });
      if (rpcError || !resolvedEmail) throw new Error('No account found with that username.');
      loginEmail = resolvedEmail;
    }

    const { data, error } = await supabase.auth.signInWithPassword({ email: loginEmail, password });
    if (error) throw error;

    // Set auth immediately
    const completeUser = { ...data.user, following: [] } as unknown as User;
    storage.set('ironvault_user_cache', JSON.stringify(completeUser));
    set({ user: completeUser, isAuthenticated: true });

    // Enrich with profile in background
    Promise.resolve(supabase.from('profiles').select('id, username, role, bio, avatar_url, display_name, is_social_private, preferences, persona, created_at').eq('id', data.user.id).single())
      .then((res) => {
        if (res.data) {
           set((s) => {
             const updatedUser = s.user ? { ...s.user, ...res.data } : null;
             if (updatedUser) storage.set('ironvault_user_cache', JSON.stringify(updatedUser));
             return { user: updatedUser };
           });
        }
      }).catch(() => {});

    hydrateFollowing();
  },

  signup: async (email, password, username, persona = 'The Cinephile') => {
    // Build the redirect URL so confirmation emails deep-link back to the app
    const redirectTo = Linking.createURL('auth-callback');
    const { data, error } = await supabase.auth.signUp({
      email, password,
      options: {
        data: { username },
        emailRedirectTo: redirectTo,
      },
    });
    if (error) throw error;

    if (data?.session) {
      // Email confirmation disabled — immediate login
      await supabase.from('profiles').update({ username, persona }).eq('id', data.user!.id);
      const { data: profile } = await supabase.from('profiles').select('id, username, role, bio, avatar_url, display_name, is_social_private, preferences, persona, created_at').eq('id', data.user!.id).single();
      const completeUser = { ...data.user, ...profile, following: [] } as User;
      storage.set('ironvault_user_cache', JSON.stringify(completeUser));
      set({ user: completeUser, isAuthenticated: true });
      return { needsConfirmation: false };
    }
    // Email confirmation required
    return { needsConfirmation: true };
  },

  logout: async () => {
    // 1. Sign out from Supabase
    try { await supabase.auth.signOut(); } catch { /* continue */ }

    // 2. Clear zustand auth state
    set({ user: null, isAuthenticated: false });

    // 3. Nuclear cleanup — Clear ALL dependent stores to prevent cross-user data leakage
    //    Using lazy requires to avoid circular dependency (films.ts imports auth.ts)
    try {
      const { useFilmStore } = require('./films');
      useFilmStore.setState({
        logs: [], watchlist: [], lists: [], interactions: [], physicalArchive: [],
        _loggedIndex: {}, _watchlistIndex: {}, _endorsedIndex: {}, _listEndorsedIndex: {},
        _addLogMutex: false,
      });
    } catch { /* store may not be initialized */ }
    try {
      const { useNotificationStore } = require('./social');
      useNotificationStore.setState({ notifications: [], _unreadCount: 0 });
    } catch { /* store may not be initialized */ }
    try {
      const { useDispatchStore } = require('./content');
      useDispatchStore.setState({ dossiers: [], loading: false });
    } catch { /* store may not be initialized */ }
    try {
      const { useLoungeStore } = require('./lounge');
      useLoungeStore.setState({ lounges: [], currentMessages: [], currentLoungeId: null, loading: false, sending: false });
    } catch { /* store may not be initialized */ }
    try {
      const { useDiscoverStore } = require('./discover');
      useDiscoverStore.setState({ page: 1, mood: null, query: '', inputVal: '', accumulatedFilms: [], filters: { genreId: null, decade: null, sortBy: 'popularity.desc', language: null, minRating: 0, yearFrom: null, yearTo: null } });
    } catch { /* store may not be initialized */ }

    // 4. Clear user cache
    if (Platform.OS !== 'web') {
      storage.delete('ironvault_user_cache');
      storage.delete('reelhouse-offline-mutations');
    }
  },

  updateUser: async (updates) => {
    const user = get().user;
    if (!user) return;

    const throttleKey = `update:${user.id}`;
    const lastCall = _actionThrottles.get(throttleKey) ?? 0;
    if (Date.now() - lastCall < 1500) {
      // Slow down
      return;
    }
    pruneThrottles();
    _actionThrottles.set(throttleKey, Date.now());

    // Snapshot for rollback
    const prevUser = user;

    // Prevent client-side role elevation
    const { role: _stripped, ...safeUpdates } = updates as Partial<User> & { role?: unknown };

    // Optimistic update
    set((state) => {
      const updatedUser = state.user ? { ...state.user, ...safeUpdates } : null;
      if (updatedUser) storage.set('ironvault_user_cache', JSON.stringify(updatedUser));
      return { user: updatedUser };
    });

    const dbUpdates: DBProfileUpdate = {};
    if (updates.bio !== undefined) dbUpdates.bio = updates.bio;
    if (updates.username !== undefined) dbUpdates.username = updates.username;
    if (updates.avatar_url !== undefined) dbUpdates.avatar_url = updates.avatar_url;
    if (updates.display_name !== undefined) dbUpdates.display_name = updates.display_name;
    if (updates.isSocialPrivate !== undefined) dbUpdates.is_social_private = updates.isSocialPrivate;
    if (Object.keys(dbUpdates).length > 0) {
      try {
        const { error } = await supabase.from('profiles').update(dbUpdates).eq('id', user.id);
        if (error) throw error;
      } catch (e: unknown) {
        // Rollback optimistic update
        console.warn('[updateUser] DB sync failed, rolling back:', e);
        set({ user: prevUser });
        storage.set('ironvault_user_cache', JSON.stringify(prevUser));
        const { default: reelToast } = require('../utils/reelToast');
        reelToast.error('Profile update failed \u2014 changes reverted.');
      }
    }
  },

  setPreference: async (key, value) => {
    const user = get().user;
    if (!user) return;
    const prefs = { ...(user.preferences ?? {}), [key]: value };
    set((state) => ({ user: state.user ? { ...state.user, preferences: prefs } : null }));

    const throttleKey = `pref:${user.id}`;
    const lastCall = _actionThrottles.get(throttleKey) ?? 0;
    if (Date.now() - lastCall < 1500) return;
    pruneThrottles();
    _actionThrottles.set(throttleKey, Date.now());

    try {
      await supabase.from('profiles').update({ preferences: prefs }).eq('id', user.id);
      // Persist updated cache
      storage.set('ironvault_user_cache', JSON.stringify({ ...get().user, preferences: prefs }));
    } catch {
      // DB write failed but local state is already set — persist to MMKV so it survives restart
      storage.set('ironvault_user_cache', JSON.stringify({ ...get().user, preferences: prefs }));
      console.warn('[setPreference] DB sync failed, persisted locally');
    }
  },

  getPreference: (key, fallback = null) => {
    const user = get().user;
    return user?.preferences?.[key] ?? fallback;
  },

  followUser: async (targetUsername) => {
    const state = get();
    const following = state.user?.following ?? [];
    if (following.includes(targetUsername)) return;

    const throttleKey = `follow:${targetUsername}`;
    const lastCall = _actionThrottles.get(throttleKey) ?? 0;
    if (Date.now() - lastCall < 2000) return;
    pruneThrottles();
    _actionThrottles.set(throttleKey, Date.now());

    const userId = state.user?.id;
    if (!userId) {
      console.warn('[followUser] No userId — user not authenticated');
      return;
    }

    // Optimistic update + persist to cache immediately
    const newFollowing = [...(state.user?.following ?? []), targetUsername];
    set((s) => ({ user: s.user ? { ...s.user, following: newFollowing } : null }));
    _persistFollowingToCache(newFollowing, state.user!);

    try {
      const targetId = await resolveUsernameToId(targetUsername);
      if (!targetId) throw new Error(`User "${targetUsername}" not found in profiles table`);

      // CHECK if follow already exists in DB before inserting
      const { data: existing } = await supabase
        .from('interactions')
        .select('id')
        .eq('user_id', userId)
        .eq('target_user_id', targetId)
        .eq('type', 'follow')
        .maybeSingle();

      if (existing) {
        // Follow already exists in DB — just keep the optimistic update, no insert needed
        console.warn(`[followUser] Already following @${targetUsername} in DB, syncing state`);
        return;
      }

      const { error } = await supabase.from('interactions').insert([{
        user_id: userId, target_user_id: targetId, type: 'follow',
      }]);
      if (error && !error.message?.includes('duplicate')) throw error;
      // Success — DB trigger handles notification generation
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      console.warn(`[followUser] FAILED for @${targetUsername}: ${msg}`);
      // Rollback optimistic update + cache
      const rolledBack = (get().user?.following ?? []).filter(u => u !== targetUsername);
      set((s) => ({ user: s.user ? { ...s.user, following: rolledBack } : null }));
      _persistFollowingToCache(rolledBack, get().user!);
      Alert.alert('Follow Failed', `Could not follow @${targetUsername}. Please try again.`);
    }
  },

  unfollowUser: async (targetUsername) => {
    const throttleKey = `unfollow:${targetUsername}`;
    const lastCall = _actionThrottles.get(throttleKey) ?? 0;
    if (Date.now() - lastCall < 2000) return;
    pruneThrottles();
    _actionThrottles.set(throttleKey, Date.now());

    const prevFollowing = get().user?.following ?? [];
    const userId = get().user?.id;
    if (!userId) {
      console.warn('[unfollowUser] No userId — user not authenticated');
      return;
    }

    // Optimistic update + persist to cache immediately
    const newFollowing = prevFollowing.filter(u => u !== targetUsername);
    set((s) => ({ user: s.user ? { ...s.user, following: newFollowing } : null }));
    _persistFollowingToCache(newFollowing, get().user!);

    try {
      const targetId = await resolveUsernameToId(targetUsername);
      if (targetId) {
        const { error } = await supabase.from('interactions').delete()
          .eq('user_id', userId).eq('target_user_id', targetId).eq('type', 'follow');
        if (error) throw error;
      } else {
        console.warn(`[unfollowUser] Could not resolve ID for @${targetUsername}`);
      }
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      console.warn(`[unfollowUser] FAILED for @${targetUsername}: ${msg}`);
      // Rollback
      set((s) => ({ user: s.user ? { ...s.user, following: prevFollowing } : null }));
      _persistFollowingToCache(prevFollowing, get().user!);
      Alert.alert('Unfollow Failed', `Could not unfollow @${targetUsername}. Please try again.`);
    }
  },
}));

// ── Persist following array to ironvault cache (fire-and-forget) ──
function _persistFollowingToCache(following: string[], user: User) {
  try {
    const cached = { ...user, following };
    storage.set('ironvault_user_cache', JSON.stringify(cached));
  } catch { /* non-critical */ }
}

// ── Hydrate following list from interactions table ──
export async function hydrateFollowing() {
  const userId = useAuthStore.getState().user?.id;
  if (!userId) {
    console.warn('[hydrateFollowing] No userId — skipping');
    return;
  }
  try {
    const { data: followRows, error: followErr } = await supabase
      .from('interactions').select('target_user_id')
      .eq('user_id', userId).eq('type', 'follow').limit(5000);
    if (followErr) {
      console.warn('[hydrateFollowing] Query error:', followErr.message);
      return;
    }
    if (!followRows || followRows.length === 0) {
      useAuthStore.setState(s => ({ user: s.user ? { ...s.user, following: [] } : null }));
      // Persist empty following to cache to prevent phantom follows on cold-start
      const currentUser = useAuthStore.getState().user;
      if (currentUser) _persistFollowingToCache([], currentUser);
      return;
    }
    const targetIds = followRows.map(r => r.target_user_id);
    const { data: profiles, error: profileErr } = await supabase
      .from('profiles').select('username').in('id', targetIds).limit(5000);
    if (profileErr) {
      console.warn('[hydrateFollowing] Profile resolve error:', profileErr.message);
      return;
    }
    const usernames = (profiles ?? []).map(p => p.username).filter(Boolean);
    useAuthStore.setState(s => ({ user: s.user ? { ...s.user, following: usernames } : null }));
    // Persist to cache so next session loads instantly
    const currentUser = useAuthStore.getState().user;
    if (currentUser) _persistFollowingToCache(usernames, currentUser);
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : String(err);
    console.warn('[hydrateFollowing] Unexpected error:', msg);
  }
}

import { StateCreator } from 'zustand';
import { supabase } from '../../lib/supabase';
import { useAuthStore } from '../auth';
import { FilmState } from '../films';
import reelToast from '../../utils/reelToast';
import { TicketStub, PhysicalArchiveItem } from '../../types';

export interface ArchiveSlice {
    physicalArchive: PhysicalArchiveItem[];
    stubs: TicketStub[];

    fetchPhysicalArchive: (userId?: string) => Promise<PhysicalArchiveItem[]>;
    addToPhysicalArchive: (film: { id: number; title?: string; name?: string; poster_path?: string | null; release_date?: string }, formats: string[], notes?: string, condition?: string) => Promise<void>;
    removeFromPhysicalArchive: (filmId: number) => Promise<void>;
    updatePhysicalArchiveItem: (filmId: number, updates: Partial<PhysicalArchiveItem>) => Promise<void>;

    fetchStubs: () => Promise<void>;
    saveStub: (stub: Partial<TicketStub> & { showtimeId?: string, slotId?: string }) => Promise<string | null>;
}

export const createArchiveSlice: StateCreator<FilmState, [], [], ArchiveSlice> = (set, get) => ({
    physicalArchive: [],
    stubs: [],

    fetchPhysicalArchive: async (userId?: string) => {
        const uid = userId ?? useAuthStore.getState().user?.id;
        if (!uid) return [];
        const { data, error } = await supabase
            .from('physical_archive').select('id, user_id, film_id, film_title, poster_path, year, formats, notes, condition, created_at').eq('user_id', uid)
            .order('created_at', { ascending: false }).limit(2000);
        if (!error && data) {
            const items = data.map((item) => ({
                id: item.id,
                filmId: item.film_id,
                title: item.film_title,
                poster_path: item.poster_path ?? null,
                year: item.year ?? null,
                formats: item.formats ?? [],
                notes: item.notes ?? '',
                condition: item.condition ?? 'good',
                createdAt: item.created_at,
            }));
            if (!userId || userId === useAuthStore.getState().user?.id) {
                set({ physicalArchive: items });
            }
            return items;
        }
        return [];
    },

    addToPhysicalArchive: async (film, formats, notes = '', condition = 'good') => {
        const user = useAuthStore.getState().user;
        if (!user) return;

        const existingItem = get().physicalArchive.find(item => item.filmId === film.id);
        const newFormats = existingItem ? Array.from(new Set([...existingItem.formats, ...formats])) : formats;

        const newItem: PhysicalArchiveItem = {
            id: String(existingItem ? existingItem.id : `-${Date.now()}`),
            filmId: film.id,
            title: film.title ?? film.name ?? 'Unknown',
            poster_path: film.poster_path ?? (film as any).poster ?? null,
            year: film.release_date ? parseInt(film.release_date.slice(0, 4)) : undefined,
            formats: newFormats,
            notes,
            condition,
            createdAt: existingItem ? existingItem.createdAt : new Date().toISOString(),
        };

        set((state) => {
            const filtered = state.physicalArchive.filter(i => i.filmId !== film.id);
            return { physicalArchive: [newItem, ...filtered] };
        });

        try {
            const { data, error } = await supabase.from('physical_archive').upsert([{
                user_id: user.id,
                film_id: film.id,
                film_title: film.title ?? film.name ?? 'Unknown',
                poster_path: film.poster_path ?? (film as any).poster ?? null,
                year: film.release_date ? parseInt(film.release_date.slice(0, 4)) : null,
                formats: newFormats,
                notes,
                condition,
            }], { onConflict: 'user_id, film_id' }).select().single();

            if (error) throw error;

            if (data && !existingItem) {
                set(state => ({
                    physicalArchive: state.physicalArchive.map(item => 
                        item.filmId === film.id ? { ...item, id: data.id } : item
                    )
                }));
            }
        } catch (e: unknown) {
            set((state) => {
                const filtered = state.physicalArchive.filter(i => i.filmId !== film.id);
                return { 
                    physicalArchive: existingItem ? [existingItem, ...filtered] : filtered 
                };
            });
            reelToast.error('Failed to update physical archive.');
        }
    },

    removeFromPhysicalArchive: async (filmId) => {
        const user = useAuthStore.getState().user;
        if (!user) return;

        const itemToRemove = get().physicalArchive.find((item) => item.filmId === filmId);
        if (!itemToRemove) return;

        set((state) => ({
            physicalArchive: state.physicalArchive.filter((item) => item.filmId !== filmId)
        }));

        try {
            const { error } = await supabase.from('physical_archive').delete().eq('user_id', user.id).eq('film_id', filmId);
            if (error) throw error;
        } catch (e: unknown) {
            set((state) => ({
                physicalArchive: [itemToRemove, ...state.physicalArchive]
            }));
            reelToast.error('Failed to remove from physical archive.');
        }
    },

    updatePhysicalArchiveItem: async (filmId: number, updates: Partial<PhysicalArchiveItem>) => {
        const user = useAuthStore.getState().user;
        if (!user) return;

        const prevItem = get().physicalArchive.find(a => a.filmId === filmId);

        set((state) => ({ physicalArchive: state.physicalArchive.map(a => a.filmId === filmId ? { ...a, ...updates } : a) }));

        try {
            const dbUpdates: Record<string, any> = {};
            if (updates.formats) dbUpdates.formats = updates.formats;
            if (updates.notes !== undefined) dbUpdates.notes = updates.notes;
            if (updates.condition !== undefined) dbUpdates.condition = updates.condition;
            const { error } = await supabase.from('physical_archive').update(dbUpdates).eq('user_id', user.id).eq('film_id', filmId);
            if (error) throw error;
        } catch (e: unknown) {
            if (prevItem) {
                set((state) => ({ physicalArchive: state.physicalArchive.map(a => a.filmId === filmId ? prevItem : a) }));
            }
            reelToast.error('Failed to update physical archive.');
        }
    },

    fetchStubs: async () => {
        const user = useAuthStore.getState().user;
        if (!user) return;
        const { data, error } = await supabase
            .from('tickets')
            .select('id, user_id, showtime_id, seat, ticket_type, amount, qr_code, screen_name, created_at, showtimes(film_title, date)')
            .eq('user_id', user.id)
            .order('created_at', { ascending: false })
            .limit(500);
        if (!error && data) {
            set({
                stubs: data.map((t) => {
                    const showtime = Array.isArray(t.showtimes) ? t.showtimes[0] : t.showtimes;
                    return {
                        id: t.id ?? '',
                        filmTitle: showtime?.film_title ?? 'Unknown Film',
                        date: showtime?.date ?? '',
                        seat: t.seat ?? '—',
                        ticketType: t.ticket_type ?? 'Standard',
                        amount: t.amount ?? 0,
                        qrCode: t.qr_code ?? null,
                        screenName: t.screen_name ?? null,
                        createdAt: t.created_at ?? new Date().toISOString(),
                    };
                }),
            });
        }
    },

    saveStub: async (stub) => {
        const user = useAuthStore.getState().user;
        if (!user) return null;

        const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
        const isRealShowtime = stub.showtimeId && UUID_RE.test(stub.showtimeId);
        if (!isRealShowtime) return null;
        const { data, error } = await supabase.from('tickets').insert([{
            user_id: user.id,
            showtime_id: stub.showtimeId,
            slot_id: stub.slotId ?? 'default',
            seat: stub.seat ?? '—',
            ticket_type: stub.ticketType ?? 'Standard',
            amount: stub.amount ?? 0,
            qr_code: stub.qrCode ?? null,
            screen_name: stub.screenName ?? null,
        }]).select().single();
        if (error || !data) {
            reelToast.error('Failed to save ticket stub — please try again.');
            throw error ?? new Error('Ticket stub save returned no data');
        }
        return data.id;
    },
});

import { StateCreator } from 'zustand';
import { supabase } from '../../lib/supabase';
import { useAuthStore } from '../auth';
import { FilmState } from '../films';
import reelToast from '../../utils/reelToast';
import { CustomList } from '../../types';

export interface ListSlice {
    lists: CustomList[];
    listsHasMore: boolean;
    listsPage: number;
    _fetchingLists: boolean;

    fetchLists: (loadMore?: boolean) => Promise<void>;
    createList: (list: Partial<CustomList>) => Promise<void>;
    updateList: (listId: string, updates: Partial<CustomList>) => Promise<void>;
    deleteList: (listId: string) => Promise<void>;
    addFilmToList: (listId: string, film: { id: number; title?: string; name?: string; poster_path?: string | null }) => Promise<void>;
    removeFilmFromList: (listId: string, filmId: number) => Promise<void>;
}

export const createListSlice: StateCreator<FilmState, [], [], ListSlice> = (set, get) => ({
    lists: [],
    listsHasMore: true,
    listsPage: 0,
    _fetchingLists: false,

    fetchLists: async (loadMore = false) => {
        const user = useAuthStore.getState().user;
        if (!user) return;
        const state = get();
        if (state._fetchingLists) return;
        if (loadMore && !state.listsHasMore) return;
        set({ _fetchingLists: true });

        const PAGE_SIZE = 20;
        const page = loadMore ? state.listsPage : 0;

        const { data, error } = await supabase
            .from('lists')
            .select(`
                id, user_id, title, description, is_ranked, is_private, created_at,
                list_items ( id, film_id, film_title, poster_path, position )
            `)
            .eq('user_id', user.id)
            .order('created_at', { ascending: false })
            .range(page * PAGE_SIZE, (page + 1) * PAGE_SIZE - 1);

        if (error || !data) { set({ _fetchingLists: false }); return; }

        const hasMore = data.length === PAGE_SIZE;

        const newLists = data.map((d: any) => {
            const items = d.list_items || [];
            items.sort((a: any, b: any) => a.position - b.position);
            return {
                id: d.id,
                title: d.title,
                description: d.description,
                isRanked: d.is_ranked,
                isPrivate: d.is_private,
                createdAt: d.created_at,
                films: items.map((i: any) => ({
                    id: i.film_id,
                    title: i.film_title,
                    poster: i.poster_path
                }))
            };
        });

        const nextLists = loadMore ? [...state.lists, ...newLists] : newLists;
        set({
            lists: nextLists,
            listsPage: page + 1,
            listsHasMore: hasMore,
            _fetchingLists: false,
        });
    },

    createList: async (list) => {
        const user = useAuthStore.getState().user;
        if (!user) return;
        const { data, error } = await supabase.from('lists').insert([{
            user_id: user.id, title: list.title, description: list.description ?? '', is_private: list.isPrivate ?? false, is_ranked: list.isRanked ?? false
        }]).select().single();
        if (error) throw error;
        if (data) {
            const inputFilms = (list as { films?: { id: number; title?: string; poster_path?: string | null; poster?: string | null }[] }).films ?? [];
            const filmEntries = inputFilms.map((f) => ({ id: f.id, title: f.title ?? 'Unknown', poster: f.poster_path ?? f.poster ?? null }));

            set((state) => ({ lists: [{ id: data.id, title: list.title ?? 'Untitled', description: list.description ?? '', isRanked: list.isRanked ?? false, isPrivate: list.isPrivate ?? false, films: filmEntries, createdAt: data.created_at }, ...state.lists] }));

            if (inputFilms.length > 0) {
                const items = inputFilms.map((f, idx) => ({
                    list_id: data.id,
                    film_id: f.id,
                    film_title: f.title ?? 'Unknown',
                    poster_path: f.poster_path ?? f.poster ?? null,
                    position: idx,
                }));
                const { error: itemsError } = await supabase.from('list_items').insert(items);
                if (itemsError) {
                    console.warn('[createList] list_items insert failed, rolling back:', itemsError);
                    set((state) => ({ lists: state.lists.filter(l => l.id !== data.id) }));
                    await supabase.from('lists').delete().eq('id', data.id).eq('user_id', user.id);
                    reelToast.error('Failed to save films to list — please try again.');
                    throw itemsError;
                }
            }
        }
    },

    updateList: async (listId, updates) => {
        const user = useAuthStore.getState().user;
        if (!user) return;

        const prevList = get().lists.find(l => l.id === listId);
        if (!prevList) return;

        const dbUpdates: Record<string, any> = {};
        if (updates.title !== undefined) dbUpdates.title = updates.title;
        if (updates.description !== undefined) dbUpdates.description = updates.description;
        if (updates.isPrivate !== undefined) dbUpdates.is_private = updates.isPrivate;
        if (updates.isRanked !== undefined) dbUpdates.is_ranked = updates.isRanked;

        const inputFilms = (updates as { films?: { id: number; title?: string; poster_path?: string | null; poster?: string | null }[] }).films;

        set((state) => ({
            lists: state.lists.map(l => l.id === listId ? { 
                ...l, 
                ...updates,
                films: inputFilms !== undefined ? inputFilms.map(f => ({ id: f.id, title: f.title ?? 'Unknown', poster: f.poster_path ?? f.poster ?? null })) : l.films 
            } : l)
        }));

        try {
            const { error } = await supabase.from('lists').update(dbUpdates).eq('id', listId).eq('user_id', user.id);
            if (error) throw error;

            if (inputFilms !== undefined) {
                await supabase.from('list_items').delete().eq('list_id', listId);
                if (inputFilms.length > 0) {
                    const items = inputFilms.map((f, idx) => ({
                        list_id: listId,
                        film_id: f.id,
                        film_title: f.title ?? 'Unknown',
                        poster_path: f.poster_path ?? f.poster ?? null,
                        position: idx,
                    }));
                    const { error: itemsError } = await supabase.from('list_items').insert(items);
                    if (itemsError) throw itemsError;
                }
            }
        } catch (e: unknown) {
            set((state) => ({ lists: state.lists.map(l => l.id === listId ? prevList : l) }));
            reelToast.error('Failed to update list — changes reverted.');
            throw e;
        }
    },

    deleteList: async (listId) => {
        const user = useAuthStore.getState().user;
        if (!user) return;

        const listToRemove = get().lists.find(l => l.id === listId);
        if (!listToRemove) return;

        set((state) => ({ lists: state.lists.filter(l => l.id !== listId) }));

        try {
            // Delete child items FIRST to prevent orphans (safe regardless of CASCADE)
            await supabase.from('list_items').delete().eq('list_id', listId);
            const { error } = await supabase.from('lists').delete().eq('id', listId).eq('user_id', user.id);
            if (error) throw error;
        } catch (e: unknown) {
            set((state) => ({ lists: [listToRemove, ...state.lists] }));
            reelToast.error('Failed to delete list — please try again.');
            throw e;
        }
    },

    addFilmToList: async (listId, film) => {
        const listIdx = get().lists.findIndex(l => l.id === listId);
        if (listIdx === -1) return;

        const currentList = get().lists[listIdx];
        if (currentList.films.some(f => f.id === film.id)) return;

        const newFilm = { id: film.id, title: film.title ?? film.name ?? 'Unknown', poster: film.poster_path ?? null };

        set((state) => ({
            lists: state.lists.map((l) => l.id === listId ? { ...l, films: [...l.films, newFilm] } : l),
        }));

        try {
            const { error } = await supabase.from('list_items').insert([{
                list_id: listId, film_id: film.id, film_title: newFilm.title,
                poster_path: newFilm.poster,
            }]);
            if (error) throw error;
        } catch (e: unknown) {
            set((state) => ({
                lists: state.lists.map((l) => l.id === listId ? { ...l, films: l.films.filter(f => f.id !== film.id) } : l),
            }));
            reelToast.error('Failed to add film to stack.');
        }
    },

    removeFilmFromList: async (listId, filmId) => {
        const listIdx = get().lists.findIndex(l => l.id === listId);
        if (listIdx === -1) return;

        const currentList = get().lists[listIdx];
        const filmToRemove = currentList.films.find(f => f.id === filmId);
        if (!filmToRemove) return;

        set((state) => ({
            lists: state.lists.map((l) => l.id === listId ? { ...l, films: l.films.filter((f) => f.id !== filmId) } : l),
        }));

        try {
            const { error } = await supabase.from('list_items').delete().eq('list_id', listId).eq('film_id', filmId);
            if (error) throw error;
        } catch (e: unknown) {
            set((state) => ({
                lists: state.lists.map((l) => l.id === listId ? { ...l, films: [...l.films, filmToRemove] } : l),
            }));
            reelToast.error('Failed to remove film from stack.');
        }
    },
});

import { StateCreator } from 'zustand';
import { supabase } from '../../lib/supabase';
import { useAuthStore } from '../auth';
import { FilmState } from '../films';
import reelToast from '../../utils/reelToast';
import { colors } from '../../theme/theme';
import { FilmLog } from '../../types';

export interface LogSlice {
    logs: FilmLog[];
    logsHasMore: boolean;
    logsPage: number;
    _loggedIndex: Record<number, FilmLog>;
    _fetchingLogs: boolean;
    _addLogMutex: boolean;

    fetchLogs: (loadMore?: boolean) => Promise<void>;
    addLog: (log: Partial<FilmLog>) => Promise<void>;
    updateLog: (id: string, updates: Partial<FilmLog>) => Promise<void>;
    removeLog: (id: string) => Promise<void>;
    markAsWatched: (film: { id: number; title?: string; name?: string; poster_path?: string | null; release_date?: string }, status?: 'watched' | 'rewatched' | 'abandoned') => Promise<void>;
    unmarkWatched: (filmId: number) => Promise<void>;
    getCinephileStats: (overrideCount?: number) => { count: number, level: string, color: string, progress: number };
}

export const createLogSlice: StateCreator<FilmState, [], [], LogSlice> = (set, get) => ({
    logs: [],
    logsHasMore: true,
    logsPage: 0,
    _loggedIndex: {},
    _fetchingLogs: false,
    _addLogMutex: false,

    fetchLogs: async (loadMore = false) => {
        const user = useAuthStore.getState().user;
        if (!user) return;
        const state = get();
        if (state._fetchingLogs) return;
        if (loadMore && !state.logsHasMore) return;
        set({ _fetchingLogs: true });

        const PAGE_SIZE = 50;
        const page = loadMore ? state.logsPage : 0;

        const { data, error } = await supabase
            .from('logs').select('id, user_id, film_id, film_title, poster_path, year, rating, review, status, watched_date, is_spoiler, watched_with, private_notes, abandoned_reason, physical_media, is_autopsied, autopsy, alt_poster, editorial_header, drop_cap, pull_quote, video_url, format, created_at, view_count, viewing_history').eq('user_id', user.id)
            .order('watched_date', { ascending: false })
            .range(page * PAGE_SIZE, (page + 1) * PAGE_SIZE - 1);

        if (error || !data) { set({ _fetchingLogs: false }); return; }

        const hasMore = data.length === PAGE_SIZE;

        const newLogs = data.map((dbLog) => ({
                id: dbLog.id,
                filmId: dbLog.film_id,
                title: dbLog.film_title,
                poster: dbLog.poster_path ?? null,
                year: dbLog.year ?? null,
                rating: dbLog.rating,
                review: dbLog.review,
                status: dbLog.status ?? 'watched',
                isSpoiler: dbLog.is_spoiler ?? false,
                watchedDate: dbLog.watched_date,
                watchedWith: dbLog.watched_with ?? null,
                privateNotes: dbLog.private_notes ?? null,
                abandonedReason: dbLog.abandoned_reason ?? null,
                physicalMedia: dbLog.physical_media ?? null,
                isAutopsied: dbLog.is_autopsied ?? false,
                autopsy: dbLog.autopsy ?? null,
                altPoster: dbLog.alt_poster ?? null,
                editorialHeader: dbLog.editorial_header ?? null,
                dropCap: dbLog.drop_cap ?? false,
                pullQuote: dbLog.pull_quote ?? '',
                videoUrl: dbLog.video_url ?? null,
                createdAt: dbLog.created_at,
                viewCount: dbLog.view_count ?? 1,
                viewingHistory: dbLog.viewing_history ?? [],
        }));

        const nextLogs = loadMore ? [...state.logs, ...newLogs] : newLogs;
        const cappedLogs = nextLogs.slice(0, 500);
        const idx: Record<number, FilmLog> = {};
        cappedLogs.forEach(l => { if (l.filmId && !idx[l.filmId]) idx[l.filmId] = l as FilmLog; });

        set({ 
            logs: cappedLogs as FilmLog[], 
            _loggedIndex: idx,
            logsPage: page + 1,
            logsHasMore: hasMore,
            _fetchingLogs: false,
        });
    },

    addLog: async (log) => {
        const user = useAuthStore.getState().user;
        if (!user) return;

        if (get()._addLogMutex) return;
        set({ _addLogMutex: true });

        try {
            let existingLog = log.filmId ? get()._loggedIndex[log.filmId] : undefined;
            if (!existingLog && log.filmId) {
                const { data: serverCheck } = await supabase.from('logs')
                    .select('id, rating, review, watched_date, watched_with, view_count, viewing_history, created_at, status')
                    .eq('user_id', user.id).eq('film_id', log.filmId).maybeSingle();
                if (serverCheck) {
                    existingLog = {
                        id: serverCheck.id, filmId: log.filmId, rating: serverCheck.rating, review: serverCheck.review, 
                        watchedDate: serverCheck.watched_date, watchedWith: serverCheck.watched_with, 
                        viewCount: serverCheck.view_count, viewingHistory: serverCheck.viewing_history,
                        createdAt: serverCheck.created_at, status: serverCheck.status
                    } as FilmLog;
                }
            }

            if (existingLog) {
                const oldHistory = (Array.isArray(existingLog.viewingHistory) ? existingLog.viewingHistory : []) as Array<{ date?: string; rating: number; review?: string; watchedWith?: string | null }>;
                const archivedEntry = {
                    date: existingLog.watchedDate ?? existingLog.createdAt ?? new Date().toISOString(),
                    rating: existingLog.rating,
                    review: existingLog.review ?? '',
                    watchedWith: existingLog.watchedWith ?? null,
                };
                const newHistory = [archivedEntry, ...oldHistory];
                const newViewCount = (existingLog.viewCount ?? 1) + 1;

                await get().updateLog(existingLog.id, {
                    rating: log.rating ?? 0,
                    review: log.review ?? '',
                    status: log.status === 'abandoned' ? 'abandoned' : 'rewatched',
                    watchedDate: log.watchedDate ?? new Date().toISOString(),
                    watchedWith: log.watchedWith ?? null,
                    isSpoiler: log.isSpoiler ?? false,
                    privateNotes: log.privateNotes ?? null,
                    physicalMedia: log.physicalMedia ?? null,
                    abandonedReason: log.abandonedReason ?? null,
                    isAutopsied: log.isAutopsied ?? false,
                    autopsy: log.autopsy ?? null,
                    altPoster: log.altPoster ?? null,
                    editorialHeader: log.editorialHeader ?? null,
                    dropCap: log.dropCap ?? false,
                    pullQuote: log.pullQuote ?? '',
                    videoUrl: log.videoUrl ?? null,
                    format: log.physicalMedia ?? 'Digital',
                    viewCount: newViewCount,
                    viewingHistory: newHistory,
                } as Partial<FilmLog>);
                return;
            }

            const { data, error } = await supabase.from('logs').insert([{
                user_id: user.id,
                film_id: log.filmId, film_title: log.title,
                poster_path: log.poster ?? null, year: log.year ? (parseInt(String(log.year)) || null) : null,
                rating: log.rating ?? 0, review: log.review ?? '',
                status: log.status ?? 'watched', is_spoiler: log.isSpoiler ?? false,
                watched_date: log.watchedDate ?? new Date().toISOString(),
                watched_with: log.watchedWith ?? null,
                private_notes: log.privateNotes ?? null,
                abandoned_reason: log.abandonedReason ?? null,
                physical_media: log.physicalMedia ?? null,
                is_autopsied: log.isAutopsied ?? false, autopsy: log.autopsy ?? null,
                alt_poster: log.altPoster ?? null, editorial_header: log.editorialHeader ?? null,
                drop_cap: log.dropCap ?? false, pull_quote: log.pullQuote ?? '',
                video_url: log.videoUrl ?? null,
                format: log.physicalMedia ?? 'Digital',
                view_count: 1,
                viewing_history: [],
            }]).select().single();

            if (error) { reelToast.error('Failed to file record — please try again.'); return; }

            const fullLog = { ...log, id: data.id, createdAt: data.created_at, viewCount: 1, viewingHistory: [] } as FilmLog;
            set((state) => ({
                logs: [fullLog, ...state.logs],
                _loggedIndex: (() => { const n = { ...state._loggedIndex }; if (log.filmId) n[log.filmId] = fullLog; return n; })()
            }));

            const syncFormatMap: Record<string, string> = { 'DVD': 'dvd', 'Blu-Ray': 'bluray', '4K UHD': '4k', 'VHS': 'vhs' };
            if (log.physicalMedia && syncFormatMap[log.physicalMedia] && log.filmId !== undefined) {
                const fmt = syncFormatMap[log.physicalMedia];
                try {
                    await get().addToPhysicalArchive({ id: log.filmId, title: log.title ?? '', poster_path: log.poster, release_date: log.year?.toString() }, [fmt]);
                } catch (e) {
                    console.error('Failed to auto-sync physical archive', e);
                }
            }
        } finally {
            set({ _addLogMutex: false });
        }
    },

    markAsWatched: async (film, status = 'watched') => {
        const user = useAuthStore.getState().user;
        if (!user) return;

        let existingLog = get()._loggedIndex[film.id];
        if (!existingLog) {
            const { data: serverCheck } = await supabase.from('logs').select('id, status').eq('user_id', user.id).eq('film_id', film.id).maybeSingle();
            if (serverCheck) existingLog = { id: serverCheck.id, status: serverCheck.status } as FilmLog;
        }

        if (existingLog) {
            await get().updateLog(existingLog.id, { status } as Partial<FilmLog>);
            return;
        }
        const { data, error } = await supabase.from('logs').insert([{
            user_id: user.id,
            film_id: film.id,
            film_title: film.title ?? film.name ?? 'Untitled',
            poster_path: film.poster_path ?? null,
            year: film.release_date ? (parseInt(film.release_date.slice(0, 4)) || null) : null,
            rating: 0,
            review: '',
            status,
            watched_date: new Date().toISOString(),
            is_spoiler: false,
            view_count: 1,
            viewing_history: [],
        }]).select().single();
        if (error) { reelToast.error('Failed to mark as watched — please try again.'); return; }
        const newLog: FilmLog = {
            id: data.id,
            filmId: film.id,
            title: film.title ?? film.name ?? 'Untitled',
            poster: film.poster_path,
            year: film.release_date ? (parseInt(film.release_date.slice(0, 4)) || undefined) : undefined,
            rating: 0,
            status,
            createdAt: data.created_at,
            watchedDate: new Date().toISOString(),
            viewCount: 1,
            viewingHistory: [],
        };
        set(state => {
            const nextIdx = { ...state._loggedIndex };
            nextIdx[film.id] = newLog;
            return { logs: [newLog, ...state.logs], _loggedIndex: nextIdx };
        });
        const inWatchlist = get().watchlist.some(w => w.id === film.id);
        if (inWatchlist) get().removeFromWatchlist(film.id);
    },

    unmarkWatched: async (filmId) => {
        const existingLog = get().logs.find(l => l.filmId === filmId);
        if (!existingLog) return;
        if (existingLog.rating > 0 || (existingLog.review && existingLog.review.length > 0)) return;
        await get().removeLog(existingLog.id);
    },

    getCinephileStats: (overrideCount?: number) => {
        const logs = get().logs;
        const count = overrideCount ?? logs.length;
        let level = 'FIRST REEL';
        let color: string = colors.fog;
        if (count >= 100) { level = 'THE ORACLE'; color = colors.sepia; }
        else if (count >= 25) { level = 'THE DEVOTEE'; color = colors.bloodReel; }
        else if (count >= 10) { level = 'THE REGULAR'; color = colors.flicker; }
        else if (count >= 1) { level = 'THE INITIATE'; color = colors.bone; }
        return { count, level, color, progress: (count % 25) * 4 };
    },

    updateLog: async (id, updates) => {
        const user = useAuthStore.getState().user;
        if (!user) return;

        const prevLogs = get().logs;
        const prevIdx = get()._loggedIndex;

        set((state) => {
            let filmIdToUpdate: number | undefined;
            const nextLogs = state.logs.map((l) => {
                if (l.id === id) {
                    filmIdToUpdate = l.filmId;
                    return { ...l, ...updates } as FilmLog;
                }
                return l;
            });
            const nextIdx = { ...state._loggedIndex };
            if (filmIdToUpdate) {
                const updated = nextLogs.find(l => l.filmId === filmIdToUpdate);
                if (updated) nextIdx[filmIdToUpdate] = updated as FilmLog;
            }
            return { logs: nextLogs, _loggedIndex: nextIdx };
        });

        const dbUpdates: Record<string, any> = {};
        if (updates.rating !== undefined) dbUpdates.rating = updates.rating;
        if (updates.review !== undefined) dbUpdates.review = updates.review;
        if (updates.status !== undefined) dbUpdates.status = updates.status;
        if (updates.isSpoiler !== undefined) dbUpdates.is_spoiler = updates.isSpoiler;
        if (updates.watchedDate !== undefined) dbUpdates.watched_date = updates.watchedDate;
        if (updates.watchedWith !== undefined) dbUpdates.watched_with = updates.watchedWith;
        if (updates.privateNotes !== undefined) dbUpdates.private_notes = updates.privateNotes;
        if (updates.abandonedReason !== undefined) dbUpdates.abandoned_reason = updates.abandonedReason;
        if (updates.physicalMedia !== undefined) dbUpdates.physical_media = updates.physicalMedia;
        if (updates.isAutopsied !== undefined) dbUpdates.is_autopsied = updates.isAutopsied;
        if (updates.autopsy !== undefined) dbUpdates.autopsy = updates.autopsy;
        if (updates.pullQuote !== undefined) dbUpdates.pull_quote = updates.pullQuote;
        if (updates.dropCap !== undefined) dbUpdates.drop_cap = updates.dropCap;
        if (updates.editorialHeader !== undefined) dbUpdates.editorial_header = updates.editorialHeader;
        if (updates.altPoster !== undefined) dbUpdates.alt_poster = updates.altPoster;
        if (updates.videoUrl !== undefined) dbUpdates.video_url = updates.videoUrl;
        if (updates.viewCount !== undefined) dbUpdates.view_count = updates.viewCount;
        if (updates.viewingHistory !== undefined) dbUpdates.viewing_history = JSON.stringify(updates.viewingHistory);

        try {
            const { error } = await supabase.from('logs').update(dbUpdates).eq('id', id);
            if (error) throw error;

            const syncFormatMap: Record<string, string> = { 'DVD': 'dvd', 'Blu-Ray': 'bluray', '4K UHD': '4k', 'VHS': 'vhs' };
            if (updates.physicalMedia && syncFormatMap[updates.physicalMedia]) {
                const fmt = syncFormatMap[updates.physicalMedia];
                const logToUpdate = get().logs.find(l => l.id === id);
                if (logToUpdate && logToUpdate.filmId !== undefined) {
                    try {
                        await get().addToPhysicalArchive({ id: logToUpdate.filmId, title: logToUpdate.title ?? '', poster_path: logToUpdate.poster, release_date: logToUpdate.year?.toString() }, [fmt]);
                    } catch (e) {
                        console.error('Failed to auto-sync physical archive on update', e);
                    }
                }
            }
        } catch (e: unknown) {
            set({ logs: prevLogs, _loggedIndex: prevIdx });
            reelToast.error('Failed to update log — changes reverted.');
            throw e;
        }
    },

    removeLog: async (id) => {
        const logToRemove = get().logs.find((l) => l.id === id);
        if (!logToRemove) return;

        set((state) => {
            const nextIdx = { ...state._loggedIndex };
            if (logToRemove.filmId) delete nextIdx[logToRemove.filmId];
            return { logs: state.logs.filter((l) => l.id !== id), _loggedIndex: nextIdx };
        });

        try {
            const { error } = await supabase.from('logs').delete().eq('id', id);
            if (error) throw error;
            reelToast(`"${logToRemove.title}" removed.`);
        } catch (e: unknown) {
            console.warn(`[removeLog] Failed for log ${id}:`, e);
            set((state) => {
                const nextIdx = { ...state._loggedIndex };
                if (logToRemove.filmId) nextIdx[logToRemove.filmId] = logToRemove;
                return { logs: [logToRemove, ...state.logs], _loggedIndex: nextIdx };
            });
            reelToast.error('Failed to remove log.');
        }
    },
});

import { create } from 'zustand';
import { supabase } from '../lib/supabase';
import { useAuthStore } from './auth';
import { Alert } from 'react-native';

// ── Types ──
export interface LoungeRoom {
  id: string;
  name: string;
  description: string;
  is_private: boolean;
  invite_code: string | null;
  creator_id: string;
  created_at: string;
  cover_image?: string | null;
  member_count?: number;
  unread_count?: number;
  last_message?: string;
  last_message_at?: string;
}

export interface LoungeMessage {
  id: string;
  lounge_id: string;
  user_id: string;
  username: string;
  avatar_url?: string;
  content: string;
  type: 'text' | 'film_share' | 'log_share' | 'system' | string;
  reply_to_id?: string | null;
  reply_to_username?: string | null;
  reply_to_content?: string | null;
  film_id?: number | null;
  film_title?: string | null;
  film_poster?: string | null;
  created_at: string;
}

export interface LoungeState {
  lounges: LoungeRoom[];
  currentMessages: LoungeMessage[];
  currentLoungeId: string | null;
  loading: boolean;
  sending: boolean;

  fetchLounges: () => Promise<void>;
  fetchMessages: (loungeId: string) => Promise<void>;
  loadMoreMessages: (loungeId: string) => Promise<void>;
  sendMessage: (loungeId: string, content: string, type?: string, meta?: {
    reply_to_id?: string | null;
    reply_to_username?: string | null;
    reply_to_content?: string | null;
    film_id?: number | null;
    film_title?: string | null;
    film_poster?: string | null;
  }) => Promise<void>;
  deleteMessage: (messageId: string) => Promise<void>;
  createLounge: (name: string, description: string, isPrivate: boolean) => Promise<string | null>;
  joinLounge: (inviteCode: string) => Promise<boolean>;
  joinLoungeById: (loungeId: string) => Promise<boolean>;
  leaveLounge: (loungeId: string) => Promise<void>;
  deleteLounge: (loungeId: string) => Promise<void>;
  subscribeToLounge: (loungeId: string) => () => void;
  markRead: (loungeId: string) => Promise<void>;
}

// ── Throttle ── (800ms between sends, matching web)
let _lastSendAt = 0;
const SEND_THROTTLE = 800;

// ── Username cache for Realtime messages — prevents N+1 profile queries ──
const _profileCache = new Map<string, { username: string; avatar_url?: string; ts: number }>();
const _PROFILE_CACHE_TTL = 5 * 60 * 1000; // 5 minutes
const _PROFILE_CACHE_MAX = 100;
async function resolveProfile(userId: string): Promise<{ username: string; avatar_url?: string }> {
  const cached = _profileCache.get(userId);
  if (cached && Date.now() - cached.ts < _PROFILE_CACHE_TTL) return cached;
  if (cached) _profileCache.delete(userId);
  const { data: profile } = await supabase.from('profiles').select('username, avatar_url').eq('id', userId).single();
  const result = { username: profile?.username ?? 'unknown', avatar_url: profile?.avatar_url };
  if (_profileCache.size >= _PROFILE_CACHE_MAX) {
    const oldest = _profileCache.keys().next().value;
    if (oldest !== undefined) _profileCache.delete(oldest);
  }
  _profileCache.set(userId, { ...result, ts: Date.now() });
  return result;
}

// ── Raw Realtime payload shape ──
interface RawLoungePayload {
  id: string;
  lounge_id: string;
  user_id: string;
  content: string;
  type: string;
  reply_to_id?: string | null;
  reply_to_username?: string | null;
  reply_to_content?: string | null;
  film_id?: number | null;
  film_title?: string | null;
  film_poster?: string | null;
  created_at: string;
}

// ── Supabase join result shape for lounge_messages + profiles ──
interface LoungeMessageRow {
  id: string;
  lounge_id: string;
  user_id: string;
  content: string;
  type: string;
  reply_to_id?: string | null;
  reply_to_username?: string | null;
  reply_to_content?: string | null;
  film_id?: number | null;
  film_title?: string | null;
  film_poster?: string | null;
  created_at: string;
  profiles: { username: string; avatar_url?: string } | { username: string; avatar_url?: string }[] | null;
}

export const useLoungeStore = create<LoungeState>()((set, get) => ({
  lounges: [],
  currentMessages: [],
  currentLoungeId: null,
  loading: false,
  sending: false,

  fetchLounges: async () => {
    const user = useAuthStore.getState().user;
    if (!user) return;
    set({ loading: true });
    try {
      // Fetch lounges where user is a member
      const { data: memberRows } = await supabase
        .from('lounge_members')
        .select('lounge_id, last_read_at')
        .eq('user_id', user.id)
        .limit(100);

      const memberships = memberRows ?? [];
      const myLoungeIds = memberships.map(r => r.lounge_id);

      // Fetch from three sources to guarantee visibility:
      // 1) Public lounges (browsable by anyone)
      // 2) Lounges user has explicitly joined (via lounge_members)
      // 3) Lounges user created (fallback if lounge_members insert failed)
      // Fetch ALL browsable lounges (public + private — both are visible, private just needs approval)
      const browsablePromise = supabase.from('lounges')
        .select('id, name, description, is_private, invite_code, creator_id, created_at, member_count')
        .order('created_at', { ascending: false })
        .limit(50);

      const myJoinedPromise = myLoungeIds.length > 0 
        ? supabase.from('lounges')
            .select('id, name, description, is_private, invite_code, creator_id, created_at, member_count')
            .in('id', myLoungeIds)
        : Promise.resolve({ data: [] as Array<{ id: string; name: string; description: string; is_private: boolean; invite_code: string | null; creator_id: string; created_at: string; member_count: number }> });

      const myCreatedPromise = supabase.from('lounges')
        .select('id, name, description, is_private, invite_code, creator_id, created_at, member_count')
        .eq('creator_id', user.id);

      const [browsableRes, myJoinedRes, myCreatedRes] = await Promise.all([
        browsablePromise, myJoinedPromise, myCreatedPromise,
      ]);

      // Merge all three, deduplicating by id
      const allLoungesMap = new Map<string, { id: string; name: string; description: string; is_private: boolean; invite_code: string | null; creator_id: string; created_at: string; member_count: number }>();
      if (browsableRes.data) browsableRes.data.forEach(l => allLoungesMap.set(l.id, l));
      if (myJoinedRes.data) myJoinedRes.data.forEach(l => allLoungesMap.set(l.id, l));
      if (myCreatedRes.data) myCreatedRes.data.forEach(l => allLoungesMap.set(l.id, l));

      // Build the combined set of IDs the user "owns or joined"
      const ownedOrJoinedIds = new Set(myLoungeIds);
      if (myCreatedRes.data) myCreatedRes.data.forEach(l => ownedOrJoinedIds.add(l.id));

      // Calculate unread counts and last message timestamps — BATCHED (no N+1)
      const unreadCounts: Record<string, number> = {};
      const lastMessageTimestamps: Record<string, string> = {};

      const loungeIds = memberships.map(m => m.lounge_id);
      if (loungeIds.length > 0) {
        // Batch 1: Get last message per lounge in a single query
        const { data: lastMsgs } = await supabase
          .from('lounge_messages')
          .select('lounge_id, created_at')
          .in('lounge_id', loungeIds)
          .order('created_at', { ascending: false });

        if (lastMsgs) {
          // Keep only the latest per lounge_id
          for (const msg of lastMsgs) {
            if (!lastMessageTimestamps[msg.lounge_id]) {
              lastMessageTimestamps[msg.lounge_id] = msg.created_at;
            }
          }
        }

        // Batch 2: Count unread per lounge — fetch messages newer than last_read_at
        // Build a map of last_read_at per lounge for comparison
        const lastReadMap = new Map(memberships.map(m => [m.lounge_id, m.last_read_at]));
        const oldestLastRead = memberships
          .filter(m => m.last_read_at)
          .map(m => m.last_read_at!)
          .sort()[0];

        // Single query: fetch all recent messages across all lounges
        let unreadQuery = supabase
          .from('lounge_messages')
          .select('lounge_id, created_at')
          .in('lounge_id', loungeIds);
        if (oldestLastRead) {
          unreadQuery = unreadQuery.gt('created_at', oldestLastRead);
        }
        const { data: recentMsgs } = await unreadQuery;

        // Count per lounge, respecting each membership's last_read_at
        if (recentMsgs) {
          for (const msg of recentMsgs) {
            const memberLastRead = lastReadMap.get(msg.lounge_id);
            if (!memberLastRead || msg.created_at > memberLastRead) {
              unreadCounts[msg.lounge_id] = (unreadCounts[msg.lounge_id] || 0) + 1;
            }
          }
        }
        // Ensure all lounges have an entry
        for (const id of loungeIds) {
          if (!(id in unreadCounts)) unreadCounts[id] = 0;
        }
      }

      // Sort by recent activity
      const loungesList = Array.from(allLoungesMap.values());
      loungesList.sort((a, b) => {
        const aTime = lastMessageTimestamps[a.id] || a.created_at;
        const bTime = lastMessageTimestamps[b.id] || b.created_at;
        return new Date(bTime).getTime() - new Date(aTime).getTime();
      });

      // Enrich — rooms the user owns or joined get unread_count and last_message_at
      const enriched: LoungeRoom[] = loungesList.map((l) => ({
        id: l.id,
        name: l.name,
        description: l.description ?? '',
        is_private: l.is_private ?? false,
        invite_code: l.invite_code ?? null,
        creator_id: l.creator_id,
        created_at: l.created_at,
        member_count: l.member_count ?? 0,
        unread_count: ownedOrJoinedIds.has(l.id) ? (unreadCounts[l.id] || 0) : undefined,
        last_message_at: lastMessageTimestamps[l.id],
      }));

      set({ lounges: enriched, loading: false });
    } catch {
      set({ loading: false });
    }
  },

  fetchMessages: async (loungeId: string) => {
    set({ currentLoungeId: loungeId, loading: true });
    try {
      const { data, error } = await supabase
        .from('lounge_messages')
        .select('id, lounge_id, user_id, content, type, reply_to_id, reply_to_username, reply_to_content, film_id, film_title, film_poster, created_at, profiles!lounge_messages_user_id_fkey(username, avatar_url)')
        .eq('lounge_id', loungeId)
        .order('created_at', { ascending: false })
        .limit(100);

      if (data && !error) {
        const messages: LoungeMessage[] = (data as LoungeMessageRow[]).reverse().map((m) => ({
          id: m.id,
          lounge_id: m.lounge_id,
          user_id: m.user_id,
          username: Array.isArray(m.profiles) ? m.profiles[0]?.username : m.profiles?.username ?? 'unknown',
          avatar_url: Array.isArray(m.profiles) ? m.profiles[0]?.avatar_url : m.profiles?.avatar_url,
          content: m.content,
          type: (m.type as LoungeMessage['type']) ?? 'text',
          reply_to_id: m.reply_to_id,
          reply_to_username: m.reply_to_username,
          reply_to_content: m.reply_to_content,
          film_id: m.film_id,
          film_title: m.film_title,
          film_poster: m.film_poster,
          created_at: m.created_at,
        }));
        set({ currentMessages: messages });
      }
    } catch { /* silent */ }
    set({ loading: false });
  },

  loadMoreMessages: async (loungeId: string) => {
    const current = get().currentMessages;
    if (current.length === 0) return;

    // The oldest message is at index 0 because fetchMessages reverses the chronological array
    const oldestMessage = current[0];
    if (oldestMessage.id.startsWith('optimistic')) return; // Safety

    try {
      const { data, error } = await supabase
        .from('lounge_messages')
        .select('id, lounge_id, user_id, content, type, reply_to_id, reply_to_username, reply_to_content, film_id, film_title, film_poster, created_at, profiles!lounge_messages_user_id_fkey(username, avatar_url)')
        .eq('lounge_id', loungeId)
        .lt('created_at', oldestMessage.created_at)
        .order('created_at', { ascending: false })
        .limit(100);

      if (data && data.length > 0 && !error) {
        const olderMessages: LoungeMessage[] = (data as LoungeMessageRow[]).reverse().map((m) => ({
          id: m.id,
          lounge_id: m.lounge_id,
          user_id: m.user_id,
          username: Array.isArray(m.profiles) ? m.profiles[0]?.username : m.profiles?.username ?? 'unknown',
          avatar_url: Array.isArray(m.profiles) ? m.profiles[0]?.avatar_url : m.profiles?.avatar_url,
          content: m.content,
          type: (m.type as LoungeMessage['type']) ?? 'text',
          reply_to_id: m.reply_to_id,
          reply_to_username: m.reply_to_username,
          reply_to_content: m.reply_to_content,
          film_id: m.film_id,
          film_title: m.film_title,
          film_poster: m.film_poster,
          created_at: m.created_at,
        }));

        // Prepend older messages
        set({ currentMessages: [...olderMessages, ...current] });
      }
    } catch { /* silent */ }
  },

  sendMessage: async (loungeId, content, type = 'text', meta = {}) => {
    const user = useAuthStore.getState().user;
    const ALLOWED_TYPES = ['text', 'film_share', 'log_share', 'system'] as const;
    const safeType = (ALLOWED_TYPES as readonly string[]).includes(type) ? type : 'text';
    if (!user || !content.trim()) return;

    // Throttle
    const now = Date.now();
    if (now - _lastSendAt < SEND_THROTTLE) return;
    _lastSendAt = now;

    set({ sending: true });

    // Optimistic insert
    const optimisticMsg: LoungeMessage = {
      id: `optimistic-${now}`,
      lounge_id: loungeId,
      user_id: user.id,
      username: user.username,
      content: content.trim().slice(0, 500),
      type: safeType as LoungeMessage['type'],
      created_at: new Date().toISOString(),
      ...meta,
    };

    set(s => ({
      currentMessages: [...s.currentMessages, optimisticMsg],
      sending: false,
    }));

    try {
      const { data, error } = await supabase.from('lounge_messages').insert([{
        lounge_id: loungeId,
        user_id: user.id,
        content: content.trim().slice(0, 500).replace(/<[^>]*>/g, ''),
        type: safeType,
        ...meta,
      }]).select('id, created_at').single();

      if (error) throw error;

      set(s => {
        const alreadyReplaced = s.currentMessages.some(m => m.id === data.id);
        if (alreadyReplaced) {
          return { currentMessages: s.currentMessages.filter(m => m.id !== optimisticMsg.id) };
        }
        return {
          currentMessages: s.currentMessages.map(m => 
            m.id === optimisticMsg.id 
              ? { ...m, id: data.id, created_at: data.created_at } 
              : m
          ).sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime())
        };
      });
    } catch {
      // Remove optimistic message on failure
      set(s => ({
        currentMessages: s.currentMessages.filter(m => m.id !== optimisticMsg.id),
      }));
      Alert.alert('Error', 'Failed to send message.');
    }
  },

  deleteMessage: async (messageId) => {
    const user = useAuthStore.getState().user;
    if (!user) return;

    const prev = get().currentMessages;
    set(s => ({ currentMessages: s.currentMessages.filter(m => m.id !== messageId) }));

    const { error } = await supabase.from('lounge_messages').delete()
      .eq('id', messageId)
      .eq('user_id', user.id);

    if (error) {
      set({ currentMessages: prev });
    }
  },

  createLounge: async (name, description, isPrivate) => {
    const user = useAuthStore.getState().user;
    if (!user) return null;

    const inviteCode = isPrivate
      ? Math.random().toString(36).slice(2, 8).toUpperCase()
      : null;

    const { data, error } = await supabase.from('lounges').insert([{
      name,
      description,
      is_private: isPrivate,
      invite_code: inviteCode,
      creator_id: user.id,
      member_count: 0, // Begins at 0; auto-join trigger increments to 1
    }]).select().single();

    if (error || !data) {
      Alert.alert('Error', 'Failed to create lounge.');
      return null;
    }

    // Auto-join
    await supabase.from('lounge_members').insert([{
      lounge_id: data.id,
      user_id: user.id,
    }]);

    await get().fetchLounges();
    return data.id;
  },

  joinLounge: async (inviteCode) => {
    const user = useAuthStore.getState().user;
    if (!user) return false;

    const { data: lounge } = await supabase
      .from('lounges')
      .select('id')
      .eq('invite_code', inviteCode.toUpperCase())
      .single();

    if (!lounge) {
      Alert.alert('Error', 'Invalid invite code.');
      return false;
    }

    const { error } = await supabase.from('lounge_members').insert([{
      lounge_id: lounge.id,
      user_id: user.id,
    }]);

    if (error && !error.message?.includes('duplicate')) {
      Alert.alert('Error', 'Failed to join lounge.');
      return false;
    }

    await get().fetchLounges();
    return true;
  },

  joinLoungeById: async (loungeId) => {
    const user = useAuthStore.getState().user;
    if (!user) return false;

    const { error } = await supabase.from('lounge_members').insert([{
      lounge_id: loungeId,
      user_id: user.id,
    }]);

    if (error && !error.message?.includes('duplicate')) {
      Alert.alert('Error', 'Failed to take a seat.');
      return false;
    }

    await get().fetchLounges();
    return true;
  },

  leaveLounge: async (loungeId) => {
    const user = useAuthStore.getState().user;
    if (!user) return;

    await supabase.from('lounge_members').delete()
      .eq('lounge_id', loungeId)
      .eq('user_id', user.id);

    set(s => ({ lounges: s.lounges.filter(l => l.id !== loungeId) }));
  },

  deleteLounge: async (loungeId) => {
    const user = useAuthStore.getState().user;
    if (!user) return;

    // Optimistic removal
    set(s => ({ lounges: s.lounges.filter(l => l.id !== loungeId) }));

    const { error } = await supabase.from('lounges').delete()
      .eq('id', loungeId)
      .eq('creator_id', user.id);

    if (error) {
      Alert.alert('Error', 'Failed to incinerate lounge.');
      await get().fetchLounges(); // Revert
    }
  },

  subscribeToLounge: (loungeId: string) => {
    const channel = supabase
      .channel(`lounge-${loungeId}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'lounge_messages',
          filter: `lounge_id=eq.${loungeId}`,
        },
        async (payload) => {
          const msg = payload.new as RawLoungePayload;
          // Ignore our own optimistic messages (they're already rendered)
          const existing = get().currentMessages.find(m => m.id === msg.id);
          if (existing) return;

          // Resolve username via cache — prevents N+1 queries in busy lounges
          const { username, avatar_url } = await resolveProfile(msg.user_id);

          const newMsg: LoungeMessage = {
            id: msg.id,
            lounge_id: msg.lounge_id,
            user_id: msg.user_id,
            username,
            avatar_url,
            content: msg.content,
            type: (msg.type ?? 'text') as LoungeMessage['type'],
            reply_to_id: msg.reply_to_id,
            reply_to_username: msg.reply_to_username,
            reply_to_content: msg.reply_to_content,
            film_id: msg.film_id,
            film_title: msg.film_title,
            film_poster: msg.film_poster,
            created_at: msg.created_at,
          };

          // Find the exact optimistic message and replace it
          set(s => {
            const optMatch = s.currentMessages.find(
              m => m.id.startsWith('optimistic-') && m.user_id === msg.user_id && m.content === msg.content
            );

            const messagesWithoutOpt = s.currentMessages.filter(m => m.id !== optMatch?.id && m.id !== newMsg.id);

            return {
              currentMessages: [...messagesWithoutOpt, newMsg].sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime()),
            };
          });
        }
      )
      .on(
        'postgres_changes',
        { event: 'DELETE', schema: 'public', table: 'lounge_messages', filter: `lounge_id=eq.${loungeId}` },
        (payload) => {
          const deletedId = (payload.old as RawLoungePayload)?.id;
          if (deletedId) {
            set(s => ({ currentMessages: s.currentMessages.filter(m => m.id !== deletedId) }));
          }
        }
      )
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  },

  markRead: async (loungeId) => {
    const user = useAuthStore.getState().user;
    if (!user) return;
    await supabase
      .from('lounge_members')
      .update({ last_read_at: new Date().toISOString() })
      .eq('lounge_id', loungeId)
      .eq('user_id', user.id);
  },
}));

