// ============================================================
// REELHOUSE — SHARED TYPE DEFINITIONS
// ============================================================

// ── Auth ──
export interface UserPreferences {
    social_visibility?: string
    privacy_endorsements?: string
    privacy_annotations?: string
    notif_follows?: boolean
    notif_endorsements?: boolean
    notif_comments?: boolean
    notif_system?: boolean
    [key: string]: unknown
}

export interface User {
    id: string
    username: string
    email?: string
    bio?: string
    avatar?: string
    avatar_url?: string
    role: 'free' | 'cinephile' | 'archivist' | 'auteur'
    tier?: 'free' | 'cinephile' | 'archivist' | 'auteur'
    displayName?: string
    display_name?: string
    persona?: string
    socialVisibility?: 'public' | 'members' | 'private'
    social_visibility?: string
    following?: string[]
    followers_count?: number
    following_count?: number
    isSocialPrivate?: boolean
    is_social_private?: boolean
    created_at?: string
    preferences?: UserPreferences
    is_banned?: boolean
    ban_reason?: string
    social_links?: Record<string, string> | Array<{title: string; url: string}>
}

// ── Film Log ──
export interface FilmLog {
    id: string
    filmId: number
    title: string
    film_title?: string
    poster?: string | null
    altPoster?: string | null | undefined
    year?: number
    rating: number
    status: 'watched' | 'rewatched' | 'abandoned' | string
    review?: string | null
    pullQuote?: string | null
    tags?: string[]
    director?: string | null
    directors?: string[]
    genres?: Array<{ id: number; name: string }> | number[]
    runtime?: number | null
    popularity?: number
    release_date?: string | null
    loggedAt?: string
    created_at?: string
    createdAt?: string
    user_id?: string
    // Half-life tracking
    genre_ids?: number[]
    format?: string | null
    watched_date?: string | null

    // UI mapping properties
    isSpoiler?: boolean
    watchedDate?: string | null
    watchedWith?: string | null
    privateNotes?: string | null
    abandonedReason?: string | null
    physicalMedia?: string | null
    isAutopsied?: boolean
    autopsy?: string | null
    editorialHeader?: string | null
    dropCap?: boolean
    videoUrl?: string | null
    // Viewing Chronicle — rewatch history stored in same log
    viewCount?: number
    viewingHistory?: Array<{
        date?: string
        rating: number
        review?: string
        watchedWith?: string | null
    }> | Record<string, number> | string | null
}

// ── Watchlist ──
export interface WatchlistItem {
